window.EXAM_VISUALS["k8s-kcna"] = {
  "questions": {
    "kcna-01": {
      "badge": "Control Plane Hub",
      "title": "kube-apiserver: Puerta de Enlace REST y Único Cliente de etcd",
      "titleEn": "kube-apiserver: Central REST Gateway & Sole etcd Client",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">CONTROL PLANE COMMUNICATION: KUBE-APISERVER AS THE CENTRAL HUB</text>\n  <!-- Clients on Left -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"130\" height=\"34\" rx=\"4\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <text x=\"12\" y=\"16\" fill=\"#38bdf8\" font-size=\"7.5\" font-weight=\"700\">kubectl / Users</text>\n    <text x=\"12\" y=\"27\" fill=\"#cbd5e1\" font-size=\"6.5\">CLI operations</text>\n    <rect x=\"0\" y=\"44\" width=\"130\" height=\"34\" rx=\"4\" fill=\"#1e293b\" stroke=\"#a78bfa\"/>\n    <text x=\"12\" y=\"60\" fill=\"#c4b5fd\" font-size=\"7.5\" font-weight=\"700\">kube-scheduler</text>\n    <text x=\"12\" y=\"71\" fill=\"#cbd5e1\" font-size=\"6.5\">Pod assignment</text>\n    <rect x=\"0\" y=\"88\" width=\"130\" height=\"34\" rx=\"4\" fill=\"#1e293b\" stroke=\"#34d399\"/>\n    <text x=\"12\" y=\"104\" fill=\"#6ee7b7\" font-size=\"7.5\" font-weight=\"700\">controller-manager</text>\n    <text x=\"12\" y=\"115\" fill=\"#cbd5e1\" font-size=\"6.5\">Control loops</text>\n    <rect x=\"0\" y=\"132\" width=\"130\" height=\"34\" rx=\"4\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n    <text x=\"12\" y=\"148\" fill=\"#fde68a\" font-size=\"7.5\" font-weight=\"700\">kubelet (Nodes)</text>\n    <text x=\"12\" y=\"159\" fill=\"#cbd5e1\" font-size=\"6.5\">Pod reporting</text>\n  </g>\n  <!-- Arrows to API Server -->\n  <g transform=\"translate(160, 60)\">\n    <line x1=\"0\" y1=\"2\" x2=\"65\" y2=\"40\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n    <line x1=\"0\" y1=\"46\" x2=\"65\" y2=\"45\" stroke=\"#a78bfa\" stroke-width=\"1.5\"/>\n    <line x1=\"0\" y1=\"90\" x2=\"65\" y2=\"50\" stroke=\"#34d399\" stroke-width=\"1.5\"/>\n    <line x1=\"0\" y1=\"134\" x2=\"65\" y2=\"55\" stroke=\"#f59e0b\" stroke-width=\"1.5\"/>\n    <polygon points=\"65,48 57,44 57,52\" fill=\"#60a5fa\"/>\n  </g>\n  <!-- API Server Center -->\n  <g transform=\"translate(230, 42)\">\n    <rect x=\"0\" y=\"0\" width=\"220\" height=\"170\" rx=\"6\" fill=\"#1e3a5f\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n    <rect x=\"0\" y=\"0\" width=\"220\" height=\"26\" rx=\"6\" fill=\"#1d4ed8\"/>\n    <text x=\"14\" y=\"17\" fill=\"#ffffff\" font-size=\"9\" font-weight=\"800\">kube-apiserver (REST API)</text>\n    <!-- Internal stages -->\n    <rect x=\"14\" y=\"34\" width=\"192\" height=\"26\" rx=\"3\" fill=\"#0f172a\" stroke=\"#60a5fa\"/>\n    <text x=\"22\" y=\"50\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"700\">1. Authentication (AuthN): Certs / JWT</text>\n    <rect x=\"14\" y=\"66\" width=\"192\" height=\"26\" rx=\"3\" fill=\"#0f172a\" stroke=\"#60a5fa\"/>\n    <text x=\"22\" y=\"82\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"700\">2. Authorization (AuthZ): RBAC Roles</text>\n    <rect x=\"14\" y=\"98\" width=\"192\" height=\"26\" rx=\"3\" fill=\"#0f172a\" stroke=\"#60a5fa\"/>\n    <text x=\"22\" y=\"114\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"700\">3. Admission: Mutating &amp; Validating</text>\n    <rect x=\"14\" y=\"130\" width=\"192\" height=\"28\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n    <text x=\"22\" y=\"148\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"800\">✓ OpenAPI Schema Validation</text>\n  </g>\n  <!-- Arrow from API Server to etcd only -->\n  <g transform=\"translate(455, 120)\">\n    <line x1=\"0\" y1=\"0\" x2=\"35\" y2=\"0\" stroke=\"#a78bfa\" stroke-width=\"2.5\"/>\n    <polygon points=\"35,0 27,-5 27,5\" fill=\"#a78bfa\"/>\n    <polygon points=\"0,0 8,-5 8,5\" fill=\"#a78bfa\"/>\n    <text x=\"18\" y=\"-7\" fill=\"#c4b5fd\" font-size=\"6.5\" font-weight=\"800\" text-anchor=\"middle\">gRPC</text>\n  </g>\n  <!-- etcd on Right -->\n  <g transform=\"translate(495, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"160\" height=\"165\" rx=\"6\" fill=\"#2e1065\" stroke=\"#a78bfa\" stroke-width=\"2\"/>\n    <rect x=\"0\" y=\"0\" width=\"160\" height=\"24\" rx=\"6\" fill=\"#6d28d9\"/>\n    <text x=\"12\" y=\"16\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">etcd (K8s State)</text>\n    <rect x=\"10\" y=\"32\" width=\"140\" height=\"52\" rx=\"3\" fill=\"#0f172a\" stroke=\"#c084fc\"/>\n    <text x=\"18\" y=\"48\" fill=\"#e9d5ff\" font-size=\"7.5\" font-weight=\"700\">Distributed Key-Value</text>\n    <text x=\"18\" y=\"60\" fill=\"#cbd5e1\" font-size=\"6.5\">Raft Consensus</text>\n    <text x=\"18\" y=\"72\" fill=\"#cbd5e1\" font-size=\"6.5\">Revision history</text>\n    <rect x=\"10\" y=\"92\" width=\"140\" height=\"60\" rx=\"3\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n    <text x=\"18\" y=\"108\" fill=\"#fca5a5\" font-size=\"7.5\" font-weight=\"800\">EXCLUSIVE ACCESS:</text>\n    <text x=\"18\" y=\"122\" fill=\"#fecaca\" font-size=\"6.5\">No other component</text>\n    <text x=\"18\" y=\"132\" fill=\"#fecaca\" font-size=\"6.5\">can query or write</text>\n    <text x=\"18\" y=\"142\" fill=\"#fecaca\" font-size=\"6.5\">directly to etcd.</text>\n  </g>\n</svg>",
      "caption": "El kube-apiserver es el núcleo de comunicación del clúster: intercepta, autentica (AuthN), autoriza (AuthZ con RBAC) y valida todas las operaciones de usuarios y controladores. Es el único componente autorizado para dialogar directamente con etcd.",
      "captionEn": "kube-apiserver acts as the central communication hub: it handles AuthN, RBAC AuthZ, and admission validation before persisting cluster state to etcd."
    },
    "kcna-02": {
      "badge": "Raft Quorum",
      "title": "Consenso Raft en etcd: Quórum Impar y Tolerancia a Fallos",
      "titleEn": "Raft Consensus in etcd: Odd Quorum & Fault Tolerance",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">ETCD TOPOLOGY: RAFT STRICT-MAJORITY QUORUM (N/2)+1</text>\n  <!-- 3 Node Cluster -->\n  <g transform=\"translate(25, 42)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"170\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"12\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">RECOMMENDED CLUSTER: 3 MEMBERS (Quorum = 2)</text>\n    <!-- Nodes -->\n    <g transform=\"translate(14, 30)\">\n      <rect x=\"0\" y=\"0\" width=\"85\" height=\"60\" rx=\"4\" fill=\"#064e3b\" stroke=\"#34d399\"/>\n      <text x=\"8\" y=\"18\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"800\">etcd-1 (Leader)</text>\n      <text x=\"8\" y=\"32\" fill=\"#cbd5e1\" font-size=\"6.5\">Term: 4</text>\n      <text x=\"8\" y=\"44\" fill=\"#34d399\" font-size=\"6.5\">✓ Raft Vote</text>\n      <rect x=\"96\" y=\"0\" width=\"85\" height=\"60\" rx=\"4\" fill=\"#064e3b\" stroke=\"#34d399\"/>\n      <text x=\"104\" y=\"18\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"800\">etcd-2 (Follower)</text>\n      <text x=\"104\" y=\"32\" fill=\"#cbd5e1\" font-size=\"6.5\">Term: 4</text>\n      <text x=\"104\" y=\"44\" fill=\"#34d399\" font-size=\"6.5\">✓ Raft Vote</text>\n      <rect x=\"192\" y=\"0\" width=\"85\" height=\"60\" rx=\"4\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n      <text x=\"200\" y=\"18\" fill=\"#fca5a5\" font-size=\"7.5\" font-weight=\"800\">etcd-3 (Down)</text>\n      <text x=\"200\" y=\"32\" fill=\"#cbd5e1\" font-size=\"6.5\">Timeout</text>\n      <text x=\"200\" y=\"44\" fill=\"#ef4444\" font-size=\"6.5\">✗ No response</text>\n    </g>\n    <!-- Quorum Evaluation -->\n    <rect x=\"14\" y=\"100\" width=\"277\" height=\"58\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"22\" y=\"118\" fill=\"#a7f3d0\" font-size=\"8\" font-weight=\"700\">Quorum Evaluation: 2 of 3 votes active (66%)</text>\n    <text x=\"22\" y=\"132\" fill=\"#cbd5e1\" font-size=\"7\">• The strict majority rule is met: (3/2)+1 = 2.</text>\n    <text x=\"22\" y=\"144\" fill=\"#34d399\" font-size=\"7\">✓ The cluster tolerates 1 failed node and keeps committing writes.</text>\n  </g>\n  <!-- Even Nodes Comparison -->\n  <g transform=\"translate(350, 42)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"170\" rx=\"5\" fill=\"#1e293b\" stroke=\"#ef4444\"/>\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"22\" rx=\"5\" fill=\"#991b1b\"/>\n    <text x=\"12\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">WHY NOT AN EVEN NUMBER? (E.g. 4 Nodes)</text>\n    <g transform=\"translate(14, 30)\">\n      <rect x=\"0\" y=\"0\" width=\"62\" height=\"50\" rx=\"3\" fill=\"#1e3a5f\" stroke=\"#38bdf8\"/>\n      <text x=\"6\" y=\"16\" fill=\"#93c5fd\" font-size=\"6.5\" font-weight=\"700\">etcd-1</text>\n      <text x=\"6\" y=\"28\" fill=\"#cbd5e1\" font-size=\"6\">Vote 1</text>\n      <rect x=\"70\" y=\"0\" width=\"62\" height=\"50\" rx=\"3\" fill=\"#1e3a5f\" stroke=\"#38bdf8\"/>\n      <text x=\"76\" y=\"16\" fill=\"#93c5fd\" font-size=\"6.5\" font-weight=\"700\">etcd-2</text>\n      <text x=\"76\" y=\"28\" fill=\"#cbd5e1\" font-size=\"6\">Vote 2</text>\n      <rect x=\"140\" y=\"0\" width=\"62\" height=\"50\" rx=\"3\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n      <text x=\"146\" y=\"16\" fill=\"#fca5a5\" font-size=\"6.5\" font-weight=\"700\">etcd-3</text>\n      <text x=\"146\" y=\"28\" fill=\"#cbd5e1\" font-size=\"6\">Down</text>\n      <rect x=\"210\" y=\"0\" width=\"67\" height=\"50\" rx=\"3\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n      <text x=\"216\" y=\"16\" fill=\"#fca5a5\" font-size=\"6.5\" font-weight=\"700\">etcd-4</text>\n      <text x=\"216\" y=\"28\" fill=\"#cbd5e1\" font-size=\"6\">Down</text>\n    </g>\n    <rect x=\"14\" y=\"90\" width=\"277\" height=\"68\" rx=\"3\" fill=\"#0f172a\" stroke=\"#ef4444\"/>\n    <text x=\"22\" y=\"108\" fill=\"#fca5a5\" font-size=\"8\" font-weight=\"800\">4 Nodes require Quorum = (4/2)+1 = 3</text>\n    <text x=\"22\" y=\"122\" fill=\"#cbd5e1\" font-size=\"7\">• If 2 nodes fail, 2 votes remain: No quorum!</text>\n    <text x=\"22\" y=\"134\" fill=\"#cbd5e1\" font-size=\"7\">• 4 nodes tolerate EXACTLY 1 failure, same as 3 nodes.</text>\n    <text x=\"22\" y=\"146\" fill=\"#f87171\" font-size=\"7\">⚠️ Adding an even node wastes resources without gaining resilience.</text>\n  </g>\n</svg>",
      "caption": "Quórum en etcd con Raft: se requiere una mayoría estricta de (N/2)+1 votos. Un clúster de 3 nodos tolera 1 fallo con quórum 2; 4 nodos consumen más recursos pero siguen tolerando solo 1 fallo (quórum 3). Por ello siempre se eligen tamaños impares (3, 5).",
      "captionEn": "etcd Raft consensus requires a strict majority quorum of (N/2)+1. A 3-node cluster tolerates 1 failure; 4 nodes still tolerate only 1 failure while consuming extra resources. Hence, odd counts are always used."
    },
    "kcna-03": {
      "badge": "Scheduling Pipeline",
      "title": "kube-scheduler: Pipeline de Filtrado (Predicates) y Priorización (Scoring)",
      "titleEn": "kube-scheduler: Filtering (Predicates) & Scoring Pipeline",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">KUBE-SCHEDULER: NODE FILTERING AND SCORING PIPELINE</text>\n  <!-- Incoming Pod -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"110\" height=\"160\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <text x=\"12\" y=\"20\" fill=\"#38bdf8\" font-size=\"8\" font-weight=\"800\">POD PENDING</text>\n    <rect x=\"10\" y=\"30\" width=\"90\" height=\"40\" rx=\"3\" fill=\"#0f172a\" stroke=\"#60a5fa\"/>\n    <text x=\"16\" y=\"46\" fill=\"#ffffff\" font-size=\"7\" font-weight=\"700\">ml-worker</text>\n    <text x=\"16\" y=\"58\" fill=\"#93c5fd\" font-size=\"6\">CPU: 4 cores</text>\n    <text x=\"16\" y=\"67\" fill=\"#93c5fd\" font-size=\"6\">Mem: 16Gi</text>\n    <text x=\"10\" y=\"90\" fill=\"#cbd5e1\" font-size=\"6.5\">Requirements:</text>\n    <text x=\"10\" y=\"102\" fill=\"#cbd5e1\" font-size=\"6.5\">• GPU == true</text>\n    <text x=\"10\" y=\"114\" fill=\"#cbd5e1\" font-size=\"6.5\">• No taints</text>\n    <text x=\"10\" y=\"140\" fill=\"#f59e0b\" font-size=\"6.5\">nodeName: \"\"</text>\n  </g>\n  <!-- Phase 1: Filtering -->\n  <g transform=\"translate(155, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"180\" height=\"160\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n    <rect x=\"0\" y=\"0\" width=\"180\" height=\"22\" rx=\"5\" fill=\"#b45309\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">1. FILTERING (Predicates)</text>\n    <text x=\"10\" y=\"36\" fill=\"#fde68a\" font-size=\"7\" font-weight=\"700\">Discards non-viable nodes</text>\n    <!-- Node checks -->\n    <rect x=\"10\" y=\"44\" width=\"160\" height=\"26\" rx=\"2\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n    <text x=\"16\" y=\"58\" fill=\"#a7f3d0\" font-size=\"6.5\">node-01: CPU ok, GPU ok ➔ PASS</text>\n    <rect x=\"10\" y=\"74\" width=\"160\" height=\"26\" rx=\"2\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n    <text x=\"16\" y=\"88\" fill=\"#fca5a5\" font-size=\"6.5\">node-02: Insufficient memory ➔ DISCARDED</text>\n    <rect x=\"10\" y=\"104\" width=\"160\" height=\"26\" rx=\"2\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n    <text x=\"16\" y=\"118\" fill=\"#a7f3d0\" font-size=\"6.5\">node-03: CPU ok, GPU ok ➔ PASS</text>\n    <rect x=\"10\" y=\"134\" width=\"160\" height=\"22\" rx=\"2\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n    <text x=\"16\" y=\"148\" fill=\"#fca5a5\" font-size=\"6.5\">node-04: Taint NoSchedule ➔ DISCARDED</text>\n  </g>\n  <!-- Phase 2: Scoring -->\n  <g transform=\"translate(355, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"180\" height=\"160\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <rect x=\"0\" y=\"0\" width=\"180\" height=\"22\" rx=\"5\" fill=\"#0284c7\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">2. SCORING</text>\n    <text x=\"10\" y=\"36\" fill=\"#7dd3fc\" font-size=\"7\" font-weight=\"700\">Scores viable candidates</text>\n    <!-- Scoring bars -->\n    <g transform=\"translate(10, 48)\">\n      <rect x=\"0\" y=\"0\" width=\"160\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n      <text x=\"8\" y=\"15\" fill=\"#ffffff\" font-size=\"7\" font-weight=\"700\">node-01 (Score: 78)</text>\n      <rect x=\"8\" y=\"22\" width=\"110\" height=\"12\" rx=\"2\" fill=\"#38bdf8\"/>\n      <text x=\"125\" y=\"32\" fill=\"#94a3b8\" font-size=\"6\">78 pts</text>\n    </g>\n    <g transform=\"translate(10, 98)\">\n      <rect x=\"0\" y=\"0\" width=\"160\" height=\"52\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n      <text x=\"8\" y=\"16\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"800\">node-03 (Score: 94) ★</text>\n      <rect x=\"8\" y=\"24\" width=\"145\" height=\"14\" rx=\"2\" fill=\"#10b981\"/>\n      <text x=\"8\" y=\"46\" fill=\"#d1fae5\" font-size=\"6\">Higher zone affinity and thermal balance</text>\n    </g>\n  </g>\n  <!-- Final Assignment -->\n  <g transform=\"translate(555, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"100\" height=\"160\" rx=\"5\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n    <text x=\"10\" y=\"20\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"800\">BINDING</text>\n    <text x=\"10\" y=\"45\" fill=\"#ffffff\" font-size=\"7\">Assigns to:</text>\n    <text x=\"10\" y=\"60\" fill=\"#34d399\" font-size=\"8\" font-weight=\"800\">node-03</text>\n    <rect x=\"10\" y=\"75\" width=\"80\" height=\"70\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"14\" y=\"92\" fill=\"#cbd5e1\" font-size=\"6.5\">kubelet on</text>\n    <text x=\"14\" y=\"104\" fill=\"#a7f3d0\" font-size=\"6.5\">node-03</text>\n    <text x=\"14\" y=\"116\" fill=\"#cbd5e1\" font-size=\"6.5\">receives PodSpec</text>\n    <text x=\"14\" y=\"128\" fill=\"#34d399\" font-size=\"6.5\">and creates the</text>\n    <text x=\"14\" y=\"139\" fill=\"#34d399\" font-size=\"6.5\">containers</text>\n  </g>\n</svg>",
      "caption": "kube-scheduler ejecuta un pipeline de dos pasos: primero el Filtrado (descarta nodos sin CPU/memoria o con taints no tolerados) y luego la Priorización (calcula una puntuación de 0 a 100 ponderando afinidad y dispersión). El nodo ganador recibe el pod.",
      "captionEn": "kube-scheduler two-stage pipeline: Filtering excludes ineligible nodes; Scoring ranks remaining candidates based on resource balance and affinity. The top-scoring node binds the pod."
    },
    "kcna-04": {
      "badge": "Reconciliation",
      "title": "Bucle de Reconciliación del Controller Manager",
      "titleEn": "Controller Manager Continuous Reconciliation Loop",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">KUBE-CONTROLLER-MANAGER: CONTINUOUS RECONCILIATION LOOP</text>\n  <!-- Circular flow diagram -->\n  <g transform=\"translate(40, 45)\">\n    <!-- Desired State -->\n    <rect x=\"0\" y=\"0\" width=\"165\" height=\"70\" rx=\"5\" fill=\"#1e3a5f\" stroke=\"#38bdf8\"/>\n    <text x=\"12\" y=\"20\" fill=\"#38bdf8\" font-size=\"8\" font-weight=\"800\">1. DESIRED STATE (Spec)</text>\n    <text x=\"12\" y=\"36\" fill=\"#cbd5e1\" font-size=\"7\">Declared in Git / YAML</text>\n    <text x=\"12\" y=\"50\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"700\">Deployment replicas: 4</text>\n    <!-- Arrow Right -->\n    <line x1=\"165\" y1=\"35\" x2=\"225\" y2=\"35\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n    <polygon points=\"225,35 217,30 217,40\" fill=\"#38bdf8\"/>\n    <!-- Controller Comparison -->\n    <rect x=\"225\" y=\"0\" width=\"200\" height=\"70\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n    <text x=\"12\" y=\"20\" fill=\"#fbbf24\" font-size=\"8\" font-weight=\"800\">2. CONTROLLER (Diff)</text>\n    <text x=\"12\" y=\"34\" fill=\"#cbd5e1\" font-size=\"7\">Compares Desired vs Actual:</text>\n    <text x=\"12\" y=\"48\" fill=\"#fca5a5\" font-size=\"7\">Desired: 4 | Observed actual: 3</text>\n    <text x=\"12\" y=\"60\" fill=\"#f59e0b\" font-size=\"7\" font-weight=\"700\">➔ Detects Drift (Delta = -1)!</text>\n    <!-- Arrow Right -->\n    <line x1=\"425\" y1=\"35\" x2=\"480\" y2=\"35\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n    <polygon points=\"480,35 472,30 472,40\" fill=\"#f59e0b\"/>\n    <!-- Corrective Action -->\n    <rect x=\"480\" y=\"0\" width=\"160\" height=\"70\" rx=\"5\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n    <text x=\"12\" y=\"20\" fill=\"#a7f3d0\" font-size=\"8\" font-weight=\"800\">3. REMEDIATION ACTION</text>\n    <text x=\"12\" y=\"36\" fill=\"#cbd5e1\" font-size=\"7\">Calls the kube-apiserver:</text>\n    <text x=\"12\" y=\"50\" fill=\"#34d399\" font-size=\"7.5\" font-weight=\"700\">POST /api/v1/pods</text>\n    <text x=\"12\" y=\"62\" fill=\"#d1fae5\" font-size=\"6.5\">Creates 1 pod to restore 4</text>\n    <!-- Feedback loop below -->\n    <g transform=\"translate(0, 95)\">\n      <rect x=\"0\" y=\"0\" width=\"640\" height=\"60\" rx=\"5\" fill=\"#0f172a\" stroke=\"#334155\"/>\n      <text x=\"20\" y=\"22\" fill=\"#94a3b8\" font-size=\"8\" font-weight=\"700\">CONTROLLERS BUILT INTO THE BINARY:</text>\n      <text x=\"20\" y=\"38\" fill=\"#cbd5e1\" font-size=\"7\">• Node Lifecycle Controller · ReplicaSet Controller · Deployment Controller · EndpointSlice Controller</text>\n      <text x=\"20\" y=\"50\" fill=\"#a7f3d0\" font-size=\"7\">Principle: The system never sleeps; it actively converges toward the desired state without manual commands.</text>\n    </g>\n  </g>\n</svg>",
      "caption": "El kube-controller-manager implementa la promesa declarativa de Kubernetes: bucles infinitos observan el estado real, lo comparan con el estado deseado en etcd y ejecutan operaciones correctivas (como crear pods sustitutos) de forma autónoma.",
      "captionEn": "kube-controller-manager powers Kubernetes declarative model: perpetual reconciliation loops observe live state, compare against etcd specifications, and trigger corrective operations automatically."
    },
    "kcna-06": {
      "badge": "Worker Node",
      "title": "Anatomía Interna del Worker Node: Kubelet, CRI y Kube-Proxy",
      "titleEn": "Worker Node Internals: Kubelet, CRI Runtime & Kube-Proxy",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">WORKER NODE COMPONENTS: KUBELET ➔ CRI ➔ RUNTIME INTERACTION</text>\n  <!-- Kubelet Box -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"180\" height=\"160\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"180\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">KUBELET (Host Daemon)</text>\n    <text x=\"10\" y=\"38\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">Responsibilities:</text>\n    <text x=\"10\" y=\"52\" fill=\"#cbd5e1\" font-size=\"6.5\">• Receives PodSpecs from the apiserver</text>\n    <text x=\"10\" y=\"64\" fill=\"#cbd5e1\" font-size=\"6.5\">• Runs Probes</text>\n    <text x=\"10\" y=\"76\" fill=\"#cbd5e1\" font-size=\"6.5\">• Mounts volumes and Secrets</text>\n    <text x=\"10\" y=\"88\" fill=\"#cbd5e1\" font-size=\"6.5\">• Reports NodeStatus (Ready)</text>\n    <rect x=\"10\" y=\"104\" width=\"160\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"16\" y=\"120\" fill=\"#34d399\" font-size=\"7\" font-weight=\"700\">CRI Client (gRPC):</text>\n    <text x=\"16\" y=\"134\" fill=\"#cbd5e1\" font-size=\"6.5\">/run/containerd/containerd.sock</text>\n  </g>\n  <!-- CRI Arrow -->\n  <g transform=\"translate(210, 115)\">\n    <line x1=\"0\" y1=\"0\" x2=\"35\" y2=\"0\" stroke=\"#06b6d4\" stroke-width=\"2.5\"/>\n    <polygon points=\"35,0 27,-5 27,5\" fill=\"#06b6d4\"/>\n    <text x=\"18\" y=\"-7\" fill=\"#67e8f9\" font-size=\"6.5\" font-weight=\"700\" text-anchor=\"middle\">gRPC</text>\n  </g>\n  <!-- Container Runtime Box -->\n  <g transform=\"translate(250, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"190\" height=\"160\" rx=\"5\" fill=\"#1e293b\" stroke=\"#06b6d4\"/>\n    <rect x=\"0\" y=\"0\" width=\"190\" height=\"22\" rx=\"5\" fill=\"#0891b2\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">CRI RUNTIME (containerd)</text>\n    <text x=\"10\" y=\"38\" fill=\"#67e8f9\" font-size=\"7.5\" font-weight=\"700\">OCI Container Engine</text>\n    <rect x=\"10\" y=\"48\" width=\"170\" height=\"34\" rx=\"3\" fill=\"#0f172a\" stroke=\"#06b6d4\"/>\n    <text x=\"16\" y=\"62\" fill=\"#ffffff\" font-size=\"7\">Image Service:</text>\n    <text x=\"16\" y=\"73\" fill=\"#cbd5e1\" font-size=\"6.5\">Pulls images from OCI Registry</text>\n    <rect x=\"10\" y=\"88\" width=\"170\" height=\"58\" rx=\"3\" fill=\"#0f172a\" stroke=\"#06b6d4\"/>\n    <text x=\"16\" y=\"102\" fill=\"#ffffff\" font-size=\"7\">Runtime Service (runc):</text>\n    <text x=\"16\" y=\"114\" fill=\"#cbd5e1\" font-size=\"6.5\">• Configures cgroups (CPU / Mem)</text>\n    <text x=\"16\" y=\"125\" fill=\"#cbd5e1\" font-size=\"6.5\">• Isolates Linux namespaces</text>\n    <text x=\"16\" y=\"136\" fill=\"#cbd5e1\" font-size=\"6.5\">• Invokes CNI for veth interface</text>\n  </g>\n  <!-- Kube-proxy and Pods on Right -->\n  <g transform=\"translate(450, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"205\" height=\"160\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n    <rect x=\"0\" y=\"0\" width=\"205\" height=\"22\" rx=\"5\" fill=\"#b45309\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">KUBE-PROXY &amp; LOCAL PODS</text>\n    <!-- kube-proxy -->\n    <rect x=\"10\" y=\"30\" width=\"185\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f59e0b\"/>\n    <text x=\"18\" y=\"45\" fill=\"#fde68a\" font-size=\"7.5\" font-weight=\"700\">kube-proxy (Node Networking):</text>\n    <text x=\"18\" y=\"57\" fill=\"#cbd5e1\" font-size=\"6.5\">Programs iptables / IPVS in the kernel</text>\n    <text x=\"18\" y=\"67\" fill=\"#cbd5e1\" font-size=\"6.5\">Maps ClusterIP ➔ actual Pod IP</text>\n    <!-- Pods running -->\n    <g transform=\"translate(10, 80)\">\n      <rect x=\"0\" y=\"0\" width=\"88\" height=\"68\" rx=\"3\" fill=\"#064e3b\" stroke=\"#34d399\"/>\n      <text x=\"8\" y=\"16\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"700\">Pod A</text>\n      <text x=\"8\" y=\"28\" fill=\"#cbd5e1\" font-size=\"6\">IP: 10.244.2.14</text>\n      <text x=\"8\" y=\"42\" fill=\"#34d399\" font-size=\"6\">Pause + App</text>\n      <text x=\"8\" y=\"56\" fill=\"#a7f3d0\" font-size=\"6\">cgroup: Limits</text>\n      <rect x=\"96\" y=\"0\" width=\"89\" height=\"68\" rx=\"3\" fill=\"#064e3b\" stroke=\"#34d399\"/>\n      <text x=\"104\" y=\"16\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"700\">Pod B</text>\n      <text x=\"104\" y=\"28\" fill=\"#cbd5e1\" font-size=\"6\">IP: 10.244.2.15</text>\n      <text x=\"104\" y=\"42\" fill=\"#34d399\" font-size=\"6\">Pause + Sidecar</text>\n      <text x=\"104\" y=\"56\" fill=\"#a7f3d0\" font-size=\"6\">cgroup: Limits</text>\n    </g>\n  </g>\n</svg>",
      "caption": "Anatomía del nodo worker: el kubelet dialoga vía gRPC (CRI) con containerd para gestionar imágenes y contenedores OCI; a su vez, kube-proxy programa las reglas iptables/IPVS para que los pods atiendan tráfico de Services.",
      "captionEn": "Worker node internals: kubelet interacts via gRPC CRI with containerd to launch OCI containers; concurrently, kube-proxy configures iptables/IPVS routing rules for Services."
    },
    "kcna-07": {
      "badge": "Enrutamiento kube-proxy",
      "title": "kube-proxy: Enrutamiento NAT con iptables e IPVS",
      "titleEn": "kube-proxy: NAT Packet Routing via iptables and IPVS",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">KUBE-PROXY: TRANSLATING CLUSTERIP TO REAL ENDPOINTS</text>\n  <!-- Incoming request -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"135\" height=\"160\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <text x=\"10\" y=\"20\" fill=\"#38bdf8\" font-size=\"8\" font-weight=\"800\">CLIENT REQUEST</text>\n    <rect x=\"10\" y=\"32\" width=\"115\" height=\"50\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"16\" y=\"48\" fill=\"#ffffff\" font-size=\"7\">Destination:</text>\n    <text x=\"16\" y=\"60\" fill=\"#38bdf8\" font-size=\"7.5\" font-weight=\"700\">Virtual ClusterIP</text>\n    <text x=\"16\" y=\"72\" fill=\"#cbd5e1\" font-size=\"6.5\">10.96.0.10:80</text>\n    <rect x=\"10\" y=\"92\" width=\"115\" height=\"55\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"16\" y=\"108\" fill=\"#94a3b8\" font-size=\"6.5\">The virtual IP</text>\n    <text x=\"16\" y=\"120\" fill=\"#94a3b8\" font-size=\"6.5\">does NOT answer ping,</text>\n    <text x=\"16\" y=\"132\" fill=\"#94a3b8\" font-size=\"6.5\">it lives in NAT rules.</text>\n  </g>\n  <!-- Arrow -->\n  <g transform=\"translate(165, 120)\">\n    <line x1=\"0\" y1=\"0\" x2=\"35\" y2=\"0\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n    <polygon points=\"35,0 27,-5 27,5\" fill=\"#38bdf8\"/>\n  </g>\n  <!-- Kernel Table Center -->\n  <g transform=\"translate(205, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"260\" height=\"160\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n    <rect x=\"0\" y=\"0\" width=\"260\" height=\"22\" rx=\"5\" fill=\"#b45309\"/>\n    <text x=\"12\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">LINUX KERNEL (Programmed by kube-proxy)</text>\n    <!-- iptables chains -->\n    <rect x=\"12\" y=\"30\" width=\"236\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f59e0b\"/>\n    <text x=\"20\" y=\"45\" fill=\"#fde68a\" font-size=\"7.5\" font-weight=\"700\">KUBE-SERVICES chain ➔ KUBE-SVC-XYZ</text>\n    <text x=\"20\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6.5\">Intercepts packets destined for 10.96.0.10:80</text>\n    <!-- DNAT Probability -->\n    <rect x=\"12\" y=\"80\" width=\"236\" height=\"70\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n    <text x=\"20\" y=\"96\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">DNAT rule with probabilistic balancing:</text>\n    <text x=\"20\" y=\"110\" fill=\"#cbd5e1\" font-size=\"6.5\">• 33% probability ➔ Pod 1 (10.244.1.10:8080)</text>\n    <text x=\"20\" y=\"122\" fill=\"#cbd5e1\" font-size=\"6.5\">• 50% probability ➔ Pod 2 (10.244.2.15:8080)</text>\n    <text x=\"20\" y=\"134\" fill=\"#cbd5e1\" font-size=\"6.5\">• 100% remaining ➔ Pod 3 (10.244.3.22:8080)</text>\n  </g>\n  <!-- Arrow -->\n  <g transform=\"translate(470, 120)\">\n    <line x1=\"0\" y1=\"0\" x2=\"35\" y2=\"0\" stroke=\"#10b981\" stroke-width=\"2.5\"/>\n    <polygon points=\"35,0 27,-5 27,5\" fill=\"#10b981\"/>\n  </g>\n  <!-- Selected Endpoint Right -->\n  <g transform=\"translate(510, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"145\" height=\"160\" rx=\"5\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n    <text x=\"10\" y=\"20\" fill=\"#a7f3d0\" font-size=\"8\" font-weight=\"800\">POD ENDPOINT</text>\n    <rect x=\"10\" y=\"32\" width=\"125\" height=\"50\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"16\" y=\"48\" fill=\"#ffffff\" font-size=\"7\">Real Pod IP:</text>\n    <text x=\"16\" y=\"62\" fill=\"#34d399\" font-size=\"7.5\" font-weight=\"800\">10.244.2.15:8080</text>\n    <text x=\"16\" y=\"73\" fill=\"#cbd5e1\" font-size=\"6\">Network namespace</text>\n    <rect x=\"10\" y=\"92\" width=\"125\" height=\"55\" rx=\"3\" fill=\"#0f172a\" stroke=\"#334155\"/>\n    <text x=\"16\" y=\"108\" fill=\"#a7f3d0\" font-size=\"6.5\">✓ Packet delivered</text>\n    <text x=\"16\" y=\"120\" fill=\"#cbd5e1\" font-size=\"6.5\">Response leaves with</text>\n    <text x=\"16\" y=\"132\" fill=\"#cbd5e1\" font-size=\"6.5\">reverse un-NAT.</text>\n  </g>\n</svg>",
      "caption": "kube-proxy no es un proxy de aplicación en línea por donde fluyan los datos; en su lugar programa reglas DNAT en iptables o IPVS en el kernel. Cuando llega un paquete para ClusterIP, el kernel reescribe la IP destino hacia un pod real.",
      "captionEn": "kube-proxy does not forward user traffic in user space; it programs kernel DNAT rules (iptables/IPVS) so the Linux network stack rewrites the virtual ClusterIP to a healthy pod endpoint."
    },
    "kcna-09": {
      "badge": "CRI Stack",
      "title": "Pila de Ejecución OCI: Kubelet ➔ CRI ➔ containerd ➔ runc",
      "titleEn": "Container Runtime Stack: Kubelet ➔ CRI ➔ containerd ➔ runc",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">OCI EXECUTION STACK: FROM THE KUBELET TO THE CONTAINER IN THE KERNEL</text>\n  <g transform=\"translate(25, 45)\">\n    <!-- Layer 1: Kubelet -->\n    <rect x=\"0\" y=\"0\" width=\"135\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#3b82f6\"/>\n    <text x=\"10\" y=\"20\" fill=\"#60a5fa\" font-size=\"8\" font-weight=\"800\">1. KUBELET</text>\n    <text x=\"10\" y=\"34\" fill=\"#cbd5e1\" font-size=\"6.5\">Node orchestrator</text>\n    <rect x=\"10\" y=\"44\" width=\"115\" height=\"40\" rx=\"3\" fill=\"#0f172a\" stroke=\"#3b82f6\"/>\n    <text x=\"16\" y=\"58\" fill=\"#ffffff\" font-size=\"7\">Receives PodSpec</text>\n    <text x=\"16\" y=\"70\" fill=\"#93c5fd\" font-size=\"6\">YAML declaration</text>\n    <rect x=\"10\" y=\"94\" width=\"115\" height=\"45\" rx=\"3\" fill=\"#1e3a5f\"/>\n    <text x=\"16\" y=\"110\" fill=\"#93c5fd\" font-size=\"6.5\" font-weight=\"700\">CRI gRPC Client</text>\n    <text x=\"16\" y=\"122\" fill=\"#cbd5e1\" font-size=\"6\">RunPodSandbox()</text>\n    <text x=\"16\" y=\"132\" fill=\"#cbd5e1\" font-size=\"6\">CreateContainer()</text>\n  </g>\n  <!-- Arrow -->\n  <g transform=\"translate(165, 115)\">\n    <line x1=\"0\" y1=\"0\" x2=\"25\" y2=\"0\" stroke=\"#06b6d4\" stroke-width=\"2\"/>\n    <polygon points=\"25,0 18,-4 18,4\" fill=\"#06b6d4\"/>\n    <text x=\"12\" y=\"-6\" fill=\"#06b6d4\" font-size=\"6\" text-anchor=\"middle\">CRI</text>\n  </g>\n  <!-- Layer 2: containerd -->\n  <g transform=\"translate(195, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"145\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#06b6d4\"/>\n    <text x=\"10\" y=\"20\" fill=\"#67e8f9\" font-size=\"8\" font-weight=\"800\">2. CRI RUNTIME</text>\n    <text x=\"10\" y=\"34\" fill=\"#cbd5e1\" font-size=\"6.5\">containerd / CRI-O</text>\n    <rect x=\"10\" y=\"44\" width=\"125\" height=\"36\" rx=\"3\" fill=\"#0f172a\" stroke=\"#06b6d4\"/>\n    <text x=\"16\" y=\"58\" fill=\"#ffffff\" font-size=\"7\">Image Management</text>\n    <text x=\"16\" y=\"68\" fill=\"#67e8f9\" font-size=\"6\">Pull / Unpacking</text>\n    <rect x=\"10\" y=\"90\" width=\"125\" height=\"48\" rx=\"3\" fill=\"#0f172a\" stroke=\"#06b6d4\"/>\n    <text x=\"16\" y=\"106\" fill=\"#ffffff\" font-size=\"7\">containerd-shim</text>\n    <text x=\"16\" y=\"118\" fill=\"#cbd5e1\" font-size=\"6\">Holds stdin/stdout</text>\n    <text x=\"16\" y=\"128\" fill=\"#cbd5e1\" font-size=\"6\">Survives restart</text>\n  </g>\n  <!-- Arrow -->\n  <g transform=\"translate(345, 115)\">\n    <line x1=\"0\" y1=\"0\" x2=\"25\" y2=\"0\" stroke=\"#a78bfa\" stroke-width=\"2\"/>\n    <polygon points=\"25,0 18,-4 18,4\" fill=\"#a78bfa\"/>\n    <text x=\"12\" y=\"-6\" fill=\"#a78bfa\" font-size=\"6\" text-anchor=\"middle\">OCI</text>\n  </g>\n  <!-- Layer 3: OCI Runtime runc -->\n  <g transform=\"translate(375, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"135\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#a78bfa\"/>\n    <text x=\"10\" y=\"20\" fill=\"#c4b5fd\" font-size=\"8\" font-weight=\"800\">3. OCI LOW-LEVEL</text>\n    <text x=\"10\" y=\"34\" fill=\"#cbd5e1\" font-size=\"6.5\">runc / crun</text>\n    <rect x=\"10\" y=\"44\" width=\"115\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#a78bfa\"/>\n    <text x=\"16\" y=\"58\" fill=\"#ffffff\" font-size=\"7\">OCI Spec</text>\n    <text x=\"16\" y=\"70\" fill=\"#c4b5fd\" font-size=\"6\">rootfs + config.json</text>\n    <rect x=\"10\" y=\"94\" width=\"115\" height=\"45\" rx=\"3\" fill=\"#2e1065\"/>\n    <text x=\"16\" y=\"110\" fill=\"#e9d5ff\" font-size=\"6.5\" font-weight=\"700\">Invokes syscalls:</text>\n    <text x=\"16\" y=\"122\" fill=\"#cbd5e1\" font-size=\"6\">clone(), pivot_root()</text>\n    <text x=\"16\" y=\"132\" fill=\"#cbd5e1\" font-size=\"6\">setns(), unshare()</text>\n  </g>\n  <!-- Arrow -->\n  <g transform=\"translate(515, 115)\">\n    <line x1=\"0\" y1=\"0\" x2=\"25\" y2=\"0\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <polygon points=\"25,0 18,-4 18,4\" fill=\"#10b981\"/>\n    <text x=\"12\" y=\"-6\" fill=\"#10b981\" font-size=\"6\" text-anchor=\"middle\">Linux</text>\n  </g>\n  <!-- Layer 4: Kernel -->\n  <g transform=\"translate(545, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"110\" height=\"155\" rx=\"5\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n    <text x=\"10\" y=\"20\" fill=\"#a7f3d0\" font-size=\"8\" font-weight=\"800\">4. LINUX KERNEL</text>\n    <text x=\"10\" y=\"34\" fill=\"#cbd5e1\" font-size=\"6.5\">Host Isolation</text>\n    <rect x=\"8\" y=\"44\" width=\"94\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"14\" y=\"58\" fill=\"#34d399\" font-size=\"7\" font-weight=\"700\">Namespaces:</text>\n    <text x=\"14\" y=\"70\" fill=\"#cbd5e1\" font-size=\"6\">pid, net, ipc, mnt</text>\n    <rect x=\"8\" y=\"94\" width=\"94\" height=\"45\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"14\" y=\"110\" fill=\"#34d399\" font-size=\"7\" font-weight=\"700\">cgroups v2:</text>\n    <text x=\"14\" y=\"122\" fill=\"#cbd5e1\" font-size=\"6\">CPU and Mem limits</text>\n    <text x=\"14\" y=\"132\" fill=\"#cbd5e1\" font-size=\"6\">OOM Killer (137)</text>\n  </g>\n</svg>",
      "caption": "Pila de ejecución OCI: Kubelet se comunica por gRPC (CRI) con un runtime de alto nivel (containerd). Este invoca al runtime de bajo nivel (runc) para crear namespaces y cgroups en el kernel de Linux.",
      "captionEn": "OCI execution stack: Kubelet communicates via gRPC CRI with containerd, which spawns low-level runc to configure Linux kernel namespaces and cgroups."
    },
    "kcna-10": {
      "badge": "Pod Anatomy",
      "title": "Anatomía Interna de un Pod: Contenedor Pause, IP Compartida y Volúmenes",
      "titleEn": "Pod Internal Anatomy: Pause Container, Shared IP & Localhost",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">POD ANATOMY: SHARED NAMESPACES AND PAUSE CONTAINER</text>\n  <!-- Outer Pod Box -->\n  <g transform=\"translate(25, 40)\">\n    <rect x=\"0\" y=\"0\" width=\"630\" height=\"170\" rx=\"6\" fill=\"#1e293b\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n    <rect x=\"0\" y=\"0\" width=\"630\" height=\"24\" rx=\"6\" fill=\"#1d4ed8\"/>\n    <text x=\"14\" y=\"16\" fill=\"#ffffff\" font-size=\"9\" font-weight=\"800\">POD SANDBOX (Pod IP: 10.244.1.25 · Node: worker-02)</text>\n    <!-- Pause Container Left -->\n    <g transform=\"translate(15, 34)\">\n      <rect x=\"0\" y=\"0\" width=\"135\" height=\"120\" rx=\"4\" fill=\"#0f172a\" stroke=\"#f59e0b\"/>\n      <text x=\"10\" y=\"18\" fill=\"#fbbf24\" font-size=\"7.5\" font-weight=\"800\">pause container</text>\n      <text x=\"10\" y=\"32\" fill=\"#cbd5e1\" font-size=\"6.5\">Infra Container</text>\n      <text x=\"10\" y=\"46\" fill=\"#94a3b8\" font-size=\"6\">• Reserves Network NS</text>\n      <text x=\"10\" y=\"58\" fill=\"#94a3b8\" font-size=\"6\">• Reserves IPC NS</text>\n      <text x=\"10\" y=\"70\" fill=\"#94a3b8\" font-size=\"6\">• Keeps the IP alive</text>\n      <text x=\"10\" y=\"82\" fill=\"#94a3b8\" font-size=\"6\">• Adopts orphaned processes</text>\n      <rect x=\"10\" y=\"94\" width=\"115\" height=\"18\" rx=\"2\" fill=\"#78350f\"/>\n      <text x=\"16\" y=\"106\" fill=\"#fef08a\" font-size=\"6\" font-weight=\"700\">Created first</text>\n    </g>\n    <!-- App Container Center -->\n    <g transform=\"translate(165, 34)\">\n      <rect x=\"0\" y=\"0\" width=\"215\" height=\"120\" rx=\"4\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n      <text x=\"12\" y=\"18\" fill=\"#a7f3d0\" font-size=\"8\" font-weight=\"800\">Main Container: app-web</text>\n      <rect x=\"10\" y=\"28\" width=\"195\" height=\"24\" rx=\"3\" fill=\"#0f172a\"/>\n      <text x=\"16\" y=\"44\" fill=\"#34d399\" font-size=\"7\">Port: 8080 (http://localhost:8080)</text>\n      <text x=\"10\" y=\"66\" fill=\"#d1fae5\" font-size=\"6.5\">• Processes user transactions</text>\n      <text x=\"10\" y=\"78\" fill=\"#d1fae5\" font-size=\"6.5\">• Writes logs to /var/log/app.log</text>\n      <text x=\"10\" y=\"90\" fill=\"#d1fae5\" font-size=\"6.5\">• Reads configuration from /etc/config</text>\n      <rect x=\"10\" y=\"100\" width=\"195\" height=\"14\" rx=\"2\" fill=\"#047857\"/>\n      <text x=\"16\" y=\"110\" fill=\"#ffffff\" font-size=\"6\">PID 1 in its own PID namespace</text>\n    </g>\n    <!-- Sidecar Container Right -->\n    <g transform=\"translate(395, 34)\">\n      <rect x=\"0\" y=\"0\" width=\"220\" height=\"120\" rx=\"4\" fill=\"#1e3a5f\" stroke=\"#38bdf8\"/>\n      <text x=\"12\" y=\"18\" fill=\"#7dd3fc\" font-size=\"8\" font-weight=\"800\">Sidecar Container: log-shipper</text>\n      <rect x=\"10\" y=\"28\" width=\"200\" height=\"24\" rx=\"3\" fill=\"#0f172a\"/>\n      <text x=\"16\" y=\"44\" fill=\"#38bdf8\" font-size=\"7\">Connects via localhost:8080</text>\n      <text x=\"10\" y=\"66\" fill=\"#cbd5e1\" font-size=\"6.5\">• Reads /var/log/app.log (Shared volume)</text>\n      <text x=\"10\" y=\"78\" fill=\"#cbd5e1\" font-size=\"6.5\">• Exports logs to Fluentd / Elasticsearch</text>\n      <rect x=\"10\" y=\"92\" width=\"200\" height=\"22\" rx=\"3\" fill=\"#0284c7\"/>\n      <text x=\"16\" y=\"106\" fill=\"#ffffff\" font-size=\"6.5\" font-weight=\"700\">Shared emptyDir volume mounted</text>\n    </g>\n  </g>\n</svg>",
      "caption": "Anatomía de un Pod multi-contenedor: el contenedor pause reserva los namespaces de Red e IPC. Todos los contenedores comparten la misma dirección IP (10.244.1.25), pueden comunicarse mediante localhost y compartir volúmenes montados.",
      "captionEn": "Pod internal anatomy: pause container holds network and IPC namespaces. Co-located containers share the pod IP, resolve each other on localhost, and mount shared volumes."
    },
    "kcna-11": {
      "badge": "Deployment Rollout",
      "title": "Rolling Update de Deployment: Creación y Desescalado de ReplicaSets",
      "titleEn": "Deployment Rolling Update: ReplicaSet Creation & Drain",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">DEPLOYMENT ROLLING UPDATE: ORCHESTRATING REPLICASETS V1 AND V2</text>\n  <!-- Deployment Header -->\n  <g transform=\"translate(25, 42)\">\n    <rect x=\"0\" y=\"0\" width=\"630\" height=\"34\" rx=\"4\" fill=\"#1e293b\" stroke=\"#3b82f6\"/>\n    <text x=\"14\" y=\"21\" fill=\"#93c5fd\" font-size=\"8.5\" font-weight=\"800\">Deployment: payment-api · replicas: 4 · maxSurge: 25% · maxUnavailable: 25%</text>\n  </g>\n  <!-- ReplicaSets Flow -->\n  <g transform=\"translate(25, 86)\">\n    <!-- Old ReplicaSet v1 -->\n    <rect x=\"0\" y=\"0\" width=\"295\" height=\"120\" rx=\"5\" fill=\"#1e293b\" stroke=\"#ef4444\"/>\n    <rect x=\"0\" y=\"0\" width=\"295\" height=\"22\" rx=\"5\" fill=\"#991b1b\"/>\n    <text x=\"12\" y=\"15\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">Old ReplicaSet (v1: 2.13.0) ➔ Scaling down</text>\n    <!-- Pods old -->\n    <g transform=\"translate(12, 32)\">\n      <rect x=\"0\" y=\"0\" width=\"58\" height=\"34\" rx=\"3\" fill=\"#1e3a5f\" stroke=\"#38bdf8\"/>\n      <text x=\"6\" y=\"16\" fill=\"#93c5fd\" font-size=\"6.5\">pod-v1-a</text>\n      <text x=\"6\" y=\"27\" fill=\"#34d399\" font-size=\"6\">Active</text>\n      <rect x=\"68\" y=\"0\" width=\"58\" height=\"34\" rx=\"3\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n      <text x=\"74\" y=\"16\" fill=\"#fca5a5\" font-size=\"6.5\">pod-v1-b</text>\n      <text x=\"74\" y=\"27\" fill=\"#f87171\" font-size=\"6\">Terminating</text>\n      <rect x=\"136\" y=\"0\" width=\"58\" height=\"34\" rx=\"3\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n      <text x=\"142\" y=\"16\" fill=\"#fca5a5\" font-size=\"6.5\">pod-v1-c</text>\n      <text x=\"142\" y=\"27\" fill=\"#f87171\" font-size=\"6\">Deleted</text>\n      <rect x=\"204\" y=\"0\" width=\"67\" height=\"34\" rx=\"3\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n      <text x=\"210\" y=\"16\" fill=\"#fca5a5\" font-size=\"6.5\">pod-v1-d</text>\n      <text x=\"210\" y=\"27\" fill=\"#f87171\" font-size=\"6\">Deleted</text>\n    </g>\n    <text x=\"12\" y=\"85\" fill=\"#cbd5e1\" font-size=\"6.5\">Active replicas: 1 of 4 initial</text>\n    <text x=\"12\" y=\"100\" fill=\"#a7f3d0\" font-size=\"6.5\">Stays alive for instant rollback (kubectl rollout undo)</text>\n  </g>\n  <!-- New ReplicaSet v2 -->\n  <g transform=\"translate(360, 86)\">\n    <rect x=\"0\" y=\"0\" width=\"295\" height=\"120\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"295\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"12\" y=\"15\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">New ReplicaSet (v2: 2.14.0) ➔ Scaling up</text>\n    <!-- Pods new -->\n    <g transform=\"translate(12, 32)\">\n      <rect x=\"0\" y=\"0\" width=\"58\" height=\"34\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n      <text x=\"6\" y=\"16\" fill=\"#a7f3d0\" font-size=\"6.5\">pod-v2-1</text>\n      <text x=\"6\" y=\"27\" fill=\"#34d399\" font-size=\"6\">Ready</text>\n      <rect x=\"68\" y=\"0\" width=\"58\" height=\"34\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n      <text x=\"74\" y=\"16\" fill=\"#a7f3d0\" font-size=\"6.5\">pod-v2-2</text>\n      <text x=\"74\" y=\"27\" fill=\"#34d399\" font-size=\"6\">Ready</text>\n      <rect x=\"136\" y=\"0\" width=\"58\" height=\"34\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n      <text x=\"142\" y=\"16\" fill=\"#a7f3d0\" font-size=\"6.5\">pod-v2-3</text>\n      <text x=\"142\" y=\"27\" fill=\"#34d399\" font-size=\"6\">Ready</text>\n      <rect x=\"204\" y=\"0\" width=\"67\" height=\"34\" rx=\"3\" fill=\"#1e3a5f\" stroke=\"#38bdf8\"/>\n      <text x=\"210\" y=\"16\" fill=\"#93c5fd\" font-size=\"6.5\">pod-v2-4</text>\n      <text x=\"210\" y=\"27\" fill=\"#38bdf8\" font-size=\"6\">Creating</text>\n    </g>\n    <text x=\"12\" y=\"85\" fill=\"#cbd5e1\" font-size=\"6.5\">Active replicas: 3 of 4 final (+1 starting)</text>\n    <text x=\"12\" y=\"100\" fill=\"#a7f3d0\" font-size=\"6.5\">Zero downtime: the Service serves v1 and v2 while migrating</text>\n  </g>\n</svg>",
      "caption": "Mecánica del Rolling Update: el Deployment crea un segundo ReplicaSet para v2 y coordina el escalado proporcional de v2 mientras desescala v1, garantizando que nunca se viole maxUnavailable y manteniendo v1 disponible para rollback inmediato.",
      "captionEn": "Deployment Rolling Update mechanics: Deployment controller creates a new ReplicaSet for v2, scaling it up while draining v1 within maxSurge and maxUnavailable constraints, keeping v1 ready for rollback."
    },
    "kcna-12": {
      "badge": "DaemonSet",
      "title": "Topología de DaemonSet: Un Pod por Cada Nodo Worker",
      "titleEn": "DaemonSet Topology: One Pod per Worker Node",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">DAEMONSET TOPOLOGY: INFRASTRUCTURE AGENTS ON EVERY NODE</text>\n  <!-- Node 1 -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"195\" height=\"160\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <rect x=\"0\" y=\"0\" width=\"195\" height=\"22\" rx=\"5\" fill=\"#0284c7\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">WORKER NODE 01</text>\n    <!-- Daemon Pod -->\n    <rect x=\"10\" y=\"32\" width=\"175\" height=\"42\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n    <text x=\"16\" y=\"48\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"800\">DaemonSet Pod: fluentd</text>\n    <text x=\"16\" y=\"60\" fill=\"#cbd5e1\" font-size=\"6.5\">Collects /var/log/* from the host</text>\n    <!-- App Pods -->\n    <rect x=\"10\" y=\"82\" width=\"175\" height=\"32\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"16\" y=\"96\" fill=\"#93c5fd\" font-size=\"7\">App Pod: frontend-x1</text>\n    <text x=\"16\" y=\"106\" fill=\"#94a3b8\" font-size=\"6\">Emits logs to stdout</text>\n    <rect x=\"10\" y=\"120\" width=\"175\" height=\"30\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"16\" y=\"136\" fill=\"#93c5fd\" font-size=\"7\">App Pod: api-y1</text>\n  </g>\n  <!-- Node 2 -->\n  <g transform=\"translate(240, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"195\" height=\"160\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <rect x=\"0\" y=\"0\" width=\"195\" height=\"22\" rx=\"5\" fill=\"#0284c7\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">WORKER NODE 02</text>\n    <!-- Daemon Pod -->\n    <rect x=\"10\" y=\"32\" width=\"175\" height=\"42\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n    <text x=\"16\" y=\"48\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"800\">DaemonSet Pod: fluentd</text>\n    <text x=\"16\" y=\"60\" fill=\"#cbd5e1\" font-size=\"6.5\">Collects /var/log/* from the host</text>\n    <!-- App Pods -->\n    <rect x=\"10\" y=\"82\" width=\"175\" height=\"32\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"16\" y=\"96\" fill=\"#93c5fd\" font-size=\"7\">App Pod: frontend-x2</text>\n    <text x=\"16\" y=\"106\" fill=\"#94a3b8\" font-size=\"6\">Emits logs to stdout</text>\n    <rect x=\"10\" y=\"120\" width=\"175\" height=\"30\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"16\" y=\"136\" fill=\"#93c5fd\" font-size=\"7\">App Pod: payment-z1</text>\n  </g>\n  <!-- Node 3 (Newly Added Node) -->\n  <g transform=\"translate(455, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"160\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"22\" rx=\"5\" fill=\"#b45309\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">NEW NODE 03 (Autoscaling)</text>\n    <!-- Auto-spawned Daemon Pod -->\n    <rect x=\"10\" y=\"32\" width=\"180\" height=\"42\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n    <text x=\"16\" y=\"48\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"800\">DaemonSet Pod: fluentd ★</text>\n    <text x=\"16\" y=\"60\" fill=\"#34d399\" font-size=\"6.5\">Auto-deployed immediately</text>\n    <!-- Notice -->\n    <rect x=\"10\" y=\"82\" width=\"180\" height=\"68\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f59e0b\"/>\n    <text x=\"16\" y=\"98\" fill=\"#fde68a\" font-size=\"7\" font-weight=\"700\">Automatic Behavior:</text>\n    <text x=\"16\" y=\"112\" fill=\"#cbd5e1\" font-size=\"6.5\">• Node added ➔ Pod created</text>\n    <text x=\"16\" y=\"124\" fill=\"#cbd5e1\" font-size=\"6.5\">• Node removed ➔ Pod deleted</text>\n    <text x=\"16\" y=\"136\" fill=\"#a7f3d0\" font-size=\"6.5\">Ignores sched restrictions</text>\n  </g>\n</svg>",
      "caption": "Topología de DaemonSet: garantiza exactamente una copia del pod por cada nodo worker. Es el controlador idóneo para agentes de telemetría (node-exporter), recolección de logs (Fluentd) o proxies de red CNI.",
      "captionEn": "DaemonSet topology: ensures exactly one pod replica per worker node. Essential for infrastructure agents like node-exporter metrics, Fluentd logging, and CNI plugins."
    },
    "kcna-13": {
      "badge": "StatefulSet",
      "title": "StatefulSet: Nombres Ordinales y Almacenamiento Persistente Dedicado",
      "titleEn": "StatefulSet: Stable Ordinal Identities & Dedicated PVCs",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">STATEFULSET: ORDINAL IDENTITY AND DEDICATED PERSISTENT VOLUMES</text>\n  <!-- Headless Service Top -->\n  <g transform=\"translate(25, 42)\">\n    <rect x=\"0\" y=\"0\" width=\"630\" height=\"30\" rx=\"4\" fill=\"#2e1065\" stroke=\"#a78bfa\"/>\n    <text x=\"14\" y=\"19\" fill=\"#f5d0fe\" font-size=\"8\" font-weight=\"800\">Headless Service (clusterIP: None) ➔ Pod DNS: $(pod-name).$(service-name).default.svc.cluster.local</text>\n  </g>\n  <!-- 3 Ordinal Pods -->\n  <g transform=\"translate(25, 80)\">\n    <!-- Pod 0 -->\n    <g transform=\"translate(0, 0)\">\n      <rect x=\"0\" y=\"0\" width=\"195\" height=\"125\" rx=\"5\" fill=\"#1e293b\" stroke=\"#a78bfa\"/>\n      <rect x=\"0\" y=\"0\" width=\"195\" height=\"20\" rx=\"5\" fill=\"#6d28d9\"/>\n      <text x=\"10\" y=\"14\" fill=\"#ffffff\" font-size=\"7.5\" font-weight=\"800\">Pod: zk-0 (Primary)</text>\n      <text x=\"10\" y=\"34\" fill=\"#cbd5e1\" font-size=\"6.5\">DNS: zk-0.zk-svc</text>\n      <!-- Dedicated PVC -->\n      <rect x=\"10\" y=\"44\" width=\"175\" height=\"66\" rx=\"3\" fill=\"#0f172a\" stroke=\"#a78bfa\"/>\n      <text x=\"16\" y=\"60\" fill=\"#ddd6fe\" font-size=\"7\" font-weight=\"700\">Dedicated PVC: data-zk-0</text>\n      <text x=\"16\" y=\"72\" fill=\"#cbd5e1\" font-size=\"6\">PV: pvc-e9812 (100 GiB SSD)</text>\n      <text x=\"16\" y=\"86\" fill=\"#a7f3d0\" font-size=\"6.5\">✓ If zk-0 restarts,</text>\n      <text x=\"16\" y=\"98\" fill=\"#a7f3d0\" font-size=\"6.5\">it always remounts data-zk-0</text>\n    </g>\n    <!-- Pod 1 -->\n    <g transform=\"translate(215, 0)\">\n      <rect x=\"0\" y=\"0\" width=\"195\" height=\"125\" rx=\"5\" fill=\"#1e293b\" stroke=\"#a78bfa\"/>\n      <rect x=\"0\" y=\"0\" width=\"195\" height=\"20\" rx=\"5\" fill=\"#6d28d9\"/>\n      <text x=\"10\" y=\"14\" fill=\"#ffffff\" font-size=\"7.5\" font-weight=\"800\">Pod: zk-1 (Follower)</text>\n      <text x=\"10\" y=\"34\" fill=\"#cbd5e1\" font-size=\"6.5\">DNS: zk-1.zk-svc</text>\n      <!-- Dedicated PVC -->\n      <rect x=\"10\" y=\"44\" width=\"175\" height=\"66\" rx=\"3\" fill=\"#0f172a\" stroke=\"#a78bfa\"/>\n      <text x=\"16\" y=\"60\" fill=\"#ddd6fe\" font-size=\"7\" font-weight=\"700\">Dedicated PVC: data-zk-1</text>\n      <text x=\"16\" y=\"72\" fill=\"#cbd5e1\" font-size=\"6\">PV: pvc-f4521 (100 GiB SSD)</text>\n      <text x=\"16\" y=\"86\" fill=\"#a7f3d0\" font-size=\"6.5\">✓ Ordered deployment:</text>\n      <text x=\"16\" y=\"98\" fill=\"#a7f3d0\" font-size=\"6.5\">zk-1 starts after zk-0 is Ready</text>\n    </g>\n    <!-- Pod 2 -->\n    <g transform=\"translate(430, 0)\">\n      <rect x=\"0\" y=\"0\" width=\"200\" height=\"125\" rx=\"5\" fill=\"#1e293b\" stroke=\"#a78bfa\"/>\n      <rect x=\"0\" y=\"0\" width=\"200\" height=\"20\" rx=\"5\" fill=\"#6d28d9\"/>\n      <text x=\"10\" y=\"14\" fill=\"#ffffff\" font-size=\"7.5\" font-weight=\"800\">Pod: zk-2 (Follower)</text>\n      <text x=\"10\" y=\"34\" fill=\"#cbd5e1\" font-size=\"6.5\">DNS: zk-2.zk-svc</text>\n      <!-- Dedicated PVC -->\n      <rect x=\"10\" y=\"44\" width=\"180\" height=\"66\" rx=\"3\" fill=\"#0f172a\" stroke=\"#a78bfa\"/>\n      <text x=\"16\" y=\"60\" fill=\"#ddd6fe\" font-size=\"7\" font-weight=\"700\">Dedicated PVC: data-zk-2</text>\n      <text x=\"16\" y=\"72\" fill=\"#cbd5e1\" font-size=\"6\">PV: pvc-a8903 (100 GiB SSD)</text>\n      <text x=\"16\" y=\"86\" fill=\"#a7f3d0\" font-size=\"6.5\">✓ Ordered termination:</text>\n      <text x=\"16\" y=\"98\" fill=\"#a7f3d0\" font-size=\"6.5\">zk-2 shuts down before zk-1</text>\n    </g>\n  </g>\n</svg>",
      "caption": "StatefulSet para bases de datos: proporciona identificadores ordinales estables (zk-0, zk-1), DNS determinista vía Headless Service y aprovisiona volúmenes dedicados por réplica mediante volumeClaimTemplates que persisten entre reinicios.",
      "captionEn": "StatefulSet for stateful workloads: provides ordinal pod identities, deterministic DNS via Headless Services, and persistent volumes bound via volumeClaimTemplates across pod recreations."
    },
    "kcna-16": {
      "badge": "DNS CoreDNS",
      "title": "Resolución DNS en CoreDNS: Formato FQDN entre Namespaces",
      "titleEn": "CoreDNS Service Resolution: Cross-Namespace FQDN Format",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">DNS RESOLUTION WITH COREDNS: FQDN STRUCTURE ACROSS NAMESPACES</text>\n  <!-- Source Namespace -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"180\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <rect x=\"0\" y=\"0\" width=\"180\" height=\"22\" rx=\"5\" fill=\"#0284c7\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">NAMESPACE: production</text>\n    <rect x=\"10\" y=\"32\" width=\"160\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"16\" y=\"48\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"700\">Pod: frontend-app</text>\n    <text x=\"16\" y=\"60\" fill=\"#cbd5e1\" font-size=\"6.5\">IP: 10.244.1.88</text>\n    <!-- Query text -->\n    <rect x=\"10\" y=\"84\" width=\"160\" height=\"66\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"16\" y=\"100\" fill=\"#fde68a\" font-size=\"6.5\" font-weight=\"700\">Outbound DNS query:</text>\n    <text x=\"16\" y=\"112\" fill=\"#ffffff\" font-size=\"6.5\">billing-svc.finance</text>\n    <text x=\"16\" y=\"124\" fill=\"#94a3b8\" font-size=\"6\">Resolves through</text>\n    <text x=\"16\" y=\"136\" fill=\"#94a3b8\" font-size=\"6\">CoreDNS (10.96.0.10)</text>\n  </g>\n  <!-- CoreDNS Center Breakdown -->\n  <g transform=\"translate(225, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"230\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n    <rect x=\"0\" y=\"0\" width=\"230\" height=\"22\" rx=\"5\" fill=\"#b45309\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">FQDN BREAKDOWN (CoreDNS)</text>\n    <rect x=\"10\" y=\"32\" width=\"210\" height=\"34\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n    <text x=\"18\" y=\"48\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"800\">billing-svc . finance</text>\n    <text x=\"18\" y=\"58\" fill=\"#d1fae5\" font-size=\"6.5\">&lt;service&gt; . &lt;namespace&gt;</text>\n    <rect x=\"10\" y=\"74\" width=\"210\" height=\"34\" rx=\"3\" fill=\"#1e3a5f\" stroke=\"#38bdf8\"/>\n    <text x=\"18\" y=\"90\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"800\">. svc . cluster.local</text>\n    <text x=\"18\" y=\"100\" fill=\"#cbd5e1\" font-size=\"6.5\">&lt;resource-type&gt; . &lt;cluster-domain&gt;</text>\n    <!-- Full FQDN Result -->\n    <rect x=\"10\" y=\"116\" width=\"210\" height=\"30\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f59e0b\"/>\n    <text x=\"16\" y=\"134\" fill=\"#fbbf24\" font-size=\"6.5\" font-weight=\"800\">billing-svc.finance.svc.cluster.local</text>\n  </g>\n  <!-- Target Namespace -->\n  <g transform=\"translate(475, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"180\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"180\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">NAMESPACE: finance</text>\n    <rect x=\"10\" y=\"32\" width=\"160\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"16\" y=\"48\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">Service: billing-svc</text>\n    <text x=\"16\" y=\"60\" fill=\"#cbd5e1\" font-size=\"6.5\">ClusterIP: 10.108.45.12</text>\n    <!-- Endpoints -->\n    <rect x=\"10\" y=\"84\" width=\"160\" height=\"66\" rx=\"3\" fill=\"#0f172a\" stroke=\"#34d399\"/>\n    <text x=\"16\" y=\"100\" fill=\"#34d399\" font-size=\"6.5\" font-weight=\"700\">Target endpoints:</text>\n    <text x=\"16\" y=\"112\" fill=\"#cbd5e1\" font-size=\"6.5\">• pod-billing-1 (10.244.3.11)</text>\n    <text x=\"16\" y=\"124\" fill=\"#cbd5e1\" font-size=\"6.5\">• pod-billing-2 (10.244.3.12)</text>\n    <text x=\"16\" y=\"138\" fill=\"#a7f3d0\" font-size=\"6.5\">✓ Connection established</text>\n  </g>\n</svg>",
      "caption": "Estructura del FQDN en Kubernetes: CoreDNS resuelve los servicios mediante la jerarquía `<servicio>.<namespace>.svc.<dominio-cluster>`. Permite a pods en el namespace production conectarse inequívocamente a billing-svc en finance.",
      "captionEn": "Kubernetes FQDN resolution: CoreDNS maps service addresses following `<service>.<namespace>.svc.<cluster-domain>`, enabling clean cross-namespace communication."
    },
    "kcna-18": {
      "badge": "Static Pods",
      "title": "Static Pods: Gestión Directa por Kubelet y Mirror Pods",
      "titleEn": "Static Pods: Direct Kubelet Lifecycle & Mirror Pods",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">STATIC PODS: CONTROL PLANE BOOTSTRAP WITHOUT A SCHEDULER</text>\n  <!-- Local Filesystem on Host -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"22\" rx=\"5\" fill=\"#b45309\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">LOCAL FILE SYSTEM</text>\n    <text x=\"10\" y=\"34\" fill=\"#fde68a\" font-size=\"7\" font-weight=\"700\">/etc/kubernetes/manifests/</text>\n    <!-- Files -->\n    <rect x=\"10\" y=\"44\" width=\"180\" height=\"24\" rx=\"2\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"16\" y=\"58\" fill=\"#ffffff\" font-size=\"6.5\">📄 kube-apiserver.yaml</text>\n    <rect x=\"10\" y=\"72\" width=\"180\" height=\"24\" rx=\"2\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"16\" y=\"86\" fill=\"#ffffff\" font-size=\"6.5\">📄 etcd.yaml</text>\n    <rect x=\"10\" y=\"100\" width=\"180\" height=\"24\" rx=\"2\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"16\" y=\"114\" fill=\"#ffffff\" font-size=\"6.5\">📄 kube-scheduler.yaml</text>\n    <rect x=\"10\" y=\"128\" width=\"180\" height=\"22\" rx=\"2\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"16\" y=\"142\" fill=\"#ffffff\" font-size=\"6.5\">📄 kube-controller-manager.yaml</text>\n  </g>\n  <!-- Kubelet Supervision Center -->\n  <g transform=\"translate(245, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">KUBELET ON THE NODE</text>\n    <text x=\"10\" y=\"34\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"700\">Periodic File Monitoring</text>\n    <rect x=\"10\" y=\"44\" width=\"180\" height=\"48\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"16\" y=\"60\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"700\">Starts CRI containers:</text>\n    <text x=\"16\" y=\"72\" fill=\"#cbd5e1\" font-size=\"6.5\">• The scheduler is not involved</text>\n    <text x=\"16\" y=\"84\" fill=\"#cbd5e1\" font-size=\"6.5\">• Self-heal if they fail</text>\n    <rect x=\"10\" y=\"100\" width=\"180\" height=\"48\" rx=\"3\" fill=\"#064e3b\"/>\n    <text x=\"16\" y=\"116\" fill=\"#ffffff\" font-size=\"6.5\" font-weight=\"700\">Creates Mirror Pod in apiserver:</text>\n    <text x=\"16\" y=\"128\" fill=\"#d1fae5\" font-size=\"6\">Visible in `kubectl get pods`</text>\n    <text x=\"16\" y=\"139\" fill=\"#d1fae5\" font-size=\"6\">but immutable from the API</text>\n  </g>\n  <!-- Mirror Pod in apiserver Right -->\n  <g transform=\"translate(465, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"190\" height=\"155\" rx=\"5\" fill=\"#1e3a5f\" stroke=\"#38bdf8\"/>\n    <rect x=\"0\" y=\"0\" width=\"190\" height=\"22\" rx=\"5\" fill=\"#1d4ed8\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">MIRROR PODS (In API Server)</text>\n    <text x=\"10\" y=\"34\" fill=\"#93c5fd\" font-size=\"7\" font-weight=\"700\">Read-only representation</text>\n    <rect x=\"10\" y=\"44\" width=\"170\" height=\"30\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"16\" y=\"58\" fill=\"#ffffff\" font-size=\"6.5\">kube-apiserver-master01</text>\n    <text x=\"16\" y=\"68\" fill=\"#34d399\" font-size=\"6\">Running (Mirror)</text>\n    <rect x=\"10\" y=\"80\" width=\"170\" height=\"30\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"16\" y=\"94\" fill=\"#ffffff\" font-size=\"6.5\">etcd-master01</text>\n    <text x=\"16\" y=\"104\" fill=\"#34d399\" font-size=\"6\">Running (Mirror)</text>\n    <rect x=\"10\" y=\"118\" width=\"170\" height=\"30\" rx=\"3\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n    <text x=\"16\" y=\"132\" fill=\"#fca5a5\" font-size=\"6.5\">kubectl delete pod does NOT remove it</text>\n    <text x=\"16\" y=\"142\" fill=\"#cbd5e1\" font-size=\"6\">The kubelet recreates it immediately</text>\n  </g>\n</svg>",
      "caption": "Mecánica de Static Pods: el kubelet lee directamente manifiestos locales en /etc/kubernetes/manifests sin depender de un scheduler. Inicia los procesos y crea un Mirror Pod en el apiserver como representación de solo lectura.",
      "captionEn": "Static Pods mechanism: kubelet reads host manifests in /etc/kubernetes/manifests directly without scheduler intervention. It launches containers and maintains read-only mirror pods in the apiserver."
    },
    "kcna-19": {
      "badge": "initContainers",
      "title": "Secuencia de Inicialización: initContainers Bloqueantes vs App",
      "titleEn": "Pod Initialization Sequence: Blocking initContainers vs App",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">STARTUP SEQUENCE: SEQUENTIAL INITCONTAINERS VS APP CONTAINERS</text>\n  <!-- Timeline Steps -->\n  <g transform=\"translate(25, 45)\">\n    <!-- Step 1: Network & Pause -->\n    <g transform=\"translate(0, 0)\">\n      <rect x=\"0\" y=\"0\" width=\"135\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n      <rect x=\"0\" y=\"0\" width=\"135\" height=\"22\" rx=\"5\" fill=\"#b45309\"/>\n      <text x=\"8\" y=\"15\" fill=\"#ffffff\" font-size=\"7.5\" font-weight=\"800\">1. INFRA CONTAINER</text>\n      <text x=\"8\" y=\"34\" fill=\"#fde68a\" font-size=\"6.5\">pause container</text>\n      <rect x=\"8\" y=\"44\" width=\"119\" height=\"50\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n      <text x=\"12\" y=\"60\" fill=\"#ffffff\" font-size=\"6.5\">Configures CNI Network</text>\n      <text x=\"12\" y=\"72\" fill=\"#cbd5e1\" font-size=\"6\">Assigns IP to the Pod</text>\n      <text x=\"12\" y=\"84\" fill=\"#34d399\" font-size=\"6\">Namespace ready</text>\n      <rect x=\"8\" y=\"104\" width=\"119\" height=\"42\" rx=\"2\" fill=\"#064e3b\"/>\n      <text x=\"12\" y=\"120\" fill=\"#a7f3d0\" font-size=\"6.5\">State: Ready</text>\n      <text x=\"12\" y=\"132\" fill=\"#d1fae5\" font-size=\"6\">Moves on to initContainer 1</text>\n    </g>\n    <!-- Arrow -->\n    <g transform=\"translate(140, 75)\">\n      <line x1=\"0\" y1=\"0\" x2=\"20\" y2=\"0\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n      <polygon points=\"20,0 14,-3 14,3\" fill=\"#f59e0b\"/>\n    </g>\n    <!-- Step 2: initContainer 1 -->\n    <g transform=\"translate(165, 0)\">\n      <rect x=\"0\" y=\"0\" width=\"145\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#a78bfa\"/>\n      <rect x=\"0\" y=\"0\" width=\"145\" height=\"22\" rx=\"5\" fill=\"#6d28d9\"/>\n      <text x=\"8\" y=\"15\" fill=\"#ffffff\" font-size=\"7.5\" font-weight=\"800\">2. INIT 1 (Wait DB)</text>\n      <text x=\"8\" y=\"34\" fill=\"#ddd6fe\" font-size=\"6.5\">Sequential Execution</text>\n      <rect x=\"8\" y=\"44\" width=\"129\" height=\"50\" rx=\"3\" fill=\"#0f172a\" stroke=\"#a78bfa\"/>\n      <text x=\"12\" y=\"58\" fill=\"#ffffff\" font-size=\"6.5\">wait-for-db.sh</text>\n      <text x=\"12\" y=\"70\" fill=\"#cbd5e1\" font-size=\"6\">Polls TCP port 5432</text>\n      <text x=\"12\" y=\"82\" fill=\"#a7f3d0\" font-size=\"6\">✓ DB Responds OK</text>\n      <rect x=\"8\" y=\"104\" width=\"129\" height=\"42\" rx=\"2\" fill=\"#2e1065\"/>\n      <text x=\"12\" y=\"120\" fill=\"#f5d0fe\" font-size=\"6.5\">Exit Code: 0</text>\n      <text x=\"12\" y=\"132\" fill=\"#c4b5fd\" font-size=\"6\">Unblocks INIT 2</text>\n    </g>\n    <!-- Arrow -->\n    <g transform=\"translate(315, 75)\">\n      <line x1=\"0\" y1=\"0\" x2=\"20\" y2=\"0\" stroke=\"#a78bfa\" stroke-width=\"2\"/>\n      <polygon points=\"20,0 14,-3 14,3\" fill=\"#a78bfa\"/>\n    </g>\n    <!-- Step 3: initContainer 2 -->\n    <g transform=\"translate(340, 0)\">\n      <rect x=\"0\" y=\"0\" width=\"145\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n      <rect x=\"0\" y=\"0\" width=\"145\" height=\"22\" rx=\"5\" fill=\"#0284c7\"/>\n      <text x=\"8\" y=\"15\" fill=\"#ffffff\" font-size=\"7.5\" font-weight=\"800\">3. INIT 2 (Pull Config)</text>\n      <text x=\"8\" y=\"34\" fill=\"#7dd3fc\" font-size=\"6.5\">Asset Download</text>\n      <rect x=\"8\" y=\"44\" width=\"129\" height=\"50\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n      <text x=\"12\" y=\"58\" fill=\"#ffffff\" font-size=\"6.5\">aws s3 cp config.json</text>\n      <text x=\"12\" y=\"70\" fill=\"#cbd5e1\" font-size=\"6\">Writes to emptyDir</text>\n      <text x=\"12\" y=\"82\" fill=\"#a7f3d0\" font-size=\"6\">✓ File downloaded</text>\n      <rect x=\"8\" y=\"104\" width=\"129\" height=\"42\" rx=\"2\" fill=\"#1e3a5f\"/>\n      <text x=\"12\" y=\"120\" fill=\"#93c5fd\" font-size=\"6.5\">Exit Code: 0</text>\n      <text x=\"12\" y=\"132\" fill=\"#bae6fd\" font-size=\"6\">Unblocks Apps</text>\n    </g>\n    <!-- Arrow -->\n    <g transform=\"translate(490, 75)\">\n      <line x1=\"0\" y1=\"0\" x2=\"20\" y2=\"0\" stroke=\"#10b981\" stroke-width=\"2\"/>\n      <polygon points=\"20,0 14,-3 14,3\" fill=\"#10b981\"/>\n    </g>\n    <!-- Step 4: App Containers in Parallel -->\n    <g transform=\"translate(515, 0)\">\n      <rect x=\"0\" y=\"0\" width=\"115\" height=\"155\" rx=\"5\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n      <text x=\"8\" y=\"18\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"800\">4. APP READY</text>\n      <text x=\"8\" y=\"32\" fill=\"#cbd5e1\" font-size=\"6\">In parallel</text>\n      <rect x=\"6\" y=\"44\" width=\"103\" height=\"46\" rx=\"2\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n      <text x=\"10\" y=\"58\" fill=\"#34d399\" font-size=\"6.5\" font-weight=\"700\">web-server</text>\n      <text x=\"10\" y=\"70\" fill=\"#cbd5e1\" font-size=\"6\">Starts app</text>\n      <text x=\"10\" y=\"82\" fill=\"#34d399\" font-size=\"6\">Port 8080</text>\n      <rect x=\"6\" y=\"98\" width=\"103\" height=\"46\" rx=\"2\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n      <text x=\"10\" y=\"112\" fill=\"#38bdf8\" font-size=\"6.5\" font-weight=\"700\">log-sidecar</text>\n      <text x=\"10\" y=\"124\" fill=\"#cbd5e1\" font-size=\"6\">Reads logs</text>\n      <text x=\"10\" y=\"136\" fill=\"#a7f3d0\" font-size=\"6\">Run together</text>\n    </g>\n  </g>\n</svg>",
      "caption": "Secuencia de inicio de un Pod: los initContainers se ejecutan secuencialmente en orden estricto; cada uno debe finalizar exitosamente (Exit Code 0). Si alguno falla, el Pod se reinicia y los contenedores de aplicación no llegan a arrancar.",
      "captionEn": "Pod startup sequence: initContainers execute sequentially to completion (exit code 0). If any initContainer fails, the pod restarts and application containers never launch."
    },
    "kcna-24": {
      "badge": "Requests vs Limits",
      "title": "Asignación de Recursos: Requests (Scheduling) vs Limits (cgroups)",
      "titleEn": "Resource Allocation: Requests (Scheduling) vs Limits (cgroups)",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">CONTAINER RESOURCES: REQUESTS VS LIMITS FOR CPU AND MEMORY</text>\n  <!-- CPU Bar Graph Left -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <text x=\"12\" y=\"18\" fill=\"#38bdf8\" font-size=\"8\" font-weight=\"800\">CPU BEHAVIOR (Compressible Resource)</text>\n    <!-- Bar visualization -->\n    <rect x=\"12\" y=\"30\" width=\"277\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <rect x=\"18\" y=\"40\" width=\"95\" height=\"22\" rx=\"2\" fill=\"#10b981\"/>\n    <text x=\"24\" y=\"54\" fill=\"#ffffff\" font-size=\"7\" font-weight=\"700\">requests: 500m</text>\n    <rect x=\"115\" y=\"40\" width=\"105\" height=\"22\" rx=\"2\" fill=\"#f59e0b\"/>\n    <text x=\"122\" y=\"54\" fill=\"#ffffff\" font-size=\"7\" font-weight=\"700\">limits: 1000m (1 core)</text>\n    <line x1=\"220\" y1=\"30\" x2=\"220\" y2=\"72\" stroke=\"#ef4444\" stroke-width=\"2\" stroke-dasharray=\"2,2\"/>\n    <text x=\"225\" y=\"48\" fill=\"#f87171\" font-size=\"6.5\" font-weight=\"700\">cgroup ceiling</text>\n    <!-- Explanation -->\n    <rect x=\"12\" y=\"80\" width=\"277\" height=\"58\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"18\" y=\"96\" fill=\"#a7f3d0\" font-size=\"7\">• requests: Reservation guarantee on the node for the scheduler.</text>\n    <text x=\"18\" y=\"110\" fill=\"#fde68a\" font-size=\"7\">• limits: If the process tries to use &gt;1000m, the kernel applies</text>\n    <text x=\"18\" y=\"122\" fill=\"#fca5a5\" font-size=\"7\" font-weight=\"700\">  CFS Throttling. The pod does NOT die!</text>\n  </g>\n  <!-- Memory Bar Graph Right -->\n  <g transform=\"translate(350, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#ef4444\"/>\n    <text x=\"12\" y=\"18\" fill=\"#f87171\" font-size=\"8\" font-weight=\"800\">MEMORY BEHAVIOR (Incompressible Resource)</text>\n    <!-- Bar visualization -->\n    <rect x=\"12\" y=\"30\" width=\"277\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <rect x=\"18\" y=\"40\" width=\"110\" height=\"22\" rx=\"2\" fill=\"#10b981\"/>\n    <text x=\"24\" y=\"54\" fill=\"#ffffff\" font-size=\"7\" font-weight=\"700\">requests: 512Mi</text>\n    <rect x=\"130\" y=\"40\" width=\"85\" height=\"22\" rx=\"2\" fill=\"#f59e0b\"/>\n    <text x=\"138\" y=\"54\" fill=\"#ffffff\" font-size=\"7\" font-weight=\"700\">limits: 1Gi</text>\n    <line x1=\"215\" y1=\"30\" x2=\"215\" y2=\"72\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n    <text x=\"220\" y=\"48\" fill=\"#ef4444\" font-size=\"6.5\" font-weight=\"800\">1Gi limit</text>\n    <!-- Explanation -->\n    <rect x=\"12\" y=\"80\" width=\"277\" height=\"58\" rx=\"3\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n    <text x=\"18\" y=\"96\" fill=\"#fecaca\" font-size=\"7\">• requests: Ensures the host has 512Mi free at startup.</text>\n    <text x=\"18\" y=\"110\" fill=\"#fca5a5\" font-size=\"7\">• limits: If actual consumption (RSS) exceeds 1Gi, the Linux kernel</text>\n    <text x=\"18\" y=\"122\" fill=\"#ffffff\" font-size=\"7\" font-weight=\"800\">  sends SIGKILL (9) ➔ OOMKilled (Exit Code 137).</text>\n  </g>\n</svg>",
      "caption": "Diferencia crítica entre CPU y memoria: la CPU es comprimible; si el pod supera limits.cpu sufre throttling de ciclos. La memoria no es comprimible; si supera limits.memory el OOM Killer liquida el proceso con SIGKILL (Exit Code 137).",
      "captionEn": "CPU vs Memory mechanics: CPU is compressible (breaching limits triggers CFS throttling). Memory is non-compressible (breaching limits triggers immediate Linux OOM Killer SIGKILL with Exit Code 137)."
    },
    "kcna-25": {
      "badge": "QoS Classes",
      "title": "Jerarquía de Clases QoS y Prioridad de Desalojo (Eviction)",
      "titleEn": "QoS Classes Hierarchy & Eviction Priority under Node Pressure",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">QUALITY OF SERVICE (QOS) CLASSES AND EVICTION ORDER</text>\n  <!-- 3 QoS Columns -->\n  <g transform=\"translate(25, 45)\">\n    <!-- Guaranteed -->\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"155\" rx=\"5\" fill=\"#064e3b\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n    <text x=\"12\" y=\"18\" fill=\"#a7f3d0\" font-size=\"8\" font-weight=\"800\">1. GUARANTEED (Highest Priority)</text>\n    <rect x=\"10\" y=\"28\" width=\"180\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"16\" y=\"44\" fill=\"#ffffff\" font-size=\"7\">Strict Condition:</text>\n    <text x=\"16\" y=\"56\" fill=\"#34d399\" font-size=\"6.5\">requests == limits</text>\n    <text x=\"16\" y=\"66\" fill=\"#cbd5e1\" font-size=\"6\">for CPU and Memory (all cont.)</text>\n    <rect x=\"10\" y=\"78\" width=\"180\" height=\"64\" rx=\"3\" fill=\"#0f172a\" stroke=\"#334155\"/>\n    <text x=\"16\" y=\"96\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"700\">Eviction Resilience:</text>\n    <text x=\"16\" y=\"110\" fill=\"#cbd5e1\" font-size=\"6.5\">• Last to be evicted</text>\n    <text x=\"16\" y=\"122\" fill=\"#cbd5e1\" font-size=\"6.5\">• Evicted only if the host cannot</text>\n    <text x=\"16\" y=\"132\" fill=\"#cbd5e1\" font-size=\"6.5\">  reclaim memory.</text>\n  </g>\n  <g transform=\"translate(240, 45)\">\n    <!-- Burstable -->\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"155\" rx=\"5\" fill=\"#1e3a5f\" stroke=\"#38bdf8\"/>\n    <text x=\"12\" y=\"18\" fill=\"#7dd3fc\" font-size=\"8\" font-weight=\"800\">2. BURSTABLE (Intermediate)</text>\n    <rect x=\"10\" y=\"28\" width=\"180\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"16\" y=\"44\" fill=\"#ffffff\" font-size=\"7\">Strict Condition:</text>\n    <text x=\"16\" y=\"56\" fill=\"#93c5fd\" font-size=\"6.5\">At least 1 request or limit</text>\n    <text x=\"16\" y=\"66\" fill=\"#cbd5e1\" font-size=\"6\">but requests != limits</text>\n    <rect x=\"10\" y=\"78\" width=\"180\" height=\"64\" rx=\"3\" fill=\"#0f172a\" stroke=\"#334155\"/>\n    <text x=\"16\" y=\"96\" fill=\"#7dd3fc\" font-size=\"7\" font-weight=\"700\">Eviction Resilience:</text>\n    <text x=\"16\" y=\"110\" fill=\"#cbd5e1\" font-size=\"6.5\">• Medium priority</text>\n    <text x=\"16\" y=\"122\" fill=\"#cbd5e1\" font-size=\"6.5\">• Evicted if they exceed their</text>\n    <text x=\"16\" y=\"132\" fill=\"#cbd5e1\" font-size=\"6.5\">  declared initial requests.</text>\n  </g>\n  <g transform=\"translate(455, 45)\">\n    <!-- BestEffort -->\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"155\" rx=\"5\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n    <text x=\"12\" y=\"18\" fill=\"#fca5a5\" font-size=\"8\" font-weight=\"800\">3. BESTEFFORT (Lowest Priority)</text>\n    <rect x=\"10\" y=\"28\" width=\"180\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#ef4444\"/>\n    <text x=\"16\" y=\"44\" fill=\"#ffffff\" font-size=\"7\">Strict Condition:</text>\n    <text x=\"16\" y=\"56\" fill=\"#f87171\" font-size=\"6.5\">No requests or limits</text>\n    <text x=\"16\" y=\"66\" fill=\"#cbd5e1\" font-size=\"6\">no container defines resources</text>\n    <rect x=\"10\" y=\"78\" width=\"180\" height=\"64\" rx=\"3\" fill=\"#0f172a\" stroke=\"#ef4444\"/>\n    <text x=\"16\" y=\"96\" fill=\"#f87171\" font-size=\"7\" font-weight=\"800\">FIRST TO BE EVICTED:</text>\n    <text x=\"16\" y=\"110\" fill=\"#fecaca\" font-size=\"6.5\">• Under MemoryPressure on the node,</text>\n    <text x=\"16\" y=\"122\" fill=\"#fecaca\" font-size=\"6.5\">  the kubelet kills them first</text>\n    <text x=\"16\" y=\"132\" fill=\"#fecaca\" font-size=\"6.5\">  to free memory for the host.</text>\n  </g>\n</svg>",
      "caption": "Clases de calidad de servicio (QoS): Guaranteed exige que requests y limits sean idénticos; Burstable tiene al menos un recurso configurado; BestEffort carece de requests/limits y es la primera categoría en ser expulsada cuando el nodo sufre presión de memoria.",
      "captionEn": "QoS class hierarchy: Guaranteed requires equal requests and limits; Burstable configures partial requests/limits; BestEffort defines neither and faces first eviction under node MemoryPressure."
    },
    "kcna-26": {
      "badge": "Taints & Tolerations",
      "title": "Taints y Tolerations: Repulsión de Nodos y Emparejamiento de Pods",
      "titleEn": "Taints & Tolerations: Node Repulsion & Pod Matching",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">TAINTS AND TOLERATIONS: NODE REPULSION MECHANISM</text>\n  <!-- Node with Taint -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"280\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n    <rect x=\"0\" y=\"0\" width=\"280\" height=\"24\" rx=\"5\" fill=\"#b45309\"/>\n    <text x=\"12\" y=\"16\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">SPECIALIZED NODE: gpu-node-01</text>\n    <!-- Taint badge -->\n    <rect x=\"12\" y=\"32\" width=\"256\" height=\"40\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f59e0b\"/>\n    <text x=\"20\" y=\"48\" fill=\"#fde68a\" font-size=\"7.5\" font-weight=\"800\">TAINT: sku=gpu:NoSchedule</text>\n    <text x=\"20\" y=\"62\" fill=\"#cbd5e1\" font-size=\"6.5\">Key: sku | Value: gpu | Effect: NoSchedule</text>\n    <!-- Repulsion field -->\n    <rect x=\"12\" y=\"80\" width=\"256\" height=\"60\" rx=\"3\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n    <text x=\"20\" y=\"98\" fill=\"#fca5a5\" font-size=\"7.5\" font-weight=\"700\">Active Repulsion Field:</text>\n    <text x=\"20\" y=\"112\" fill=\"#fecaca\" font-size=\"6.5\">The scheduler rejects any Pod that does NOT have</text>\n    <text x=\"20\" y=\"124\" fill=\"#fecaca\" font-size=\"6.5\">a matching Toleration for 'sku=gpu'.</text>\n  </g>\n  <!-- Pod 1 without Toleration -->\n  <g transform=\"translate(340, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"145\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#ef4444\"/>\n    <rect x=\"0\" y=\"0\" width=\"145\" height=\"22\" rx=\"5\" fill=\"#991b1b\"/>\n    <text x=\"8\" y=\"15\" fill=\"#ffffff\" font-size=\"7.5\" font-weight=\"800\">Ordinary Pod (App)</text>\n    <rect x=\"8\" y=\"30\" width=\"129\" height=\"34\" rx=\"3\" fill=\"#0f172a\" stroke=\"#ef4444\"/>\n    <text x=\"14\" y=\"46\" fill=\"#fca5a5\" font-size=\"7\">No Toleration</text>\n    <text x=\"14\" y=\"56\" fill=\"#cbd5e1\" font-size=\"6\">Standard web pod</text>\n    <!-- Cross icon -->\n    <text x=\"72\" y=\"95\" fill=\"#ef4444\" font-size=\"28\" font-weight=\"800\" text-anchor=\"middle\">✗</text>\n    <rect x=\"8\" y=\"110\" width=\"129\" height=\"34\" rx=\"2\" fill=\"#450a0a\"/>\n    <text x=\"14\" y=\"124\" fill=\"#f87171\" font-size=\"6.5\" font-weight=\"700\">REJECTED:</text>\n    <text x=\"14\" y=\"136\" fill=\"#fca5a5\" font-size=\"6\">Scheduled on another node</text>\n  </g>\n  <!-- Pod 2 with Toleration -->\n  <g transform=\"translate(505, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"150\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"150\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"8\" y=\"15\" fill=\"#ffffff\" font-size=\"7.5\" font-weight=\"800\">ML Pod (With Toleration)</text>\n    <rect x=\"8\" y=\"30\" width=\"134\" height=\"44\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"14\" y=\"44\" fill=\"#a7f3d0\" font-size=\"6.5\" font-weight=\"700\">tolerations:</text>\n    <text x=\"14\" y=\"54\" fill=\"#ffffff\" font-size=\"6\">- key: \"sku\"</text>\n    <text x=\"14\" y=\"64\" fill=\"#ffffff\" font-size=\"6\">  value: \"gpu\"</text>\n    <!-- Checkmark icon -->\n    <text x=\"75\" y=\"98\" fill=\"#10b981\" font-size=\"28\" font-weight=\"800\" text-anchor=\"middle\">✓</text>\n    <rect x=\"8\" y=\"110\" width=\"134\" height=\"34\" rx=\"2\" fill=\"#064e3b\"/>\n    <text x=\"14\" y=\"124\" fill=\"#a7f3d0\" font-size=\"6.5\" font-weight=\"700\">ACCEPTED:</text>\n    <text x=\"14\" y=\"136\" fill=\"#d1fae5\" font-size=\"6\">Successfully scheduled</text>\n  </g>\n</svg>",
      "caption": "Mecánica de Taints y Tolerations: el nodo define un Taint (repulsión con efecto NoSchedule) que impide el agendamiento de pods ordinarios. Solo aquellos pods que declaren una Toleration exacta pueden ser agendados en ese nodo.",
      "captionEn": "Taints and Tolerations mechanics: the node advertises a Taint (repelling pods via NoSchedule). Only pods explicitly declaring a matching Toleration can be scheduled onto that node."
    },
    "kcna-27": {
      "badge": "NodeAffinity",
      "title": "Afinidad de Nodos: Required (Dura) vs Preferred (Suave)",
      "titleEn": "NodeAffinity: Required (Hard) vs Preferred (Soft)",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">NODEAFFINITY: HARD RULES (REQUIRED) VS SOFT RULES (PREFERRED)</text>\n  <!-- Left: Required -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#ef4444\"/>\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"22\" rx=\"5\" fill=\"#991b1b\"/>\n    <text x=\"12\" y=\"15\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">requiredDuringSchedulingIgnoredDuringExecution</text>\n    <rect x=\"12\" y=\"32\" width=\"277\" height=\"36\" rx=\"3\" fill=\"#0f172a\" stroke=\"#ef4444\"/>\n    <text x=\"18\" y=\"47\" fill=\"#fca5a5\" font-size=\"7.5\" font-weight=\"800\">HARD RULE: Unbreakable Condition</text>\n    <text x=\"18\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6.5\">The node MUST have the label zone=us-east-1a without exception.</text>\n    <!-- Scenario result -->\n    <rect x=\"12\" y=\"76\" width=\"277\" height=\"64\" rx=\"3\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n    <text x=\"18\" y=\"94\" fill=\"#fca5a5\" font-size=\"7.5\" font-weight=\"700\">If us-east-1a is full or does not exist:</text>\n    <text x=\"18\" y=\"108\" fill=\"#cbd5e1\" font-size=\"7\">• The Pod stays in the <b>Pending</b> state indefinitely.</text>\n    <text x=\"18\" y=\"120\" fill=\"#cbd5e1\" font-size=\"7\">• The scheduler will NEVER schedule the pod in another zone.</text>\n    <text x=\"18\" y=\"132\" fill=\"#f87171\" font-size=\"6.5\">⚠️ Causes outages if the selected zone suffers a failure.</text>\n  </g>\n  <!-- Right: Preferred -->\n  <g transform=\"translate(350, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"12\" y=\"15\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">preferredDuringSchedulingIgnoredDuringExecution</text>\n    <rect x=\"12\" y=\"32\" width=\"277\" height=\"36\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"18\" y=\"47\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"800\">SOFT RULE: Weighted Preference</text>\n    <text x=\"18\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6.5\">Tries to schedule in zone=us-east-1a by giving it higher weight (weight: 80).</text>\n    <!-- Scenario result -->\n    <rect x=\"12\" y=\"76\" width=\"277\" height=\"64\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n    <text x=\"18\" y=\"94\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">If us-east-1a is full or does not exist:</text>\n    <text x=\"18\" y=\"108\" fill=\"#cbd5e1\" font-size=\"7\">• The scheduler evaluates viable nodes in us-east-1b or 1c.</text>\n    <text x=\"18\" y=\"120\" fill=\"#cbd5e1\" font-size=\"7\">• The Pod is scheduled on the next best node without staying Pending.</text>\n    <text x=\"18\" y=\"132\" fill=\"#34d399\" font-size=\"6.5\">✓ High availability ensured in dynamic environments.</text>\n  </g>\n</svg>",
      "caption": "Afinidad de Nodos: required... impone una regla dura (si no se cumple, el pod permanece en Pending). preferred... establece una afinidad suave con puntuación, agendando en otra zona si la preferida no tiene capacidad.",
      "captionEn": "NodeAffinity comparison: requiredDuringScheduling enforces a hard filter (leaves pod Pending if unmet); preferredDuringScheduling grants scoring weight, falling back to other nodes if preferred nodes are full."
    },
    "kcna-28": {
      "badge": "Liveness vs Readiness",
      "title": "Sondas del Kubelet: Liveness (Reinicio) vs Readiness (Tráfico)",
      "titleEn": "Kubelet Probes: Liveness (Restart) vs Readiness (Traffic)",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">KUBELET PROBES: LIVENESS PROBE VS READINESS PROBE</text>\n  <!-- Liveness Probe Left -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#ef4444\"/>\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"22\" rx=\"5\" fill=\"#991b1b\"/>\n    <text x=\"12\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">LIVENESS PROBE</text>\n    <text x=\"12\" y=\"36\" fill=\"#fca5a5\" font-size=\"7.5\" font-weight=\"700\">Question: Is the container still alive or deadlocked?</text>\n    <rect x=\"12\" y=\"44\" width=\"277\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#ef4444\"/>\n    <text x=\"20\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6.5\">Checks local health endpoints:</text>\n    <text x=\"20\" y=\"70\" fill=\"#fca5a5\" font-size=\"7\" font-weight=\"800\">httpGet: /healthz (Fails 3 consecutive times)</text>\n    <rect x=\"12\" y=\"94\" width=\"277\" height=\"50\" rx=\"3\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n    <text x=\"20\" y=\"110\" fill=\"#f87171\" font-size=\"7.5\" font-weight=\"800\">KUBELET ACTION ON FAILURE:</text>\n    <text x=\"20\" y=\"124\" fill=\"#ffffff\" font-size=\"7\">Kills the container with SIGKILL and RESTARTS it.</text>\n    <text x=\"20\" y=\"136\" fill=\"#fca5a5\" font-size=\"6.5\">Increments the Pod's RESTARTS counter.</text>\n  </g>\n  <!-- Readiness Probe Right -->\n  <g transform=\"translate(350, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"12\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">READINESS PROBE</text>\n    <text x=\"12\" y=\"36\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">Question: Is the container ready to receive users?</text>\n    <rect x=\"12\" y=\"44\" width=\"277\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"20\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6.5\">Checks dependencies or warm-up:</text>\n    <text x=\"20\" y=\"70\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"800\">httpGet: /ready (Fails due to overload or startup)</text>\n    <rect x=\"12\" y=\"94\" width=\"277\" height=\"50\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n    <text x=\"20\" y=\"110\" fill=\"#34d399\" font-size=\"7.5\" font-weight=\"800\">KUBELET ACTION ON FAILURE:</text>\n    <text x=\"20\" y=\"124\" fill=\"#ffffff\" font-size=\"7\">The pod is NOT restarted. Its IP is removed from the Endpoints.</text>\n    <text x=\"20\" y=\"136\" fill=\"#d1fae5\" font-size=\"6.5\">No Service traffic is sent to it.</text>\n  </g>\n</svg>",
      "caption": "Comportamiento ante fallos: la livenessProbe reinicia el contenedor (para deadlocks internos); la readinessProbe NO reinicia el contenedor, sino que retira su IP de los Endpoints del Service para evitar errores 503 mientras el servicio se recupera.",
      "captionEn": "Failure behaviors compared: livenessProbe kills and restarts the container upon deadlock; readinessProbe leaves the container running but unregisters it from Service endpoints."
    },
    "kcna-29": {
      "badge": "startupProbe",
      "title": "startupProbe: Protección de Servicios con Arranque Lento",
      "titleEn": "startupProbe: Protection for Slow-Booting Applications",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">STARTUPPROBE: SUPPRESSING LIVENESS DURING INITIALIZATION</text>\n  <!-- Timeline Without startupProbe -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#ef4444\"/>\n    <text x=\"12\" y=\"18\" fill=\"#f87171\" font-size=\"8\" font-weight=\"800\">WITHOUT STARTUPPROBE (Restart loop)</text>\n    <g transform=\"translate(12, 30)\">\n      <text x=\"0\" y=\"12\" fill=\"#cbd5e1\" font-size=\"6.5\">The app takes 90s to load cache and dependencies:</text>\n      <!-- Timeline bar -->\n      <rect x=\"0\" y=\"20\" width=\"277\" height=\"16\" rx=\"2\" fill=\"#0f172a\" stroke=\"#475569\"/>\n      <rect x=\"0\" y=\"20\" width=\"80\" height=\"16\" rx=\"2\" fill=\"#ef4444\"/>\n      <text x=\"90\" y=\"32\" fill=\"#f87171\" font-size=\"6.5\">Liveness timeout (30s) ➔ KILL</text>\n      <rect x=\"0\" y=\"44\" width=\"277\" height=\"48\" rx=\"3\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n      <text x=\"10\" y=\"60\" fill=\"#fca5a5\" font-size=\"7\" font-weight=\"700\">Result: Permanent CrashLoopBackOff</text>\n      <text x=\"10\" y=\"74\" fill=\"#cbd5e1\" font-size=\"6.5\">The kubelet kills the pod before it finishes</text>\n      <text x=\"10\" y=\"86\" fill=\"#cbd5e1\" font-size=\"6.5\">initializing, preventing it from entering production.</text>\n    </g>\n  </g>\n  <!-- Timeline With startupProbe -->\n  <g transform=\"translate(350, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <text x=\"12\" y=\"18\" fill=\"#a7f3d0\" font-size=\"8\" font-weight=\"800\">WITH STARTUPPROBE (Native Solution)</text>\n    <g transform=\"translate(12, 30)\">\n      <text x=\"0\" y=\"12\" fill=\"#cbd5e1\" font-size=\"6.5\">startupProbe: failureThreshold: 30, periodSeconds: 5 (150s)</text>\n      <!-- Timeline bar -->\n      <rect x=\"0\" y=\"20\" width=\"277\" height=\"16\" rx=\"2\" fill=\"#0f172a\" stroke=\"#475569\"/>\n      <rect x=\"0\" y=\"20\" width=\"160\" height=\"16\" rx=\"2\" fill=\"#0284c7\"/>\n      <text x=\"170\" y=\"32\" fill=\"#38bdf8\" font-size=\"6.5\">Startup completed at 90s</text>\n      <rect x=\"0\" y=\"44\" width=\"277\" height=\"52\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n      <text x=\"10\" y=\"60\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"800\">✓ Liveness and Readiness stay disabled</text>\n      <text x=\"10\" y=\"74\" fill=\"#cbd5e1\" font-size=\"6.5\">until startupProbe succeeds.</text>\n      <text x=\"10\" y=\"88\" fill=\"#a7f3d0\" font-size=\"6.5\">Once it passes, liveness takes over normal monitoring.</text>\n    </g>\n  </g>\n</svg>",
      "caption": "Mecánica de startupProbe: otorga una ventana generosa de arranque (ej. hasta 150s) inhibiendo las comprobaciones de liveness y readiness. Al responder con éxito por primera vez, transfiere el control a liveness sin provocar reinicios prematuros.",
      "captionEn": "startupProbe mechanics: creates a startup buffer disabling liveness and readiness probes during initialization. Once successful, liveness monitoring activates without premature container kills."
    },
    "kcna-30": {
      "badge": "Escalabilidad HPA",
      "title": "Horizontal Pod Autoscaler (HPA): Escalado Automático según CPU",
      "titleEn": "Horizontal Pod Autoscaler (HPA): CPU-Driven Elastic Scaling",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">HORIZONTAL POD AUTOSCALER: METRICS-BASED SCALING CURVE</text>\n  <!-- Chart Left -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"350\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <text x=\"12\" y=\"18\" fill=\"#38bdf8\" font-size=\"8\" font-weight=\"800\">OBSERVED METRIC VS TARGET (Target: 70% CPU)</text>\n    <!-- Axis lines -->\n    <line x1=\"30\" y1=\"30\" x2=\"30\" y2=\"135\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n    <line x1=\"30\" y1=\"135\" x2=\"330\" y2=\"135\" stroke=\"#475569\" stroke-width=\"1.2\"/>\n    <text x=\"22\" y=\"45\" fill=\"#94a3b8\" font-size=\"6.5\" text-anchor=\"end\">100%</text>\n    <text x=\"22\" y=\"70\" fill=\"#fbbf24\" font-size=\"6.5\" text-anchor=\"end\">70%</text>\n    <line x1=\"30\" y1=\"68\" x2=\"330\" y2=\"68\" stroke=\"#f59e0b\" stroke-dasharray=\"2,2\"/>\n    <text x=\"22\" y=\"110\" fill=\"#94a3b8\" font-size=\"6.5\" text-anchor=\"end\">30%</text>\n    <!-- Curve -->\n    <path d=\"M 30 115 Q 100 110 140 50 T 230 45 T 320 100\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n    <text x=\"145\" y=\"40\" fill=\"#f87171\" font-size=\"6.5\" font-weight=\"800\">Load Spike (88%)</text>\n    <text x=\"250\" y=\"145\" fill=\"#94a3b8\" font-size=\"6\">Time (minutes)</text>\n  </g>\n  <!-- HPA Controller Logic Right -->\n  <g transform=\"translate(390, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"265\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"265\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">HPA RECONCILIATION</text>\n    <rect x=\"10\" y=\"30\" width=\"245\" height=\"40\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"16\" y=\"46\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">Desired Replicas Formula:</text>\n    <text x=\"16\" y=\"60\" fill=\"#38bdf8\" font-size=\"7\">ceil [ current_replicas * (current_usage / target) ]</text>\n    <g transform=\"translate(10, 78)\">\n      <rect x=\"0\" y=\"0\" width=\"118\" height=\"64\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n      <text x=\"8\" y=\"16\" fill=\"#93c5fd\" font-size=\"7\" font-weight=\"700\">Initial State:</text>\n      <text x=\"8\" y=\"30\" fill=\"#cbd5e1\" font-size=\"6.5\">• Replicas: 2</text>\n      <text x=\"8\" y=\"42\" fill=\"#cbd5e1\" font-size=\"6.5\">• CPU: 35%</text>\n      <text x=\"8\" y=\"54\" fill=\"#a7f3d0\" font-size=\"6.5\">Baseline traffic</text>\n      <rect x=\"126\" y=\"0\" width=\"119\" height=\"64\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n      <text x=\"134\" y=\"16\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"800\">After the Spike (HPA):</text>\n      <text x=\"134\" y=\"30\" fill=\"#ffffff\" font-size=\"6.5\">• Replicas: 5 (Scaled)</text>\n      <text x=\"134\" y=\"42\" fill=\"#ffffff\" font-size=\"6.5\">• CPU stabilized at 68%</text>\n      <text x=\"134\" y=\"54\" fill=\"#d1fae5\" font-size=\"6.5\">✓ Demand absorbed</text>\n    </g>\n  </g>\n</svg>",
      "caption": "Curva de escalabilidad del HPA: compara el uso medio de métricas (CPU/memoria vía metrics-server) con el objetivo definido. Al superar el 70%, incrementa las réplicas del Deployment para dispersar la carga, desescalando al cesar la demanda.",
      "captionEn": "HPA scaling dynamics: compares real-time resource utilization against target thresholds, scaling out Deployment replicas to absorb load spikes and scaling back when traffic normalizes."
    },
    "kcna-31": {
      "badge": "Almacenamiento CSI",
      "title": "Aprovisionamiento Dinámico de Almacenamiento: PVC ➔ StorageClass ➔ PV",
      "titleEn": "Dynamic Storage Provisioning: PVC ➔ StorageClass ➔ PV",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">PERSISTENT STORAGE FLOW: POD ➔ PVC ➔ STORAGECLASS ➔ PV</text>\n  <!-- Step 1: Pod -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"130\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <text x=\"10\" y=\"18\" fill=\"#38bdf8\" font-size=\"7.5\" font-weight=\"800\">1. POD (Developer)</text>\n    <rect x=\"8\" y=\"28\" width=\"114\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"14\" y=\"44\" fill=\"#ffffff\" font-size=\"7\">spec.volumes:</text>\n    <text x=\"14\" y=\"54\" fill=\"#93c5fd\" font-size=\"6\">persistentVolumeClaim:</text>\n    <text x=\"14\" y=\"64\" fill=\"#93c5fd\" font-size=\"6\">claimName: db-pvc</text>\n    <rect x=\"8\" y=\"76\" width=\"114\" height=\"40\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"14\" y=\"92\" fill=\"#ffffff\" font-size=\"7\">volumeMounts:</text>\n    <text x=\"14\" y=\"104\" fill=\"#cbd5e1\" font-size=\"6\">mountPath: /var/lib/db</text>\n  </g>\n  <!-- Arrow -->\n  <g transform=\"translate(160, 115)\">\n    <line x1=\"0\" y1=\"0\" x2=\"25\" y2=\"0\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n    <polygon points=\"25,0 18,-4 18,4\" fill=\"#38bdf8\"/>\n  </g>\n  <!-- Step 2: PVC -->\n  <g transform=\"translate(190, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"140\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <text x=\"10\" y=\"18\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"800\">2. PVC (Request)</text>\n    <rect x=\"8\" y=\"28\" width=\"124\" height=\"60\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"14\" y=\"44\" fill=\"#ffffff\" font-size=\"7\">metadata.name: db-pvc</text>\n    <text x=\"14\" y=\"56\" fill=\"#a7f3d0\" font-size=\"6\">storage: 100Gi</text>\n    <text x=\"14\" y=\"68\" fill=\"#a7f3d0\" font-size=\"6\">accessModes: [RWO]</text>\n    <text x=\"14\" y=\"80\" fill=\"#fbbf24\" font-size=\"6\">storageClassName: fast</text>\n    <rect x=\"8\" y=\"96\" width=\"124\" height=\"46\" rx=\"2\" fill=\"#064e3b\"/>\n    <text x=\"14\" y=\"112\" fill=\"#a7f3d0\" font-size=\"6.5\">Status: Bound</text>\n    <text x=\"14\" y=\"124\" fill=\"#d1fae5\" font-size=\"6\">Bound to real PV</text>\n  </g>\n  <!-- Arrow -->\n  <g transform=\"translate(335, 115)\">\n    <line x1=\"0\" y1=\"0\" x2=\"25\" y2=\"0\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n    <polygon points=\"25,0 18,-4 18,4\" fill=\"#f59e0b\"/>\n  </g>\n  <!-- Step 3: StorageClass & CSI -->\n  <g transform=\"translate(365, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"140\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n    <text x=\"10\" y=\"18\" fill=\"#fde68a\" font-size=\"7.5\" font-weight=\"800\">3. STORAGECLASS (CSI)</text>\n    <rect x=\"8\" y=\"28\" width=\"124\" height=\"60\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f59e0b\"/>\n    <text x=\"14\" y=\"44\" fill=\"#ffffff\" font-size=\"7\">name: fast</text>\n    <text x=\"14\" y=\"56\" fill=\"#fde68a\" font-size=\"6\">provisioner:</text>\n    <text x=\"14\" y=\"68\" fill=\"#fde68a\" font-size=\"6\">ebs.csi.aws.com</text>\n    <text x=\"14\" y=\"80\" fill=\"#cbd5e1\" font-size=\"6\">type: gp3, iops: 3000</text>\n    <rect x=\"8\" y=\"96\" width=\"124\" height=\"46\" rx=\"2\" fill=\"#78350f\"/>\n    <text x=\"14\" y=\"112\" fill=\"#fef08a\" font-size=\"6.5\">Calls Cloud API</text>\n    <text x=\"14\" y=\"124\" fill=\"#ffffff\" font-size=\"6\">Creates dynamic disk</text>\n  </g>\n  <!-- Arrow -->\n  <g transform=\"translate(510, 115)\">\n    <line x1=\"0\" y1=\"0\" x2=\"25\" y2=\"0\" stroke=\"#a78bfa\" stroke-width=\"2\"/>\n    <polygon points=\"25,0 18,-4 18,4\" fill=\"#a78bfa\"/>\n  </g>\n  <!-- Step 4: PV Cloud Block -->\n  <g transform=\"translate(540, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"115\" height=\"155\" rx=\"5\" fill=\"#2e1065\" stroke=\"#a78bfa\"/>\n    <text x=\"8\" y=\"18\" fill=\"#ddd6fe\" font-size=\"7.5\" font-weight=\"800\">4. CLOUD DISK</text>\n    <rect x=\"6\" y=\"28\" width=\"103\" height=\"60\" rx=\"3\" fill=\"#0f172a\" stroke=\"#a78bfa\"/>\n    <text x=\"10\" y=\"44\" fill=\"#ffffff\" font-size=\"7\">PersistentVolume</text>\n    <text x=\"10\" y=\"56\" fill=\"#c4b5fd\" font-size=\"6\">vol-09823fab</text>\n    <text x=\"10\" y=\"68\" fill=\"#c4b5fd\" font-size=\"6\">100 GiB SSD gp3</text>\n    <text x=\"10\" y=\"80\" fill=\"#a7f3d0\" font-size=\"6\">RWO · Encrypted</text>\n    <rect x=\"6\" y=\"96\" width=\"103\" height=\"46\" rx=\"2\" fill=\"#4c1d95\"/>\n    <text x=\"10\" y=\"112\" fill=\"#f5d0fe\" font-size=\"6.5\">Mounted on Node</text>\n    <text x=\"10\" y=\"124\" fill=\"#ffffff\" font-size=\"6\">Attached by CSI</text>\n  </g>\n</svg>",
      "caption": "Aprovisionamiento dinámico de almacenamiento: el Pod monta un PVC; el PVC invoca una StorageClass con el driver CSI; el driver interactúa con el proveedor cloud para crear el disco físico y enlaza el PersistentVolume (PV) correspondiente.",
      "captionEn": "Dynamic storage provisioning workflow: Pod mounts PVC; PVC references StorageClass calling CSI driver; CSI driver creates cloud disk volume and binds it to a PersistentVolume (PV)."
    },
    "kcna-33": {
      "badge": "Service Types",
      "title": "Niveles de Exposición de Tráfico: ClusterIP ➔ NodePort ➔ LoadBalancer",
      "titleEn": "Traffic Exposure Hierarchy: ClusterIP ➔ NodePort ➔ LoadBalancer",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">SERVICE HIERARCHY: CLUSTERIP, NODEPORT AND LOADBALANCER</text>\n  <!-- ClusterIP Box -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"195\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <rect x=\"0\" y=\"0\" width=\"195\" height=\"22\" rx=\"5\" fill=\"#0284c7\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">1. ClusterIP (Default)</text>\n    <rect x=\"10\" y=\"30\" width=\"175\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"18\" y=\"46\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"700\">Internal Virtual IP:</text>\n    <text x=\"18\" y=\"58\" fill=\"#ffffff\" font-size=\"7\">10.96.12.45:80</text>\n    <rect x=\"10\" y=\"80\" width=\"175\" height=\"62\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"18\" y=\"96\" fill=\"#cbd5e1\" font-size=\"6.5\">• Internal East-West traffic</text>\n    <text x=\"18\" y=\"108\" fill=\"#cbd5e1\" font-size=\"6.5\">• Not reachable from outside</text>\n    <text x=\"18\" y=\"120\" fill=\"#a7f3d0\" font-size=\"6.5\">✓ Ideal for DBs and microservices</text>\n  </g>\n  <!-- NodePort Box -->\n  <g transform=\"translate(240, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"195\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n    <rect x=\"0\" y=\"0\" width=\"195\" height=\"22\" rx=\"5\" fill=\"#b45309\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">2. NodePort (Superset of ClusterIP)</text>\n    <rect x=\"10\" y=\"30\" width=\"175\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f59e0b\"/>\n    <text x=\"18\" y=\"46\" fill=\"#fde68a\" font-size=\"7.5\" font-weight=\"700\">Static Port on Every Node:</text>\n    <text x=\"18\" y=\"58\" fill=\"#ffffff\" font-size=\"7\">&lt;NodeIP&gt;:31284</text>\n    <rect x=\"10\" y=\"80\" width=\"175\" height=\"62\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"18\" y=\"96\" fill=\"#cbd5e1\" font-size=\"6.5\">• Range: 30000 - 32767</text>\n    <text x=\"18\" y=\"108\" fill=\"#cbd5e1\" font-size=\"6.5\">• Creates a ClusterIP automatically</text>\n    <text x=\"18\" y=\"120\" fill=\"#fde68a\" font-size=\"6.5\">✓ Direct access by node IP</text>\n  </g>\n  <!-- LoadBalancer Box -->\n  <g transform=\"translate(455, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">3. LoadBalancer (Full Superset)</text>\n    <rect x=\"10\" y=\"30\" width=\"180\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"18\" y=\"46\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">External Cloud Load Balancer:</text>\n    <text x=\"18\" y=\"58\" fill=\"#ffffff\" font-size=\"7\">Public IP: 52.14.88.192:80</text>\n    <rect x=\"10\" y=\"80\" width=\"180\" height=\"62\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"18\" y=\"96\" fill=\"#cbd5e1\" font-size=\"6.5\">• Provisions AWS NLB / Azure LB / GCP</text>\n    <text x=\"18\" y=\"108\" fill=\"#cbd5e1\" font-size=\"6.5\">• Includes NodePort and ClusterIP</text>\n    <text x=\"18\" y=\"120\" fill=\"#a7f3d0\" font-size=\"6.5\">✓ Public exposure to the Internet</text>\n  </g>\n</svg>",
      "caption": "Jerarquía de tipos de Service: ClusterIP provee una IP interna virtual; NodePort expone un puerto (30000-32767) en la IP de cada nodo englobando a ClusterIP; LoadBalancer provisiona un balanceador externo en la nube englobando a ambos.",
      "captionEn": "Service type hierarchy: ClusterIP assigns an internal virtual IP; NodePort opens a port (30000-32767) on all node IPs wrapping ClusterIP; LoadBalancer provisions a public cloud load balancer wrapping both."
    },
    "kcna-34": {
      "badge": "NetworkPolicy Matrix",
      "title": "NetworkPolicy: Aislamiento Default-Deny y Matriz de Tráfico Ingress",
      "titleEn": "NetworkPolicy: Default-Deny Isolation & Ingress Traffic Matrix",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">NETWORKPOLICY: TRAFFIC MATRIX AND LAYER 3/4 ISOLATION</text>\n  <!-- Policy Definition Left -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"220\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#818cf8\"/>\n    <rect x=\"0\" y=\"0\" width=\"220\" height=\"22\" rx=\"5\" fill=\"#3730a3\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">NETWORKPOLICY RULE (YAML)</text>\n    <rect x=\"10\" y=\"30\" width=\"200\" height=\"115\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"16\" y=\"44\" fill=\"#c7d2fe\" font-size=\"6.5\">podSelector: { role: db }</text>\n    <text x=\"16\" y=\"56\" fill=\"#cbd5e1\" font-size=\"6.5\">policyTypes: [ Ingress ]</text>\n    <text x=\"16\" y=\"68\" fill=\"#fde68a\" font-size=\"6.5\">ingress:</text>\n    <text x=\"16\" y=\"80\" fill=\"#a7f3d0\" font-size=\"6.5\">- from:</text>\n    <text x=\"22\" y=\"92\" fill=\"#a7f3d0\" font-size=\"6.5\">  - podSelector: { app: payment }</text>\n    <text x=\"16\" y=\"104\" fill=\"#a7f3d0\" font-size=\"6.5\">  ports:</text>\n    <text x=\"22\" y=\"116\" fill=\"#a7f3d0\" font-size=\"6.5\">  - port: 5432 (Postgres)</text>\n    <text x=\"16\" y=\"132\" fill=\"#f87171\" font-size=\"6\">Implicit Default-Deny active</text>\n  </g>\n  <!-- Traffic Matrix Center-Right -->\n  <g transform=\"translate(265, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"390\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#334155\"/>\n    <text x=\"14\" y=\"18\" fill=\"#f8fafc\" font-size=\"8\" font-weight=\"800\">ACCESS EVALUATION FOR TARGET POD: role=db (Port 5432)</text>\n    <!-- Row 1: Authorized -->\n    <g transform=\"translate(14, 28)\">\n      <rect x=\"0\" y=\"0\" width=\"362\" height=\"34\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n      <text x=\"12\" y=\"16\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"800\">Pod: app=payment ➔ role=db:5432</text>\n      <text x=\"12\" y=\"27\" fill=\"#d1fae5\" font-size=\"6.5\">Matches authorized podSelector</text>\n      <text x=\"320\" y=\"22\" fill=\"#34d399\" font-size=\"10\" font-weight=\"800\">ALLOWED ✓</text>\n    </g>\n    <!-- Row 2: Denied different app -->\n    <g transform=\"translate(14, 68)\">\n      <rect x=\"0\" y=\"0\" width=\"362\" height=\"34\" rx=\"3\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n      <text x=\"12\" y=\"16\" fill=\"#fca5a5\" font-size=\"7.5\" font-weight=\"800\">Pod: app=analytics ➔ role=db:5432</text>\n      <text x=\"12\" y=\"27\" fill=\"#fecaca\" font-size=\"6.5\">Not in the selector allowlist</text>\n      <text x=\"320\" y=\"22\" fill=\"#ef4444\" font-size=\"10\" font-weight=\"800\">BLOCKED ✗</text>\n    </g>\n    <!-- Row 3: Denied wrong port -->\n    <g transform=\"translate(14, 108)\">\n      <rect x=\"0\" y=\"0\" width=\"362\" height=\"34\" rx=\"3\" fill=\"#450a0a\" stroke=\"#ef4444\"/>\n      <text x=\"12\" y=\"16\" fill=\"#fca5a5\" font-size=\"7.5\" font-weight=\"800\">Pod: app=payment ➔ role=db:22 (SSH)</text>\n      <text x=\"12\" y=\"27\" fill=\"#fecaca\" font-size=\"6.5\">Port not authorized in the ingress rule</text>\n      <text x=\"320\" y=\"22\" fill=\"#ef4444\" font-size=\"10\" font-weight=\"800\">BLOCKED ✗</text>\n    </g>\n  </g>\n</svg>",
      "caption": "NetworkPolicy de Kubernetes: aplica aislamiento de firewall capa 3/4. Al seleccionar un pod entra en modo default-deny, bloqueando todo el tráfico entrante salvo las combinaciones exactas de selectores y puertos explícitamente autorizados.",
      "captionEn": "Kubernetes NetworkPolicy traffic filtering: isolated pods enter default-deny mode, discarding all ingress packets except those matching whitelisted podSelectors and port definitions."
    },
    "kcna-37": {
      "badge": "CNCF Graduation",
      "title": "Niveles de Madurez de Proyectos CNCF: Sandbox, Incubating y Graduated",
      "titleEn": "CNCF Project Maturity Levels: Sandbox, Incubating & Graduated",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">CNCF PROJECT GRADUATION CRITERIA</text>\n  <!-- 3 Stages Progression -->\n  <g transform=\"translate(25, 45)\">\n    <!-- Stage 1: Sandbox -->\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"22\" rx=\"5\" fill=\"#b45309\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">1. SANDBOX (Experimental)</text>\n    <rect x=\"10\" y=\"30\" width=\"180\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f59e0b\"/>\n    <text x=\"16\" y=\"46\" fill=\"#fde68a\" font-size=\"7.5\" font-weight=\"700\">Level Goal:</text>\n    <text x=\"16\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6.5\">Early innovation and community building</text>\n    <rect x=\"10\" y=\"80\" width=\"180\" height=\"64\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"16\" y=\"96\" fill=\"#cbd5e1\" font-size=\"6.5\">• Minimum adoption requirements</text>\n    <text x=\"16\" y=\"108\" fill=\"#cbd5e1\" font-size=\"6.5\">• Governance in formation</text>\n    <text x=\"16\" y=\"120\" fill=\"#fde68a\" font-size=\"6.5\">Examples: OpenFeature, Telepresence</text>\n  </g>\n  <!-- Stage 2: Incubating -->\n  <g transform=\"translate(240, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"22\" rx=\"5\" fill=\"#0284c7\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">2. INCUBATING (Production)</text>\n    <rect x=\"10\" y=\"30\" width=\"180\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"16\" y=\"46\" fill=\"#7dd3fc\" font-size=\"7.5\" font-weight=\"700\">Level Goal:</text>\n    <text x=\"16\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6.5\">Demonstrated adoption and stability</text>\n    <rect x=\"10\" y=\"80\" width=\"180\" height=\"64\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"16\" y=\"96\" fill=\"#cbd5e1\" font-size=\"6.5\">• Documented real production use</text>\n    <text x=\"16\" y=\"108\" fill=\"#cbd5e1\" font-size=\"6.5\">• Sustained release process</text>\n    <text x=\"16\" y=\"120\" fill=\"#7dd3fc\" font-size=\"6.5\">Examples: gRPC, Dapr, Notary, Thanos</text>\n  </g>\n  <!-- Stage 3: Graduated -->\n  <g transform=\"translate(455, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"155\" rx=\"5\" fill=\"#064e3b\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">3. GRADUATED (Highest Maturity)</text>\n    <rect x=\"10\" y=\"30\" width=\"180\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"16\" y=\"46\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"800\">Golden Requirements:</text>\n    <text x=\"16\" y=\"58\" fill=\"#ffffff\" font-size=\"6.5\">Formal independent security audit</text>\n    <rect x=\"10\" y=\"80\" width=\"180\" height=\"64\" rx=\"3\" fill=\"#0f172a\" stroke=\"#334155\"/>\n    <text x=\"16\" y=\"96\" fill=\"#a7f3d0\" font-size=\"6.5\">• Neutral and diverse governance</text>\n    <text x=\"16\" y=\"108\" fill=\"#a7f3d0\" font-size=\"6.5\">• Global mission-critical use</text>\n    <text x=\"16\" y=\"120\" fill=\"#ffffff\" font-size=\"6.5\" font-weight=\"700\">K8s, Prometheus, Envoy, Helm, OTel</text>\n  </g>\n</svg>",
      "caption": "Niveles de graduación en CNCF: Sandbox evalúa proyectos iniciales; Incubating certifica uso en producción y sostenibilidad; Graduated exige el estándar más alto: auditoría formal de seguridad independiente, gobernanza abierta neutral y resiliencia corporativa masiva.",
      "captionEn": "CNCF graduation stages: Sandbox tests novel concepts; Incubating proves production adoption; Graduated certifies vendor neutrality, independent security audits, and enterprise-grade maturity."
    },
    "kcna-38": {
      "badge": "Service Mesh Envoy",
      "title": "Malla de Servicios (Service Mesh): Sidecars Envoy e Interceptación mTLS",
      "titleEn": "Service Mesh Architecture: Envoy Sidecars & Transparent mTLS",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">SERVICE MESH: TRANSPARENT INTERCEPTION IN THE DATA PLANE</text>\n  <!-- Service A Pod -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"220\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#3b82f6\"/>\n    <rect x=\"0\" y=\"0\" width=\"220\" height=\"22\" rx=\"5\" fill=\"#1d4ed8\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">POD: billing-service</text>\n    <!-- App container -->\n    <rect x=\"10\" y=\"30\" width=\"200\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#3b82f6\"/>\n    <text x=\"16\" y=\"46\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"700\">App Container (Go/Java code)</text>\n    <text x=\"16\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6.5\">Sends plain HTTP: http://orders-svc:80</text>\n    <!-- Envoy sidecar -->\n    <rect x=\"10\" y=\"80\" width=\"200\" height=\"62\" rx=\"3\" fill=\"#2e1065\" stroke=\"#a78bfa\" stroke-width=\"1.5\"/>\n    <text x=\"16\" y=\"96\" fill=\"#ddd6fe\" font-size=\"7.5\" font-weight=\"800\">Envoy Sidecar Proxy (Data Plane)</text>\n    <text x=\"16\" y=\"108\" fill=\"#cbd5e1\" font-size=\"6.5\">• Intercepts socket via iptables REDIRECT</text>\n    <text x=\"16\" y=\"120\" fill=\"#a7f3d0\" font-size=\"6.5\">• Negotiates TLS handshake with certificate</text>\n    <text x=\"16\" y=\"132\" fill=\"#38bdf8\" font-size=\"6.5\">• Injects W3C trace headers (traceparent)</text>\n  </g>\n  <!-- mTLS Tunnel Center -->\n  <g transform=\"translate(255, 105)\">\n    <rect x=\"0\" y=\"0\" width=\"170\" height=\"42\" rx=\"4\" fill=\"#064e3b\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <text x=\"85\" y=\"18\" fill=\"#a7f3d0\" font-size=\"8\" font-weight=\"800\" text-anchor=\"middle\">mTLS TUNNEL (Layer 7)</text>\n    <text x=\"85\" y=\"32\" fill=\"#d1fae5\" font-size=\"6.5\" text-anchor=\"middle\">AES-256 encryption + SPIFFE authentication</text>\n    <line x1=\"-10\" y1=\"21\" x2=\"0\" y2=\"21\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <line x1=\"170\" y1=\"21\" x2=\"180\" y2=\"21\" stroke=\"#10b981\" stroke-width=\"2\"/>\n  </g>\n  <!-- Service B Pod -->\n  <g transform=\"translate(435, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"220\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"220\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">POD: orders-service</text>\n    <!-- Envoy sidecar -->\n    <rect x=\"10\" y=\"30\" width=\"200\" height=\"62\" rx=\"3\" fill=\"#2e1065\" stroke=\"#a78bfa\" stroke-width=\"1.5\"/>\n    <text x=\"16\" y=\"46\" fill=\"#ddd6fe\" font-size=\"7.5\" font-weight=\"800\">Envoy Sidecar Proxy</text>\n    <text x=\"16\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6.5\">• Validates the client's cryptographic identity</text>\n    <text x=\"16\" y=\"70\" fill=\"#a7f3d0\" font-size=\"6.5\">• Decrypts TLS traffic</text>\n    <text x=\"16\" y=\"82\" fill=\"#cbd5e1\" font-size=\"6.5\">• Forwards plain HTTP to localhost:8080</text>\n    <!-- App container -->\n    <rect x=\"10\" y=\"100\" width=\"200\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"16\" y=\"116\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">App Container (Backend)</text>\n    <text x=\"16\" y=\"128\" fill=\"#cbd5e1\" font-size=\"6.5\">Receives plain HTTP on localhost:8080</text>\n  </g>\n</svg>",
      "caption": "Service Mesh en acción: el proxy sidecar Envoy intercepta el tráfico del contenedor de aplicación. Cifra la comunicación mediante mTLS y recopila métricas y trazas de forma transparente, sin que los desarrolladores modifiquen su código fuente.",
      "captionEn": "Service Mesh in practice: Envoy sidecars transparently intercept application sockets, encrypting East-West traffic via mTLS and emitting telemetry without codebase changes."
    },
    "kcna-39": {
      "badge": "RBAC Authorization",
      "title": "Modelo de Autorización RBAC: Roles, ClusterRoles y Bindings",
      "titleEn": "RBAC Authorization Model: Roles, ClusterRoles & Bindings",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">RBAC: NAMESPACE SCOPE (ROLE) VS GLOBAL SCOPE (CLUSTERROLE)</text>\n  <!-- Left: Namespace Scope -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"22\" rx=\"5\" fill=\"#0284c7\"/>\n    <text x=\"12\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">NAMESPACE SCOPE (Role &amp; RoleBinding)</text>\n    <rect x=\"12\" y=\"30\" width=\"277\" height=\"44\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"18\" y=\"46\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"700\">Object: Role (In namespace 'staging')</text>\n    <text x=\"18\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6.5\">rules: apiGroups: [\"\"], resources: [\"pods\", \"logs\"]</text>\n    <text x=\"18\" y=\"68\" fill=\"#cbd5e1\" font-size=\"6.5\">verbs: [\"get\", \"list\", \"watch\"]</text>\n    <line x1=\"150\" y1=\"74\" x2=\"150\" y2=\"86\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n    <rect x=\"12\" y=\"88\" width=\"277\" height=\"58\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n    <text x=\"18\" y=\"104\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">Object: RoleBinding (In 'staging')</text>\n    <text x=\"18\" y=\"118\" fill=\"#cbd5e1\" font-size=\"6.5\">subjects: user: \"developer-bob\" ➔ roleRef: 'staging-reader'</text>\n    <text x=\"18\" y=\"134\" fill=\"#34d399\" font-size=\"7\" font-weight=\"700\">✓ Bob can only read pods in staging, NOTHING ELSE.</text>\n  </g>\n  <!-- Right: Cluster Scope -->\n  <g transform=\"translate(350, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#a78bfa\"/>\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"22\" rx=\"5\" fill=\"#6d28d9\"/>\n    <text x=\"12\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">GLOBAL SCOPE (ClusterRole &amp; Binding)</text>\n    <rect x=\"12\" y=\"30\" width=\"277\" height=\"44\" rx=\"3\" fill=\"#0f172a\" stroke=\"#a78bfa\"/>\n    <text x=\"18\" y=\"46\" fill=\"#c4b5fd\" font-size=\"7.5\" font-weight=\"700\">Object: ClusterRole (Global)</text>\n    <text x=\"18\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6.5\">Applies to non-namespaced resources (nodes, pvs)</text>\n    <text x=\"18\" y=\"68\" fill=\"#cbd5e1\" font-size=\"6.5\">or to all namespaces of the physical cluster.</text>\n    <line x1=\"150\" y1=\"74\" x2=\"150\" y2=\"86\" stroke=\"#a78bfa\" stroke-width=\"1.5\"/>\n    <rect x=\"12\" y=\"88\" width=\"277\" height=\"58\" rx=\"3\" fill=\"#2e1065\" stroke=\"#a78bfa\"/>\n    <text x=\"18\" y=\"104\" fill=\"#ddd6fe\" font-size=\"7.5\" font-weight=\"700\">Object: ClusterRoleBinding</text>\n    <text x=\"18\" y=\"118\" fill=\"#cbd5e1\" font-size=\"6.5\">subjects: group: \"cluster-admins\" ➔ clusterRoleRef</text>\n    <text x=\"18\" y=\"134\" fill=\"#fca5a5\" font-size=\"7\" font-weight=\"700\">⚠️ Grants global permissions over the entire cluster.</text>\n  </g>\n</svg>",
      "caption": "Modelo RBAC: un Role define permisos delimitados a un único namespace (vinculado por RoleBinding); un ClusterRole define permisos a nivel de todo el clúster o recursos de nodo (vinculado por ClusterRoleBinding).",
      "captionEn": "Kubernetes RBAC model: Role binds namespace-scoped permissions via RoleBinding; ClusterRole grants cluster-wide permissions across all namespaces via ClusterRoleBinding."
    },
    "kcna-41": {
      "badge": "Gateway API",
      "title": "Evolución de Enrutamiento: Ingress Clásico vs Gateway API Desacoplada",
      "titleEn": "Routing Evolution: Traditional Ingress vs Role-Oriented Gateway API",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">L7 ROUTING EVOLUTION: INGRESS VS CNCF GATEWAY API</text>\n  <!-- Ingress Left -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"240\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#ef4444\"/>\n    <rect x=\"0\" y=\"0\" width=\"240\" height=\"22\" rx=\"5\" fill=\"#991b1b\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">TRADITIONAL INGRESS (Monolithic)</text>\n    <rect x=\"10\" y=\"30\" width=\"220\" height=\"115\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"16\" y=\"46\" fill=\"#fca5a5\" font-size=\"7\" font-weight=\"700\">Known Limitations:</text>\n    <text x=\"16\" y=\"60\" fill=\"#cbd5e1\" font-size=\"6.5\">• Everything concentrated in a single YAML object</text>\n    <text x=\"16\" y=\"72\" fill=\"#cbd5e1\" font-size=\"6.5\">• Overload of proprietary annotations</text>\n    <text x=\"16\" y=\"82\" fill=\"#94a3b8\" font-size=\"6\">  nginx.ingress.kubernetes.io/rewrite-target</text>\n    <text x=\"16\" y=\"94\" fill=\"#cbd5e1\" font-size=\"6.5\">• No standard support for Canary or gRPC</text>\n    <text x=\"16\" y=\"106\" fill=\"#cbd5e1\" font-size=\"6.5\">• Role conflict (infra vs developer)</text>\n    <text x=\"16\" y=\"128\" fill=\"#f87171\" font-size=\"7\" font-weight=\"700\">Rigid coupling of responsibilities</text>\n  </g>\n  <!-- Gateway API Right -->\n  <g transform=\"translate(285, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"370\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"370\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"12\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">GATEWAY API (CNCF Role-Oriented Design)</text>\n    <!-- Role 1: Infra -->\n    <rect x=\"12\" y=\"28\" width=\"346\" height=\"34\" rx=\"3\" fill=\"#0f172a\" stroke=\"#3b82f6\"/>\n    <text x=\"20\" y=\"42\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"800\">GatewayClass (Cloud Infrastructure Provider):</text>\n    <text x=\"20\" y=\"54\" fill=\"#cbd5e1\" font-size=\"6.5\">Defines the L7 controller (Envoy Gateway, Istio, Cilium, AWS VPC Lattice).</text>\n    <!-- Role 2: Cluster Operator -->\n    <rect x=\"12\" y=\"68\" width=\"346\" height=\"34\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f59e0b\"/>\n    <text x=\"20\" y=\"82\" fill=\"#fde68a\" font-size=\"7.5\" font-weight=\"800\">Gateway (Network / Cluster Operator):</text>\n    <text x=\"20\" y=\"94\" fill=\"#cbd5e1\" font-size=\"6.5\">Manages ingress IP, ports (80/443), TLS policies and global listeners.</text>\n    <!-- Role 3: App Developer -->\n    <rect x=\"12\" y=\"108\" width=\"346\" height=\"36\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n    <text x=\"20\" y=\"122\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"800\">HTTPRoute / GRPCRoute (Application Developer):</text>\n    <text x=\"20\" y=\"134\" fill=\"#d1fae5\" font-size=\"6.5\">Defines routing rules (/api/*), percentage splitting (Canary) and L7 filters.</text>\n  </g>\n</svg>",
      "caption": "Gateway API desacopla el enrutamiento: GatewayClass es gestionada por el administrador de infraestructura; Gateway por el operador de clúster (puertos y TLS); y HTTPRoute por los desarrolladores para definir rutas y división ponderada de tráfico.",
      "captionEn": "Gateway API role-oriented separation: GatewayClass is maintained by cloud infra admins; Gateway by cluster operators (ports/TLS); and HTTPRoute by app developers for path matching and Canary splits."
    },
    "kcna-44": {
      "badge": "Prometheus Scraping",
      "title": "Arquitectura de Prometheus: Scraping Pull HTTP, TSDB y PromQL",
      "titleEn": "Prometheus Architecture: Pull Scraping, TSDB & PromQL",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">PROMETHEUS: PULL COLLECTION MODEL OVER /METRICS ENDPOINTS</text>\n  <!-- Targets Left -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"180\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <text x=\"10\" y=\"18\" fill=\"#38bdf8\" font-size=\"8\" font-weight=\"800\">HTTP TARGETS (/metrics)</text>\n    <rect x=\"8\" y=\"28\" width=\"164\" height=\"34\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"14\" y=\"44\" fill=\"#ffffff\" font-size=\"7\">App Pod :8080/metrics</text>\n    <text x=\"14\" y=\"55\" fill=\"#93c5fd\" font-size=\"6.5\">http_requests_total{code=\"200\"}</text>\n    <rect x=\"8\" y=\"68\" width=\"164\" height=\"34\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"14\" y=\"84\" fill=\"#ffffff\" font-size=\"7\">cAdvisor (Kubelet :10250)</text>\n    <text x=\"14\" y=\"95\" fill=\"#a7f3d0\" font-size=\"6.5\">container_cpu_usage_seconds</text>\n    <rect x=\"8\" y=\"108\" width=\"164\" height=\"34\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"14\" y=\"124\" fill=\"#ffffff\" font-size=\"7\">node-exporter :9100</text>\n    <text x=\"14\" y=\"135\" fill=\"#fde68a\" font-size=\"6.5\">node_memory_MemAvailable_bytes</text>\n  </g>\n  <!-- Pull HTTP arrow -->\n  <g transform=\"translate(210, 115)\">\n    <line x1=\"0\" y1=\"0\" x2=\"35\" y2=\"0\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n    <polygon points=\"0,0 6,-4 6,4\" fill=\"#f59e0b\"/>\n    <text x=\"18\" y=\"-7\" fill=\"#f59e0b\" font-size=\"6.5\" font-weight=\"700\" text-anchor=\"middle\">HTTP GET</text>\n    <text x=\"18\" y=\"14\" fill=\"#94a3b8\" font-size=\"6\" text-anchor=\"middle\">Interval: 15s</text>\n  </g>\n  <!-- Prometheus Core Center -->\n  <g transform=\"translate(250, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"220\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n    <rect x=\"0\" y=\"0\" width=\"220\" height=\"22\" rx=\"5\" fill=\"#b45309\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">PROMETHEUS CORE (TSDB)</text>\n    <rect x=\"10\" y=\"30\" width=\"200\" height=\"52\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f59e0b\"/>\n    <text x=\"16\" y=\"46\" fill=\"#fde68a\" font-size=\"7.5\" font-weight=\"700\">Time Series Database:</text>\n    <text x=\"16\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6.5\">• Metric + Labels (key-value)</text>\n    <text x=\"16\" y=\"70\" fill=\"#cbd5e1\" font-size=\"6.5\">• Timestamp + Float64 (Compressed)</text>\n    <rect x=\"10\" y=\"90\" width=\"200\" height=\"50\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"16\" y=\"106\" fill=\"#7dd3fc\" font-size=\"7.5\" font-weight=\"700\">PromQL Rules Engine:</text>\n    <text x=\"16\" y=\"118\" fill=\"#cbd5e1\" font-size=\"6.5\">rate(http_requests_total[5m]) &gt; 10</text>\n    <text x=\"16\" y=\"130\" fill=\"#fca5a5\" font-size=\"6.5\">Continuously evaluates alert rules</text>\n  </g>\n  <!-- Egress to Alertmanager and Grafana -->\n  <g transform=\"translate(490, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"165\" height=\"72\" rx=\"4\" fill=\"#1e293b\" stroke=\"#ef4444\"/>\n    <text x=\"10\" y=\"18\" fill=\"#f87171\" font-size=\"7.5\" font-weight=\"800\">ALERTMANAGER</text>\n    <text x=\"10\" y=\"32\" fill=\"#cbd5e1\" font-size=\"6.5\">Receives fired alerts</text>\n    <text x=\"10\" y=\"44\" fill=\"#cbd5e1\" font-size=\"6.5\">• Groups and deduplicates</text>\n    <text x=\"10\" y=\"56\" fill=\"#a7f3d0\" font-size=\"6.5\">➔ Slack / PagerDuty</text>\n    <rect x=\"0\" y=\"83\" width=\"165\" height=\"72\" rx=\"4\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <text x=\"10\" y=\"101\" fill=\"#38bdf8\" font-size=\"7.5\" font-weight=\"800\">GRAFANA</text>\n    <text x=\"10\" y=\"115\" fill=\"#cbd5e1\" font-size=\"6.5\">PromQL queries</text>\n    <text x=\"10\" y=\"127\" fill=\"#cbd5e1\" font-size=\"6.5\">• Trend charts</text>\n    <text x=\"10\" y=\"139\" fill=\"#fde68a\" font-size=\"6.5\">➔ SLO dashboards</text>\n  </g>\n</svg>",
      "caption": "Arquitectura de Prometheus: opera mediante sondeo activo (pull model) extrayendo métricas vía HTTP GET de /metrics. Guarda las series temporales en su TSDB local y utiliza PromQL para proyectar tableros en Grafana y disparar notificaciones en Alertmanager.",
      "captionEn": "Prometheus pull scraping pipeline: periodically queries targets at HTTP /metrics, stores time-series samples in local TSDB, and executes PromQL queries for dashboards and Alertmanager."
    },
    "kcna-45": {
      "badge": "OpenTelemetry OTel",
      "title": "OpenTelemetry (OTel): OTLP, SDKs y Procesamiento en OTel Collector",
      "titleEn": "OpenTelemetry (OTel): OTLP, Language SDKs & Collector Pipeline",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">OPENTELEMETRY: VENDOR-AGNOSTIC INSTRUMENTATION AND COLLECTOR PIPELINE</text>\n  <!-- Applications Left -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"160\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <text x=\"10\" y=\"18\" fill=\"#38bdf8\" font-size=\"8\" font-weight=\"800\">APPLICATIONS (OTel SDK)</text>\n    <rect x=\"8\" y=\"28\" width=\"144\" height=\"34\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"14\" y=\"44\" fill=\"#ffffff\" font-size=\"7\">Go Microservice</text>\n    <text x=\"14\" y=\"55\" fill=\"#93c5fd\" font-size=\"6.5\">OTel Go SDK (Auto/Manual)</text>\n    <rect x=\"8\" y=\"68\" width=\"144\" height=\"34\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"14\" y=\"84\" fill=\"#ffffff\" font-size=\"7\">Java Microservice</text>\n    <text x=\"14\" y=\"95\" fill=\"#a7f3d0\" font-size=\"6.5\">Java Auto-Instrumentation</text>\n    <rect x=\"8\" y=\"108\" width=\"144\" height=\"34\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"14\" y=\"124\" fill=\"#ffffff\" font-size=\"7\">Python Microservice</text>\n    <text x=\"14\" y=\"135\" fill=\"#fde68a\" font-size=\"6.5\">opentelemetry-distro</text>\n  </g>\n  <!-- Protocol OTLP Arrow -->\n  <g transform=\"translate(190, 115)\">\n    <line x1=\"0\" y1=\"0\" x2=\"35\" y2=\"0\" stroke=\"#f59e0b\" stroke-width=\"2.5\"/>\n    <polygon points=\"35,0 27,-5 27,5\" fill=\"#f59e0b\"/>\n    <text x=\"18\" y=\"-7\" fill=\"#fbbf24\" font-size=\"7\" font-weight=\"800\" text-anchor=\"middle\">OTLP</text>\n    <text x=\"18\" y=\"14\" fill=\"#94a3b8\" font-size=\"6\" text-anchor=\"middle\">gRPC / HTTP</text>\n  </g>\n  <!-- OTel Collector Center -->\n  <g transform=\"translate(230, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"250\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n    <rect x=\"0\" y=\"0\" width=\"250\" height=\"22\" rx=\"5\" fill=\"#b45309\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">OPENTELEMETRY COLLECTOR</text>\n    <!-- Receiver -->\n    <rect x=\"10\" y=\"30\" width=\"70\" height=\"60\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"14\" y=\"46\" fill=\"#38bdf8\" font-size=\"7\" font-weight=\"700\">Receivers:</text>\n    <text x=\"14\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6\">otlp (4317)</text>\n    <text x=\"14\" y=\"68\" fill=\"#cbd5e1\" font-size=\"6\">jaeger</text>\n    <text x=\"14\" y=\"78\" fill=\"#cbd5e1\" font-size=\"6\">prometheus</text>\n    <!-- Processor -->\n    <rect x=\"88\" y=\"30\" width=\"74\" height=\"60\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f59e0b\"/>\n    <text x=\"92\" y=\"46\" fill=\"#fbbf24\" font-size=\"7\" font-weight=\"700\">Processors:</text>\n    <text x=\"92\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6\">batch</text>\n    <text x=\"92\" y=\"68\" fill=\"#cbd5e1\" font-size=\"6\">memory_lim</text>\n    <text x=\"92\" y=\"78\" fill=\"#cbd5e1\" font-size=\"6\">sampling</text>\n    <!-- Exporter -->\n    <rect x=\"170\" y=\"30\" width=\"70\" height=\"60\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"174\" y=\"46\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"700\">Exporters:</text>\n    <text x=\"174\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6\">otlp / http</text>\n    <text x=\"174\" y=\"68\" fill=\"#cbd5e1\" font-size=\"6\">prometheus</text>\n    <text x=\"174\" y=\"78\" fill=\"#cbd5e1\" font-size=\"6\">logging</text>\n    <rect x=\"10\" y=\"98\" width=\"230\" height=\"42\" rx=\"3\" fill=\"#064e3b\"/>\n    <text x=\"16\" y=\"114\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"800\">Absolute Neutrality (No Lock-in):</text>\n    <text x=\"16\" y=\"126\" fill=\"#d1fae5\" font-size=\"6.5\">Changing the backend only requires editing the Collector YAML.</text>\n  </g>\n  <!-- Output Backends Right -->\n  <g transform=\"translate(490, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"165\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#334155\"/>\n    <text x=\"10\" y=\"18\" fill=\"#ffffff\" font-size=\"8\" font-weight=\"800\">DATA DESTINATIONS</text>\n    <rect x=\"8\" y=\"28\" width=\"149\" height=\"34\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f59e0b\"/>\n    <text x=\"14\" y=\"44\" fill=\"#fde68a\" font-size=\"7\">Prometheus / Mimir</text>\n    <text x=\"14\" y=\"55\" fill=\"#cbd5e1\" font-size=\"6.5\">Metrics Store</text>\n    <rect x=\"8\" y=\"68\" width=\"149\" height=\"34\" rx=\"3\" fill=\"#0f172a\" stroke=\"#a78bfa\"/>\n    <text x=\"14\" y=\"84\" fill=\"#c4b5fd\" font-size=\"7\">Jaeger / Tempo</text>\n    <text x=\"14\" y=\"95\" fill=\"#cbd5e1\" font-size=\"6.5\">Traces Store</text>\n    <rect x=\"8\" y=\"108\" width=\"149\" height=\"34\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"14\" y=\"124\" fill=\"#a7f3d0\" font-size=\"7\">Loki / Elasticsearch</text>\n    <text x=\"14\" y=\"135\" fill=\"#cbd5e1\" font-size=\"6.5\">Logs Store</text>\n  </g>\n</svg>",
      "caption": "OpenTelemetry unifica la telemetría: los SDKs emiten métricas, trazas y logs mediante OTLP hacia el OTel Collector. Este procesa, filtra y distribuye los datos hacia backends especializados (Prometheus, Jaeger, Loki) sin atar el código a ningún proveedor.",
      "captionEn": "OpenTelemetry unified telemetry pipeline: language SDKs transmit telemetry via OTLP to OTel Collector, which batches, filters, and fans out data to Prometheus, Jaeger, and Loki."
    },
    "kcna-47": {
      "badge": "GitOps ArgoCD",
      "title": "Reconciliación GitOps: Detección de Drift y Auto-Curación (Self-Healing)",
      "titleEn": "GitOps Reconciliation: Drift Detection & Self-Healing Loop",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">GITOPS RECONCILIATION: DRIFT DETECTION AND AUTOMATIC REVERSION</text>\n  <!-- Git Desired State Left -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"190\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f43f5e\"/>\n    <rect x=\"0\" y=\"0\" width=\"190\" height=\"22\" rx=\"5\" fill=\"#be123c\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">GIT (Desired State)</text>\n    <rect x=\"10\" y=\"30\" width=\"170\" height=\"50\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fb7185\"/>\n    <text x=\"16\" y=\"46\" fill=\"#ffffff\" font-size=\"7\">main branch (Commit: a7f89)</text>\n    <text x=\"16\" y=\"58\" fill=\"#93c5fd\" font-size=\"6.5\">Deployment: payment-api</text>\n    <text x=\"16\" y=\"70\" fill=\"#a7f3d0\" font-size=\"6.5\">replicas: 3 · image: v2.1.0</text>\n    <rect x=\"10\" y=\"90\" width=\"170\" height=\"52\" rx=\"3\" fill=\"#0f172a\" stroke=\"#334155\"/>\n    <text x=\"16\" y=\"106\" fill=\"#cbd5e1\" font-size=\"6.5\">Cryptographic Audit:</text>\n    <text x=\"16\" y=\"118\" fill=\"#cbd5e1\" font-size=\"6.5\">• Who authorized the change</text>\n    <text x=\"16\" y=\"130\" fill=\"#cbd5e1\" font-size=\"6.5\">• Pull Request history</text>\n  </g>\n  <!-- ArgoCD Reconciler Center -->\n  <g transform=\"translate(230, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"220\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <rect x=\"0\" y=\"0\" width=\"220\" height=\"22\" rx=\"5\" fill=\"#0284c7\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">ARGOCD APPLICATION CONTROLLER</text>\n    <rect x=\"10\" y=\"30\" width=\"200\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#ef4444\"/>\n    <text x=\"16\" y=\"46\" fill=\"#fca5a5\" font-size=\"7.5\" font-weight=\"800\">Alert: OutOfSync (Drift)!</text>\n    <text x=\"16\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6.5\">Someone edited with 'kubectl edit' in the cluster</text>\n    <line x1=\"110\" y1=\"72\" x2=\"110\" y2=\"82\" stroke=\"#10b981\" stroke-width=\"2\"/>\n    <polygon points=\"110,82 106,76 114,76\" fill=\"#10b981\"/>\n    <!-- Self-Healing action -->\n    <rect x=\"10\" y=\"84\" width=\"200\" height=\"58\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n    <text x=\"16\" y=\"100\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"800\">Automatic Self-Healing Active:</text>\n    <text x=\"16\" y=\"114\" fill=\"#ffffff\" font-size=\"6.5\">Overwrites the illegal manual change and</text>\n    <text x=\"16\" y=\"126\" fill=\"#ffffff\" font-size=\"6.5\">forces the cluster to match Git.</text>\n    <text x=\"16\" y=\"136\" fill=\"#34d399\" font-size=\"6.5\">➔ Status returns to 'Synced' in 2s.</text>\n  </g>\n  <!-- Cluster State Right -->\n  <g transform=\"translate(465, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"190\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"190\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">CLUSTER (Actual State)</text>\n    <rect x=\"10\" y=\"30\" width=\"170\" height=\"50\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"16\" y=\"46\" fill=\"#a7f3d0\" font-size=\"7\">Deployment: payment-api</text>\n    <text x=\"16\" y=\"58\" fill=\"#34d399\" font-size=\"6.5\">replicas: 3 (Restored)</text>\n    <text x=\"16\" y=\"70\" fill=\"#cbd5e1\" font-size=\"6.5\">image: v2.1.0</text>\n    <rect x=\"10\" y=\"90\" width=\"170\" height=\"52\" rx=\"3\" fill=\"#0f172a\" stroke=\"#334155\"/>\n    <text x=\"16\" y=\"106\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"800\">Guaranteed Security:</text>\n    <text x=\"16\" y=\"118\" fill=\"#cbd5e1\" font-size=\"6.5\">• Zero orphaned manual changes</text>\n    <text x=\"16\" y=\"130\" fill=\"#cbd5e1\" font-size=\"6.5\">• Full auditability in PRs</text>\n  </g>\n</svg>",
      "caption": "Reconciliación y Auto-Curación en GitOps: si un operador altera un recurso manualmente con kubectl en el clúster, ArgoCD detecta la divergencia (Drift) y su mecanismo de Self-Healing revierte la modificación para forzar que el clúster refleje el commit en Git.",
      "captionEn": "GitOps drift reconciliation and self-healing: if an engineer applies out-of-band kubectl edits, ArgoCD detects state drift and overwrites the manual changes to match the Git commit."
    },
    "kcna-50": {
      "badge": "Canary Deployment",
      "title": "Despliegue Canario (Canary Deployment): Desvío Ponderado de Tráfico",
      "titleEn": "Canary Deployment Strategy: Weighted Traffic Splitting",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">CANARY DEPLOYMENT: TELEMETRY VALIDATION WITH MINIMAL RISK</text>\n  <!-- Incoming Users Traffic Left -->\n  <g transform=\"translate(25, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"140\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <text x=\"10\" y=\"18\" fill=\"#38bdf8\" font-size=\"8\" font-weight=\"800\">USER TRAFFIC</text>\n    <rect x=\"10\" y=\"30\" width=\"120\" height=\"50\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"16\" y=\"46\" fill=\"#ffffff\" font-size=\"7\">10,000 RPS</text>\n    <text x=\"16\" y=\"58\" fill=\"#93c5fd\" font-size=\"6.5\">Real Users</text>\n    <text x=\"16\" y=\"70\" fill=\"#cbd5e1\" font-size=\"6\">Ingress / Gateway</text>\n    <rect x=\"10\" y=\"90\" width=\"120\" height=\"52\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"16\" y=\"106\" fill=\"#cbd5e1\" font-size=\"6.5\">Traffic Split:</text>\n    <text x=\"16\" y=\"118\" fill=\"#38bdf8\" font-size=\"6.5\">90% v1 (Stable)</text>\n    <text x=\"16\" y=\"130\" fill=\"#f59e0b\" font-size=\"6.5\">10% v2 (Canary)</text>\n  </g>\n  <!-- Router Splitting Center -->\n  <g transform=\"translate(175, 115)\">\n    <line x1=\"0\" y1=\"-30\" x2=\"45\" y2=\"-30\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n    <polygon points=\"45,-30 37,-34 37,-26\" fill=\"#38bdf8\"/>\n    <text x=\"22\" y=\"-36\" fill=\"#38bdf8\" font-size=\"7\" font-weight=\"800\" text-anchor=\"middle\">90%</text>\n    <line x1=\"0\" y1=\"30\" x2=\"45\" y2=\"30\" stroke=\"#f59e0b\" stroke-width=\"2.5\"/>\n    <polygon points=\"45,30 37,26 37,34\" fill=\"#f59e0b\"/>\n    <text x=\"22\" y=\"24\" fill=\"#fbbf24\" font-size=\"7\" font-weight=\"800\" text-anchor=\"middle\">10%</text>\n  </g>\n  <!-- Versions Destinations Right -->\n  <g transform=\"translate(230, 45)\">\n    <!-- Version 1 Stable -->\n    <rect x=\"0\" y=\"0\" width=\"220\" height=\"70\" rx=\"5\" fill=\"#1e3a5f\" stroke=\"#38bdf8\"/>\n    <text x=\"12\" y=\"18\" fill=\"#93c5fd\" font-size=\"8\" font-weight=\"800\">VERSION 1 (Stable - 9,000 RPS)</text>\n    <text x=\"12\" y=\"32\" fill=\"#cbd5e1\" font-size=\"6.5\">• 9 Pod replicas in production</text>\n    <text x=\"12\" y=\"44\" fill=\"#34d399\" font-size=\"6.5\">✓ 5xx error rate: 0.02% | p99 latency: 45ms</text>\n    <text x=\"12\" y=\"56\" fill=\"#d1fae5\" font-size=\"6.5\">Serves 90% of traffic without degradation</text>\n    <!-- Version 2 Canary -->\n    <rect x=\"0\" y=\"85\" width=\"220\" height=\"70\" rx=\"5\" fill=\"#332a00\" stroke=\"#f59e0b\"/>\n    <text x=\"12\" y=\"103\" fill=\"#fde68a\" font-size=\"8\" font-weight=\"800\">VERSION 2 (Canary - 1,000 RPS)</text>\n    <text x=\"12\" y=\"117\" fill=\"#cbd5e1\" font-size=\"6.5\">• 1 experimental replica v2.14.0</text>\n    <text x=\"12\" y=\"129\" fill=\"#a7f3d0\" font-size=\"6.5\">Prometheus analyzes live metrics:</text>\n    <text x=\"12\" y=\"141\" fill=\"#fbbf24\" font-size=\"6.5\">If 5xx error &lt; 0.1% ➔ Promote to 25% ➔ 50% ➔ 100%</text>\n  </g>\n  <!-- Analysis Panel Far Right -->\n  <g transform=\"translate(465, 45)\">\n    <rect x=\"0\" y=\"0\" width=\"190\" height=\"155\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"190\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">CANARY ANALYSIS (Argo Rollouts)</text>\n    <rect x=\"10\" y=\"30\" width=\"170\" height=\"50\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"16\" y=\"46\" fill=\"#a7f3d0\" font-size=\"7\">Minimal Blast Radius:</text>\n    <text x=\"16\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6.5\">If v2 fails, it affects only 10%</text>\n    <text x=\"16\" y=\"70\" fill=\"#a7f3d0\" font-size=\"6.5\">of users, not 100%.</text>\n    <rect x=\"10\" y=\"90\" width=\"170\" height=\"52\" rx=\"3\" fill=\"#064e3b\"/>\n    <text x=\"16\" y=\"106\" fill=\"#ffffff\" font-size=\"7\" font-weight=\"800\">Immediate Rollback:</text>\n    <text x=\"16\" y=\"118\" fill=\"#d1fae5\" font-size=\"6.5\">On detecting an anomaly, traffic</text>\n    <text x=\"16\" y=\"130\" fill=\"#d1fae5\" font-size=\"6.5\">returns to 100% on v1 instantly.</text>\n  </g>\n</svg>",
      "caption": "Estrategia Canary Deployment: un balanceador desvía un porcentaje mínimo de tráfico real (ej. 10%) a la nueva versión para validar métricas de rendimiento y tasa de error con Prometheus. Si es exitosa, se promueve gradualmente; si falla, se aborta sin afectar al 90% restante.",
      "captionEn": "Canary deployment architecture: splits live traffic (e.g. 90/10) to validate application metrics with Prometheus. Upon success, traffic scales incrementally; upon failure, traffic reverts instantly."
    }
  },
  "topics": {
    "kcna-t-1-1": {
      "badge": "Arquitectura Kubernetes",
      "title": "Arquitectura Global de Kubernetes: Control Plane y Nodos Worker",
      "titleEn": "Kubernetes Global Architecture: Control Plane & Worker Nodes",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">KUBERNETES ARCHITECTURE: CONTROL PLANE AND WORKER NODES</text>\n  <!-- Control Plane Box -->\n  <g transform=\"translate(25, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"295\" height=\"175\" rx=\"6\" fill=\"#1e293b\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n    <rect x=\"0\" y=\"0\" width=\"295\" height=\"24\" rx=\"6\" fill=\"#1d4ed8\"/>\n    <text x=\"12\" y=\"16\" fill=\"#ffffff\" font-size=\"9\" font-weight=\"800\">CONTROL PLANE</text>\n    <!-- kube-apiserver -->\n    <rect x=\"15\" y=\"34\" width=\"265\" height=\"32\" rx=\"4\" fill=\"#0f172a\" stroke=\"#60a5fa\"/>\n    <text x=\"25\" y=\"49\" fill=\"#93c5fd\" font-size=\"8.5\" font-weight=\"800\">kube-apiserver</text>\n    <text x=\"25\" y=\"60\" fill=\"#cbd5e1\" font-size=\"7\">REST gateway · Authentication and Validation</text>\n    <!-- etcd -->\n    <rect x=\"15\" y=\"74\" width=\"125\" height=\"42\" rx=\"4\" fill=\"#0f172a\" stroke=\"#a78bfa\"/>\n    <text x=\"23\" y=\"90\" fill=\"#c4b5fd\" font-size=\"8\" font-weight=\"800\">etcd (Raft)</text>\n    <text x=\"23\" y=\"102\" fill=\"#94a3b8\" font-size=\"6.5\">Key-value store</text>\n    <text x=\"23\" y=\"111\" fill=\"#94a3b8\" font-size=\"6.5\">Only client: apiserver</text>\n    <!-- kube-scheduler -->\n    <rect x=\"155\" y=\"74\" width=\"125\" height=\"42\" rx=\"4\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"163\" y=\"90\" fill=\"#7dd3fc\" font-size=\"8\" font-weight=\"800\">kube-scheduler</text>\n    <text x=\"163\" y=\"102\" fill=\"#94a3b8\" font-size=\"6.5\">Filtering (Predicates)</text>\n    <text x=\"163\" y=\"111\" fill=\"#94a3b8\" font-size=\"6.5\">Scoring</text>\n    <!-- kube-controller-manager -->\n    <rect x=\"15\" y=\"124\" width=\"265\" height=\"38\" rx=\"4\" fill=\"#0f172a\" stroke=\"#34d399\"/>\n    <text x=\"25\" y=\"139\" fill=\"#6ee7b7\" font-size=\"8\" font-weight=\"800\">kube-controller-manager &amp; cloud-controller-manager</text>\n    <text x=\"25\" y=\"151\" fill=\"#cbd5e1\" font-size=\"7\">Continuous reconciliation: Node, Deployment, ReplicaSet, Cloud LB</text>\n  </g>\n  <!-- Center Link -->\n  <g transform=\"translate(325, 110)\">\n    <line x1=\"0\" y1=\"0\" x2=\"30\" y2=\"0\" stroke=\"#38bdf8\" stroke-width=\"2\" stroke-dasharray=\"3,3\"/>\n    <polygon points=\"30,0 24,-4 24,4\" fill=\"#38bdf8\"/>\n    <polygon points=\"0,0 6,-4 6,4\" fill=\"#38bdf8\"/>\n    <text x=\"15\" y=\"-6\" fill=\"#38bdf8\" font-size=\"7\" font-weight=\"700\" text-anchor=\"middle\">HTTPS</text>\n  </g>\n  <!-- Worker Node Box -->\n  <g transform=\"translate(360, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"295\" height=\"175\" rx=\"6\" fill=\"#1e293b\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n    <rect x=\"0\" y=\"0\" width=\"295\" height=\"24\" rx=\"6\" fill=\"#047857\"/>\n    <text x=\"12\" y=\"16\" fill=\"#ffffff\" font-size=\"9\" font-weight=\"800\">WORKER NODE</text>\n    <!-- kubelet -->\n    <rect x=\"15\" y=\"34\" width=\"125\" height=\"42\" rx=\"4\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"23\" y=\"50\" fill=\"#a7f3d0\" font-size=\"8\" font-weight=\"800\">kubelet</text>\n    <text x=\"23\" y=\"62\" fill=\"#94a3b8\" font-size=\"6.5\">Node agent</text>\n    <text x=\"23\" y=\"71\" fill=\"#94a3b8\" font-size=\"6.5\">Watches PodSpecs</text>\n    <!-- kube-proxy -->\n    <rect x=\"155\" y=\"34\" width=\"125\" height=\"42\" rx=\"4\" fill=\"#0f172a\" stroke=\"#f59e0b\"/>\n    <text x=\"163\" y=\"50\" fill=\"#fde68a\" font-size=\"8\" font-weight=\"800\">kube-proxy</text>\n    <text x=\"163\" y=\"62\" fill=\"#94a3b8\" font-size=\"6.5\">iptables / IPVS</text>\n    <text x=\"163\" y=\"71\" fill=\"#94a3b8\" font-size=\"6.5\">Service routing</text>\n    <!-- CRI Runtime -->\n    <rect x=\"15\" y=\"84\" width=\"265\" height=\"38\" rx=\"4\" fill=\"#0f172a\" stroke=\"#06b6d4\"/>\n    <text x=\"25\" y=\"99\" fill=\"#67e8f9\" font-size=\"8\" font-weight=\"800\">Container Runtime (CRI: containerd / CRI-O)</text>\n    <text x=\"25\" y=\"111\" fill=\"#cbd5e1\" font-size=\"7\">Pulls OCI images and runs containers via runc</text>\n    <!-- Pods in Node -->\n    <g transform=\"translate(15, 128)\">\n      <rect x=\"0\" y=\"0\" width=\"80\" height=\"34\" rx=\"3\" fill=\"#064e3b\" stroke=\"#34d399\"/>\n      <text x=\"10\" y=\"15\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">Pod 1 (App)</text>\n      <text x=\"10\" y=\"26\" fill=\"#cbd5e1\" font-size=\"6.5\">IP: 10.244.1.5</text>\n      <rect x=\"92\" y=\"0\" width=\"80\" height=\"34\" rx=\"3\" fill=\"#064e3b\" stroke=\"#34d399\"/>\n      <text x=\"102\" y=\"15\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">Pod 2 (API)</text>\n      <text x=\"102\" y=\"26\" fill=\"#cbd5e1\" font-size=\"6.5\">IP: 10.244.1.6</text>\n      <rect x=\"184\" y=\"0\" width=\"81\" height=\"34\" rx=\"3\" fill=\"#064e3b\" stroke=\"#34d399\"/>\n      <text x=\"194\" y=\"15\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">Pod 3 (DB)</text>\n      <text x=\"194\" y=\"26\" fill=\"#cbd5e1\" font-size=\"6.5\">IP: 10.244.1.7</text>\n    </g>\n  </g>\n</svg>",
      "caption": "El Control Plane centraliza la toma de decisiones: kube-apiserver es el único cliente de etcd, mientras kube-scheduler y controller-manager orquestan el estado. En los nodos worker, kubelet y CRI ejecutan los pods y kube-proxy mantiene el reenvío de tráfico.",
      "captionEn": "Control Plane centralizes cluster orchestration: kube-apiserver acts as the sole etcd client, while scheduler and controller-manager reconcile state. Worker nodes run kubelet, CRI container runtime, and kube-proxy."
    },
    "kcna-t-1-2": {
      "badge": "Workloads & Primitivas",
      "title": "Jerarquía de Cargas de Trabajo: Deployments, StatefulSets y DaemonSets",
      "titleEn": "Kubernetes Workload Hierarchy: Deployments, StatefulSets & DaemonSets",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">WORKLOAD HIERARCHY AND CORE PRIMITIVES</text>\n  <!-- Deployment -> ReplicaSet -> Pods -->\n  <g transform=\"translate(25, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#3b82f6\"/>\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"22\" rx=\"5\" fill=\"#1d4ed8\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">Deployment (Stateless)</text>\n    <rect x=\"12\" y=\"30\" width=\"176\" height=\"30\" rx=\"3\" fill=\"#0f172a\" stroke=\"#60a5fa\"/>\n    <text x=\"20\" y=\"45\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"700\">Deployment: web-app</text>\n    <text x=\"20\" y=\"54\" fill=\"#cbd5e1\" font-size=\"6.5\">Version and rollout management</text>\n    <!-- Arrow -->\n    <line x1=\"100\" y1=\"60\" x2=\"100\" y2=\"72\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n    <polygon points=\"100,72 97,67 103,67\" fill=\"#60a5fa\"/>\n    <rect x=\"12\" y=\"74\" width=\"176\" height=\"30\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"20\" y=\"89\" fill=\"#7dd3fc\" font-size=\"7.5\" font-weight=\"700\">ReplicaSet (Hash v2)</text>\n    <text x=\"20\" y=\"98\" fill=\"#cbd5e1\" font-size=\"6.5\">Guarantees replicas: 3</text>\n    <!-- Arrow -->\n    <line x1=\"100\" y1=\"104\" x2=\"100\" y2=\"116\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n    <polygon points=\"100,116 97,111 103,111\" fill=\"#38bdf8\"/>\n    <!-- Pods -->\n    <g transform=\"translate(12, 118)\">\n      <rect x=\"0\" y=\"0\" width=\"54\" height=\"46\" rx=\"3\" fill=\"#064e3b\" stroke=\"#34d399\"/>\n      <text x=\"6\" y=\"16\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"700\">Pod 1</text>\n      <text x=\"6\" y=\"28\" fill=\"#cbd5e1\" font-size=\"6\">web-x1</text>\n      <text x=\"6\" y=\"38\" fill=\"#34d399\" font-size=\"6\">Ready</text>\n      <rect x=\"61\" y=\"0\" width=\"54\" height=\"46\" rx=\"3\" fill=\"#064e3b\" stroke=\"#34d399\"/>\n      <text x=\"67\" y=\"16\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"700\">Pod 2</text>\n      <text x=\"67\" y=\"28\" fill=\"#cbd5e1\" font-size=\"6\">web-x2</text>\n      <text x=\"67\" y=\"38\" fill=\"#34d399\" font-size=\"6\">Ready</text>\n      <rect x=\"122\" y=\"0\" width=\"54\" height=\"46\" rx=\"3\" fill=\"#064e3b\" stroke=\"#34d399\"/>\n      <text x=\"128\" y=\"16\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"700\">Pod 3</text>\n      <text x=\"128\" y=\"28\" fill=\"#cbd5e1\" font-size=\"6\">web-x3</text>\n      <text x=\"128\" y=\"38\" fill=\"#34d399\" font-size=\"6\">Ready</text>\n    </g>\n  </g>\n  <!-- StatefulSet Box -->\n  <g transform=\"translate(240, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#a78bfa\"/>\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"22\" rx=\"5\" fill=\"#6d28d9\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">StatefulSet (Stateful)</text>\n    <rect x=\"12\" y=\"30\" width=\"176\" height=\"34\" rx=\"3\" fill=\"#0f172a\" stroke=\"#c4b5fd\"/>\n    <text x=\"20\" y=\"45\" fill=\"#ddd6fe\" font-size=\"7.5\" font-weight=\"700\">StatefulSet: db-cluster</text>\n    <text x=\"20\" y=\"56\" fill=\"#cbd5e1\" font-size=\"6.5\">Fixed names and strict order</text>\n    <!-- Ordinal Pods -->\n    <g transform=\"translate(12, 74)\">\n      <rect x=\"0\" y=\"0\" width=\"176\" height=\"40\" rx=\"3\" fill=\"#2e1065\" stroke=\"#a78bfa\"/>\n      <text x=\"10\" y=\"17\" fill=\"#f5d0fe\" font-size=\"7.5\" font-weight=\"700\">db-0 (Primary) + PVC-0</text>\n      <text x=\"10\" y=\"30\" fill=\"#c4b5fd\" font-size=\"6.5\">DNS: db-0.db-svc.default · Dedicated PV</text>\n    </g>\n    <g transform=\"translate(12, 122)\">\n      <rect x=\"0\" y=\"0\" width=\"176\" height=\"42\" rx=\"3\" fill=\"#2e1065\" stroke=\"#a78bfa\"/>\n      <text x=\"10\" y=\"17\" fill=\"#f5d0fe\" font-size=\"7.5\" font-weight=\"700\">db-1 (Replica) + PVC-1</text>\n      <text x=\"10\" y=\"30\" fill=\"#c4b5fd\" font-size=\"6.5\">DNS: db-1.db-svc.default · Dedicated PV</text>\n    </g>\n  </g>\n  <!-- DaemonSet & Jobs Box -->\n  <g transform=\"translate(455, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">DaemonSet &amp; Batch Jobs</text>\n    <!-- DaemonSet -->\n    <rect x=\"12\" y=\"30\" width=\"176\" height=\"58\" rx=\"3\" fill=\"#0f172a\" stroke=\"#34d399\"/>\n    <text x=\"20\" y=\"46\" fill=\"#6ee7b7\" font-size=\"7.5\" font-weight=\"700\">DaemonSet (1 per Node)</text>\n    <text x=\"20\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6.5\">• Fluentd / Promtail (Logs)</text>\n    <text x=\"20\" y=\"68\" fill=\"#cbd5e1\" font-size=\"6.5\">• node-exporter (Metrics)</text>\n    <text x=\"20\" y=\"78\" fill=\"#cbd5e1\" font-size=\"6.5\">• CNI kube-flannel / cilium</text>\n    <!-- Job / CronJob -->\n    <rect x=\"12\" y=\"98\" width=\"176\" height=\"66\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f59e0b\"/>\n    <text x=\"20\" y=\"114\" fill=\"#fde68a\" font-size=\"7.5\" font-weight=\"700\">Job &amp; CronJob (Batch)</text>\n    <text x=\"20\" y=\"126\" fill=\"#cbd5e1\" font-size=\"6.5\">• Runs to completion (code 0)</text>\n    <text x=\"20\" y=\"137\" fill=\"#cbd5e1\" font-size=\"6.5\">• CronJob schedules using cron syntax</text>\n    <text x=\"20\" y=\"148\" fill=\"#cbd5e1\" font-size=\"6.5\">• restartPolicy: OnFailure | Never</text>\n  </g>\n</svg>",
      "caption": "Jerarquía de cargas en Kubernetes: Deployments gestionan ReplicaSets para apps stateless; StatefulSets aportan identidades ordinales y persistencia dedicada; DaemonSets ejecutan un pod por nodo; y Jobs gestionan tareas batch.",
      "captionEn": "Kubernetes workload architecture: Deployments manage ReplicaSets for stateless services; StatefulSets provide ordered identities and dedicated storage; DaemonSets run one pod per node; Jobs run batch tasks."
    },
    "kcna-t-2-1": {
      "badge": "Scheduling & Recursos",
      "title": "Gestión de Recursos y Fases del Ciclo de Vida del Pod",
      "titleEn": "Resource Allocation, QoS Classes & Pod Lifecycle",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">RESOURCES, QOS CLASSES AND POD LIFECYCLE</text>\n  <!-- Left: Requests vs Limits -->\n  <g transform=\"translate(25, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"300\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <text x=\"14\" y=\"20\" fill=\"#38bdf8\" font-size=\"8.5\" font-weight=\"800\">REQUESTS VS LIMITS &amp; QOS CLASSES</text>\n    <!-- Bar Diagram -->\n    <rect x=\"14\" y=\"32\" width=\"272\" height=\"60\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <!-- Requests bar -->\n    <rect x=\"20\" y=\"44\" width=\"120\" height=\"20\" rx=\"2\" fill=\"#10b981\"/>\n    <text x=\"26\" y=\"57\" fill=\"#ffffff\" font-size=\"7\" font-weight=\"700\">requests (Guarantee)</text>\n    <!-- Limits bar -->\n    <rect x=\"140\" y=\"44\" width=\"90\" height=\"20\" rx=\"2\" fill=\"#f59e0b\"/>\n    <text x=\"145\" y=\"57\" fill=\"#ffffff\" font-size=\"7\" font-weight=\"700\">limits (cgroup ceiling)</text>\n    <line x1=\"230\" y1=\"36\" x2=\"230\" y2=\"72\" stroke=\"#ef4444\" stroke-width=\"2\" stroke-dasharray=\"2,2\"/>\n    <text x=\"14\" y=\"84\" fill=\"#94a3b8\" font-size=\"6.5\">CPU &gt; limits ➔ CFS Throttling | Mem &gt; limits ➔ OOMKilled (137)</text>\n    <!-- QoS list -->\n    <g transform=\"translate(14, 100)\">\n      <rect x=\"0\" y=\"0\" width=\"272\" height=\"20\" rx=\"2\" fill=\"#064e3b\"/>\n      <text x=\"8\" y=\"14\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"700\">1. Guaranteed: requests == limits (identical CPU and Memory)</text>\n      <rect x=\"0\" y=\"24\" width=\"272\" height=\"20\" rx=\"2\" fill=\"#1e3a5f\"/>\n      <text x=\"8\" y=\"38\" fill=\"#93c5fd\" font-size=\"7\" font-weight=\"700\">2. Burstable: at least one request/limit configured</text>\n      <rect x=\"0\" y=\"48\" width=\"272\" height=\"20\" rx=\"2\" fill=\"#450a0a\"/>\n      <text x=\"8\" y=\"62\" fill=\"#fca5a5\" font-size=\"7\" font-weight=\"700\">3. BestEffort: no requests or limits (first to be evicted)</text>\n    </g>\n  </g>\n  <!-- Right: Health Probes & Lifecycle -->\n  <g transform=\"translate(350, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <text x=\"14\" y=\"20\" fill=\"#34d399\" font-size=\"8.5\" font-weight=\"800\">HEALTH PROBES</text>\n    <!-- startupProbe -->\n    <rect x=\"14\" y=\"32\" width=\"277\" height=\"38\" rx=\"3\" fill=\"#0f172a\" stroke=\"#a78bfa\"/>\n    <text x=\"24\" y=\"47\" fill=\"#c4b5fd\" font-size=\"8\" font-weight=\"800\">startupProbe (Initialization)</text>\n    <text x=\"24\" y=\"59\" fill=\"#cbd5e1\" font-size=\"7\">Inhibits liveness and readiness during slow startups.</text>\n    <!-- readinessProbe -->\n    <rect x=\"14\" y=\"78\" width=\"277\" height=\"38\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"24\" y=\"93\" fill=\"#7dd3fc\" font-size=\"8\" font-weight=\"800\">readinessProbe (Traffic)</text>\n    <text x=\"24\" y=\"105\" fill=\"#cbd5e1\" font-size=\"7\">If it fails: Pod is NOT restarted; it is removed from Service Endpoints.</text>\n    <!-- livenessProbe -->\n    <rect x=\"14\" y=\"124\" width=\"277\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#ef4444\"/>\n    <text x=\"24\" y=\"139\" fill=\"#fca5a5\" font-size=\"8\" font-weight=\"800\">livenessProbe (Container Restart)</text>\n    <text x=\"24\" y=\"151\" fill=\"#cbd5e1\" font-size=\"7\">If it fails: the kubelet kills and restarts the container (deadlocks).</text>\n  </g>\n</svg>",
      "caption": "Gestión de recursos y sondas: requests orienta el agendamiento y limits impone el techo en cgroups. Las sondas del kubelet cumplen funciones diferenciadas: startup protege arranques lentos, readiness aísla tráfico y liveness reinicia contenedores congelados.",
      "captionEn": "Resource management and health probes: requests guide scheduling while limits enforce cgroup boundaries. startupProbe protects slow boots, readinessProbe manages traffic endpoints, and livenessProbe restarts unresponsive containers."
    },
    "kcna-t-2-2": {
      "badge": "Redes & Almacenamiento",
      "title": "Redes CNI y Almacenamiento CSI: Services, Policies y PVCs",
      "titleEn": "CNI Networking & CSI Storage: Services, Policies & PVCs",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">NETWORKING MODEL (CNI) AND PERSISTENT STORAGE (CSI)</text>\n  <!-- Networking Section -->\n  <g transform=\"translate(25, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#3b82f6\"/>\n    <text x=\"14\" y=\"20\" fill=\"#60a5fa\" font-size=\"8.5\" font-weight=\"800\">CNI NETWORKING &amp; SERVICE TYPES</text>\n    <!-- Service types table -->\n    <g transform=\"translate(14, 30)\">\n      <rect x=\"0\" y=\"0\" width=\"277\" height=\"28\" rx=\"3\" fill=\"#0f172a\" stroke=\"#334155\"/>\n      <text x=\"10\" y=\"18\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"700\">ClusterIP (Default):</text>\n      <text x=\"100\" y=\"18\" fill=\"#cbd5e1\" font-size=\"7\">Internal virtual IP only within the cluster</text>\n      <rect x=\"0\" y=\"34\" width=\"277\" height=\"28\" rx=\"3\" fill=\"#0f172a\" stroke=\"#334155\"/>\n      <text x=\"10\" y=\"52\" fill=\"#fbbf24\" font-size=\"7.5\" font-weight=\"700\">NodePort:</text>\n      <text x=\"100\" y=\"52\" fill=\"#cbd5e1\" font-size=\"7\">Port 30000-32767 on each node's IP</text>\n      <rect x=\"0\" y=\"68\" width=\"277\" height=\"28\" rx=\"3\" fill=\"#0f172a\" stroke=\"#334155\"/>\n      <text x=\"10\" y=\"86\" fill=\"#34d399\" font-size=\"7.5\" font-weight=\"700\">LoadBalancer:</text>\n      <text x=\"100\" y=\"86\" fill=\"#cbd5e1\" font-size=\"7\">Provisions a public/private cloud load balancer</text>\n      <!-- NetworkPolicy card -->\n      <rect x=\"0\" y=\"104\" width=\"277\" height=\"30\" rx=\"3\" fill=\"#312e81\" stroke=\"#818cf8\"/>\n      <text x=\"10\" y=\"122\" fill=\"#c7d2fe\" font-size=\"7.5\" font-weight=\"700\">NetworkPolicy (L3/L4):</text>\n      <text x=\"115\" y=\"122\" fill=\"#e0e7ff\" font-size=\"7\">Default-deny + Ingress/Egress filtering</text>\n    </g>\n  </g>\n  <!-- Storage CSI Section -->\n  <g transform=\"translate(350, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <text x=\"14\" y=\"20\" fill=\"#34d399\" font-size=\"8.5\" font-weight=\"800\">DYNAMIC STORAGE (CSI)</text>\n    <!-- Storage workflow -->\n    <g transform=\"translate(14, 30)\">\n      <rect x=\"0\" y=\"0\" width=\"277\" height=\"30\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n      <text x=\"10\" y=\"14\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">StorageClass</text>\n      <text x=\"10\" y=\"23\" fill=\"#94a3b8\" font-size=\"6.5\">Defines CSI provisioner (e.g. ebs.csi.aws.com, standard)</text>\n      <line x1=\"138\" y1=\"30\" x2=\"138\" y2=\"40\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n      <polygon points=\"138,40 135,35 141,35\" fill=\"#10b981\"/>\n      <rect x=\"0\" y=\"42\" width=\"277\" height=\"30\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n      <text x=\"10\" y=\"56\" fill=\"#7dd3fc\" font-size=\"7.5\" font-weight=\"700\">PersistentVolumeClaim (PVC)</text>\n      <text x=\"10\" y=\"66\" fill=\"#94a3b8\" font-size=\"6.5\">User request: 50Gi · AccessMode (RWO/ROX/RWX)</text>\n      <line x1=\"138\" y1=\"72\" x2=\"138\" y2=\"82\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\n      <polygon points=\"138,82 135,77 141,77\" fill=\"#38bdf8\"/>\n      <rect x=\"0\" y=\"84\" width=\"277\" height=\"30\" rx=\"3\" fill=\"#0f172a\" stroke=\"#c084fc\"/>\n      <text x=\"10\" y=\"98\" fill=\"#e9d5ff\" font-size=\"7.5\" font-weight=\"700\">Bound PersistentVolume (PV)</text>\n      <text x=\"10\" y=\"108\" fill=\"#94a3b8\" font-size=\"6.5\">Actual volume provisioned by the cloud provider</text>\n      <!-- Access modes badge -->\n      <rect x=\"0\" y=\"118\" width=\"277\" height=\"18\" rx=\"2\" fill=\"#064e3b\"/>\n      <text x=\"10\" y=\"130\" fill=\"#a7f3d0\" font-size=\"6.5\" font-weight=\"700\">Modes: RWO (1 node) · ROX (multiple read) · RWX (multiple read/write NFS)</text>\n    </g>\n  </g>\n</svg>",
      "caption": "Redes CNI y almacenamiento CSI: los Services proporcionan IPs virtuales estables y balanceo interno o externo. En almacenamiento, PVC solicita capacidad y una StorageClass interactúa con el driver CSI para aprovisionar el PV dinámicamente.",
      "captionEn": "CNI Networking and CSI Storage: Services provide stable virtual IPs and load balancing. In storage, PVCs declare capacity requirements and StorageClasses invoke CSI drivers to provision PVs dynamically."
    },
    "kcna-t-3-1": {
      "badge": "Ecosistema CNCF",
      "title": "Arquitectura Cloud Native y Niveles de Graduación CNCF",
      "titleEn": "Cloud Native Architecture & CNCF Project Graduation Tiers",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">CLOUD NATIVE ARCHITECTURE AND CNCF GRADUATION LEVELS</text>\n  <!-- Left: 12-Factor & Cloud Native -->\n  <g transform=\"translate(25, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#3b82f6\"/>\n    <text x=\"14\" y=\"20\" fill=\"#60a5fa\" font-size=\"8.5\" font-weight=\"800\">CLOUD NATIVE PRINCIPLES (12-FACTOR)</text>\n    <g transform=\"translate(14, 30)\">\n      <rect x=\"0\" y=\"0\" width=\"277\" height=\"28\" rx=\"3\" fill=\"#0f172a\" stroke=\"#334155\"/>\n      <text x=\"10\" y=\"14\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"700\">Containers &amp; Microservices:</text>\n      <text x=\"10\" y=\"23\" fill=\"#cbd5e1\" font-size=\"6.5\">Reproducible packaging and functional decoupling</text>\n      <rect x=\"0\" y=\"34\" width=\"277\" height=\"28\" rx=\"3\" fill=\"#0f172a\" stroke=\"#334155\"/>\n      <text x=\"10\" y=\"48\" fill=\"#34d399\" font-size=\"7.5\" font-weight=\"700\">Immutable Infrastructure:</text>\n      <text x=\"10\" y=\"57\" fill=\"#cbd5e1\" font-size=\"6.5\">Servers are never modified in place; they are replaced</text>\n      <rect x=\"0\" y=\"68\" width=\"277\" height=\"28\" rx=\"3\" fill=\"#0f172a\" stroke=\"#334155\"/>\n      <text x=\"10\" y=\"82\" fill=\"#fbbf24\" font-size=\"7.5\" font-weight=\"700\">Declarative APIs &amp; Resilience:</text>\n      <text x=\"10\" y=\"91\" fill=\"#cbd5e1\" font-size=\"6.5\">Continuous reconciliation of desired state</text>\n      <rect x=\"0\" y=\"102\" width=\"277\" height=\"30\" rx=\"3\" fill=\"#0f172a\" stroke=\"#334155\"/>\n      <text x=\"10\" y=\"116\" fill=\"#f43f5e\" font-size=\"7.5\" font-weight=\"700\">Configuration &amp; Logs (12-Factor):</text>\n      <text x=\"10\" y=\"126\" fill=\"#cbd5e1\" font-size=\"6.5\">Config in environment variables · Logs as a continuous stream to stdout</text>\n    </g>\n  </g>\n  <!-- Right: CNCF Graduation Pyramid -->\n  <g transform=\"translate(350, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"305\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <text x=\"14\" y=\"20\" fill=\"#34d399\" font-size=\"8.5\" font-weight=\"800\">CNCF MATURITY LEVELS</text>\n    <g transform=\"translate(14, 30)\">\n      <!-- Graduated -->\n      <rect x=\"0\" y=\"0\" width=\"277\" height=\"42\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n      <text x=\"12\" y=\"16\" fill=\"#a7f3d0\" font-size=\"8\" font-weight=\"800\">GRADUATED (Highest Maturity &amp; Audit)</text>\n      <text x=\"12\" y=\"28\" fill=\"#ffffff\" font-size=\"7\">Kubernetes, Prometheus, Envoy, Helm, containerd,</text>\n      <text x=\"12\" y=\"38\" fill=\"#ffffff\" font-size=\"7\">CoreDNS, Jaeger, Fluentd, OpenTelemetry, Argo</text>\n      <!-- Incubating -->\n      <rect x=\"0\" y=\"48\" width=\"277\" height=\"42\" rx=\"3\" fill=\"#1e3a5f\" stroke=\"#38bdf8\"/>\n      <text x=\"12\" y=\"64\" fill=\"#93c5fd\" font-size=\"8\" font-weight=\"800\">INCUBATING (Production Adoption)</text>\n      <text x=\"12\" y=\"76\" fill=\"#cbd5e1\" font-size=\"7\">gRPC, Cilium, Dapr, Notary, Emissary-ingress,</text>\n      <text x=\"12\" y=\"86\" fill=\"#cbd5e1\" font-size=\"7\">KEDA, Litmus, Cortex, Thanos</text>\n      <!-- Sandbox -->\n      <rect x=\"0\" y=\"96\" width=\"277\" height=\"40\" rx=\"3\" fill=\"#332a00\" stroke=\"#f59e0b\"/>\n      <text x=\"12\" y=\"112\" fill=\"#fde68a\" font-size=\"8\" font-weight=\"800\">SANDBOX (Initial Experimental Phase)</text>\n      <text x=\"12\" y=\"124\" fill=\"#cbd5e1\" font-size=\"7\">Early projects under community evaluation</text>\n      <text x=\"12\" y=\"133\" fill=\"#cbd5e1\" font-size=\"7\">OpenFeature, Telepresence, KubeVela</text>\n    </g>\n  </g>\n</svg>",
      "caption": "Ecosistema CNCF: principios de inmutabilidad y 12-factor rigen las arquitecturas cloud native. Los proyectos progresan desde Sandbox (experimental) e Incubating (adopción real) hasta Graduated (máxima madurez, seguridad auditada y gobernanza neutral).",
      "captionEn": "CNCF ecosystem: immutability and 12-factor principles drive cloud native architectures. Projects advance through Sandbox (experimental), Incubating (production proven), to Graduated (fully mature, audited security)."
    },
    "kcna-t-3-2": {
      "badge": "Service Mesh & Seguridad",
      "title": "Arquitectura de Service Mesh, Políticas RBAC y Gateway API",
      "titleEn": "Service Mesh Architecture, RBAC Policies & Gateway API",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">SERVICE MESH (mTLS), RBAC AND EVOLUTION TO GATEWAY API</text>\n  <!-- Service Mesh Left -->\n  <g transform=\"translate(25, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"315\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#8b5cf6\"/>\n    <text x=\"14\" y=\"20\" fill=\"#c084fc\" font-size=\"8.5\" font-weight=\"800\">SERVICE MESH: DATA PLANE VS CONTROL PLANE</text>\n    <!-- Control plane Istio -->\n    <rect x=\"14\" y=\"28\" width=\"287\" height=\"28\" rx=\"3\" fill=\"#2e1065\" stroke=\"#a78bfa\"/>\n    <text x=\"24\" y=\"46\" fill=\"#f5d0fe\" font-size=\"7.5\" font-weight=\"700\">Control Plane (Istio / Linkerd): Certificate and policy issuance</text>\n    <!-- Two pods communicating with Envoy sidecars -->\n    <g transform=\"translate(14, 64)\">\n      <!-- Pod A -->\n      <rect x=\"0\" y=\"0\" width=\"120\" height=\"72\" rx=\"4\" fill=\"#0f172a\" stroke=\"#3b82f6\"/>\n      <text x=\"10\" y=\"16\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"700\">Frontend Pod</text>\n      <rect x=\"10\" y=\"24\" width=\"100\" height=\"20\" rx=\"2\" fill=\"#1d4ed8\"/>\n      <text x=\"16\" y=\"37\" fill=\"#ffffff\" font-size=\"6.5\">App Container</text>\n      <rect x=\"10\" y=\"48\" width=\"100\" height=\"18\" rx=\"2\" fill=\"#7c3aed\"/>\n      <text x=\"16\" y=\"60\" fill=\"#ffffff\" font-size=\"6.5\">Envoy Sidecar</text>\n      <!-- mTLS Connection Arrow -->\n      <line x1=\"120\" y1=\"57\" x2=\"167\" y2=\"57\" stroke=\"#34d399\" stroke-width=\"2\"/>\n      <polygon points=\"167,57 161,53 161,61\" fill=\"#34d399\"/>\n      <text x=\"143\" y=\"50\" fill=\"#34d399\" font-size=\"6\" font-weight=\"700\" text-anchor=\"middle\">mTLS</text>\n      <!-- Pod B -->\n      <rect x=\"167\" y=\"0\" width=\"120\" height=\"72\" rx=\"4\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n      <text x=\"177\" y=\"16\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">Backend Pod</text>\n      <rect x=\"177\" y=\"24\" width=\"100\" height=\"20\" rx=\"2\" fill=\"#047857\"/>\n      <text x=\"183\" y=\"37\" fill=\"#ffffff\" font-size=\"6.5\">App Container</text>\n      <rect x=\"177\" y=\"48\" width=\"100\" height=\"18\" rx=\"2\" fill=\"#7c3aed\"/>\n      <text x=\"183\" y=\"60\" fill=\"#ffffff\" font-size=\"6.5\">Envoy Sidecar</text>\n    </g>\n    <!-- Features badge -->\n    <rect x=\"14\" y=\"144\" width=\"287\" height=\"22\" rx=\"2\" fill=\"#0f172a\" stroke=\"#334155\"/>\n    <text x=\"20\" y=\"158\" fill=\"#cbd5e1\" font-size=\"6.5\">Benefits: Transparent mTLS encryption · Retries / Circuit Breaker · W3C Traces</text>\n  </g>\n  <!-- RBAC and Gateway API Right -->\n  <g transform=\"translate(355, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"300\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <text x=\"14\" y=\"20\" fill=\"#38bdf8\" font-size=\"8.5\" font-weight=\"800\">RBAC &amp; GATEWAY API</text>\n    <!-- RBAC breakdown -->\n    <g transform=\"translate(14, 28)\">\n      <rect x=\"0\" y=\"0\" width=\"272\" height=\"58\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n      <text x=\"10\" y=\"16\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"700\">RBAC Model (Access Control):</text>\n      <text x=\"10\" y=\"28\" fill=\"#cbd5e1\" font-size=\"6.5\">• Role &amp; RoleBinding: specific namespace scope</text>\n      <text x=\"10\" y=\"38\" fill=\"#cbd5e1\" font-size=\"6.5\">• ClusterRole &amp; ClusterRoleBinding: global cluster scope</text>\n      <text x=\"10\" y=\"48\" fill=\"#cbd5e1\" font-size=\"6.5\">• ServiceAccount: identity for processes inside Pods</text>\n    </g>\n    <!-- Gateway API breakdown -->\n    <g transform=\"translate(14, 94)\">\n      <rect x=\"0\" y=\"0\" width=\"272\" height=\"72\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n      <text x=\"10\" y=\"16\" fill=\"#fde68a\" font-size=\"7.5\" font-weight=\"700\">Gateway API (Role-Oriented Design):</text>\n      <text x=\"10\" y=\"30\" fill=\"#cbd5e1\" font-size=\"6.5\">• GatewayClass: infrastructure administrator (provider)</text>\n      <text x=\"10\" y=\"42\" fill=\"#cbd5e1\" font-size=\"6.5\">• Gateway: network operator (ports, domains and certificates)</text>\n      <text x=\"10\" y=\"54\" fill=\"#cbd5e1\" font-size=\"6.5\">• HTTPRoute: application developer (L7 rules and filters)</text>\n    </g>\n  </g>\n</svg>",
      "caption": "Service Mesh desacopla la red mediante sidecars Envoy para mTLS y métricas. En seguridad, RBAC restringe permisos por namespace o clúster. La Gateway API evoluciona Ingress separando responsabilidades entre infra, operaciones y desarrolladores.",
      "captionEn": "Service Mesh offloads network routing via Envoy sidecars for mTLS and metrics. RBAC controls API access by namespace or cluster. Gateway API modernizes Ingress with role-oriented separation."
    },
    "kcna-t-4-1": {
      "badge": "Tres Pilares Observabilidad",
      "title": "Los Tres Pilares de la Observabilidad y Ecosistema OpenTelemetry",
      "titleEn": "Three Pillars of Observability & OpenTelemetry Ecosystem",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">THE THREE PILLARS OF OBSERVABILITY &amp; OPENTELEMETRY (OTEL)</text>\n  <!-- Column 1: Metrics -->\n  <g transform=\"translate(25, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"120\" rx=\"5\" fill=\"#1e293b\" stroke=\"#3b82f6\"/>\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"22\" rx=\"5\" fill=\"#1d4ed8\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">METRICS</text>\n    <text x=\"10\" y=\"40\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"700\">Aggregatable numeric values</text>\n    <text x=\"10\" y=\"54\" fill=\"#cbd5e1\" font-size=\"7\">• Real-time detection</text>\n    <text x=\"10\" y=\"66\" fill=\"#cbd5e1\" font-size=\"7\">• SLI, SLO and alert calculation</text>\n    <text x=\"10\" y=\"78\" fill=\"#cbd5e1\" font-size=\"7\">• Time series (TSDB)</text>\n    <text x=\"10\" y=\"94\" fill=\"#38bdf8\" font-size=\"7\" font-weight=\"700\">Projects: Prometheus, Thanos</text>\n    <text x=\"10\" y=\"106\" fill=\"#94a3b8\" font-size=\"6.5\">Question: What is failing now?</text>\n  </g>\n  <!-- Column 2: Logs -->\n  <g transform=\"translate(240, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"120\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">LOGS (Textual Events)</text>\n    <text x=\"10\" y=\"40\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">Timestamped records</text>\n    <text x=\"10\" y=\"54\" fill=\"#cbd5e1\" font-size=\"7\">• Forensic failure analysis</text>\n    <text x=\"10\" y=\"66\" fill=\"#cbd5e1\" font-size=\"7\">• Rich structured JSON context</text>\n    <text x=\"10\" y=\"78\" fill=\"#cbd5e1\" font-size=\"7\">• stdout/stderr in Pods</text>\n    <text x=\"10\" y=\"94\" fill=\"#34d399\" font-size=\"7\" font-weight=\"700\">Projects: Fluentd, Loki, Vector</text>\n    <text x=\"10\" y=\"106\" fill=\"#94a3b8\" font-size=\"6.5\">Question: Why did the process fail?</text>\n  </g>\n  <!-- Column 3: Traces -->\n  <g transform=\"translate(455, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"120\" rx=\"5\" fill=\"#1e293b\" stroke=\"#a78bfa\"/>\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"22\" rx=\"5\" fill=\"#6d28d9\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">TRACES (Distributed Traces)</text>\n    <text x=\"10\" y=\"40\" fill=\"#ddd6fe\" font-size=\"7.5\" font-weight=\"700\">Request journey across the network</text>\n    <text x=\"10\" y=\"54\" fill=\"#cbd5e1\" font-size=\"7\">• Latency identification</text>\n    <text x=\"10\" y=\"66\" fill=\"#cbd5e1\" font-size=\"7\">• Spans and context propagation</text>\n    <text x=\"10\" y=\"78\" fill=\"#cbd5e1\" font-size=\"7\">• Dependency graphs</text>\n    <text x=\"10\" y=\"94\" fill=\"#c084fc\" font-size=\"7\" font-weight=\"700\">Projects: Jaeger, Zipkin</text>\n    <text x=\"10\" y=\"106\" fill=\"#94a3b8\" font-size=\"6.5\">Question: Where did the time degrade?</text>\n  </g>\n  <!-- Bottom: OpenTelemetry -->\n  <g transform=\"translate(25, 168)\">\n    <rect x=\"0\" y=\"0\" width=\"630\" height=\"46\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n    <text x=\"14\" y=\"18\" fill=\"#fbbf24\" font-size=\"8.5\" font-weight=\"800\">OPENTELEMETRY (OTel) — CNCF GRADUATED STANDARD</text>\n    <text x=\"14\" y=\"32\" fill=\"#cbd5e1\" font-size=\"7\">Unifies APIs, SDKs and the <b>OTel Collector</b> to instrument and collect Metrics, Logs and Traces via an open protocol <b>OTLP</b>.</text>\n  </g>\n</svg>",
      "caption": "Los Tres Pilares de la Observabilidad responden preguntas complementarias: Métricas indican qué falla, Logs explican por qué ocurrió y Trazas revelan en qué servicio se acumuló la latencia. OpenTelemetry estandariza su recolección mediante OTLP.",
      "captionEn": "The Three Pillars of Observability answer distinct needs: Metrics detect what is failing, Logs describe why it failed, and Traces pinpoint latency bottlenecks. OpenTelemetry standardizes telemetry via OTLP."
    },
    "kcna-t-4-2": {
      "badge": "Prometheus & Metrics",
      "title": "Arquitectura de Prometheus, Alertmanager y Telemetría del Clúster",
      "titleEn": "Prometheus Architecture, Alertmanager & Cluster Telemetry",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">CLOUD NATIVE MONITORING: PROMETHEUS, CADVISOR AND ALERTMANAGER</text>\n  <!-- Targets Section -->\n  <g transform=\"translate(25, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"170\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <text x=\"10\" y=\"18\" fill=\"#38bdf8\" font-size=\"8\" font-weight=\"800\">TARGETS</text>\n    <rect x=\"10\" y=\"28\" width=\"150\" height=\"30\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"18\" y=\"42\" fill=\"#93c5fd\" font-size=\"7\" font-weight=\"700\">cAdvisor (in Kubelet)</text>\n    <text x=\"18\" y=\"51\" fill=\"#cbd5e1\" font-size=\"6\">Container CPU/Mem usage</text>\n    <rect x=\"10\" y=\"64\" width=\"150\" height=\"30\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"18\" y=\"78\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"700\">node-exporter</text>\n    <text x=\"18\" y=\"87\" fill=\"#cbd5e1\" font-size=\"6\">Host hardware, I/O, network</text>\n    <rect x=\"10\" y=\"100\" width=\"150\" height=\"30\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"18\" y=\"114\" fill=\"#fde68a\" font-size=\"7\" font-weight=\"700\">App Microservices</text>\n    <text x=\"18\" y=\"123\" fill=\"#cbd5e1\" font-size=\"6\">HTTP /metrics endpoints</text>\n    <rect x=\"10\" y=\"136\" width=\"150\" height=\"30\" rx=\"3\" fill=\"#0f172a\" stroke=\"#475569\"/>\n    <text x=\"18\" y=\"150\" fill=\"#c4b5fd\" font-size=\"7\" font-weight=\"700\">K8s Control Plane</text>\n    <text x=\"18\" y=\"159\" fill=\"#cbd5e1\" font-size=\"6\">apiserver, etcd, scheduler</text>\n  </g>\n  <!-- Pull Arrow -->\n  <g transform=\"translate(198, 115)\">\n    <line x1=\"0\" y1=\"0\" x2=\"32\" y2=\"0\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n    <polygon points=\"0,0 6,-4 6,4\" fill=\"#f59e0b\"/>\n    <text x=\"16\" y=\"-6\" fill=\"#f59e0b\" font-size=\"6.5\" font-weight=\"700\" text-anchor=\"middle\">PULL</text>\n  </g>\n  <!-- Prometheus Server Center -->\n  <g transform=\"translate(235, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"220\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n    <rect x=\"0\" y=\"0\" width=\"220\" height=\"22\" rx=\"5\" fill=\"#b45309\"/>\n    <text x=\"12\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">PROMETHEUS SERVER</text>\n    <!-- TSDB -->\n    <rect x=\"12\" y=\"30\" width=\"196\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#f59e0b\"/>\n    <text x=\"20\" y=\"46\" fill=\"#fde68a\" font-size=\"7.5\" font-weight=\"700\">TSDB (Time Series DB)</text>\n    <text x=\"20\" y=\"58\" fill=\"#cbd5e1\" font-size=\"6.5\">Time series storage on local disk</text>\n    <!-- Retrieval & PromQL -->\n    <rect x=\"12\" y=\"80\" width=\"196\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"20\" y=\"96\" fill=\"#7dd3fc\" font-size=\"7.5\" font-weight=\"700\">PromQL Engine &amp; Rules</text>\n    <text x=\"20\" y=\"108\" fill=\"#cbd5e1\" font-size=\"6.5\">Functional queries: rate(), histogram_quantile()</text>\n    <!-- Service Discovery -->\n    <rect x=\"12\" y=\"130\" width=\"196\" height=\"34\" rx=\"3\" fill=\"#0f172a\" stroke=\"#34d399\"/>\n    <text x=\"20\" y=\"145\" fill=\"#6ee7b7\" font-size=\"7\" font-weight=\"700\">Kubernetes Service Discovery</text>\n    <text x=\"20\" y=\"155\" fill=\"#cbd5e1\" font-size=\"6\">Automatic discovery of Pods and Services</text>\n  </g>\n  <!-- Output Arrows -->\n  <g transform=\"translate(460, 80)\">\n    <line x1=\"0\" y1=\"0\" x2=\"30\" y2=\"0\" stroke=\"#ef4444\" stroke-width=\"2\"/>\n    <polygon points=\"30,0 24,-4 24,4\" fill=\"#ef4444\"/>\n    <text x=\"15\" y=\"-6\" fill=\"#ef4444\" font-size=\"6.5\" font-weight=\"700\" text-anchor=\"middle\">Alerts</text>\n  </g>\n  <g transform=\"translate(460, 150)\">\n    <line x1=\"0\" y1=\"0\" x2=\"30\" y2=\"0\" stroke=\"#38bdf8\" stroke-width=\"2\"/>\n    <polygon points=\"30,0 24,-4 24,4\" fill=\"#38bdf8\"/>\n    <text x=\"15\" y=\"-6\" fill=\"#38bdf8\" font-size=\"6.5\" font-weight=\"700\" text-anchor=\"middle\">PromQL</text>\n  </g>\n  <!-- Right: Alertmanager & Grafana -->\n  <g transform=\"translate(495, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"160\" height=\"82\" rx=\"5\" fill=\"#1e293b\" stroke=\"#ef4444\"/>\n    <text x=\"10\" y=\"18\" fill=\"#f87171\" font-size=\"8\" font-weight=\"800\">ALERTMANAGER</text>\n    <text x=\"10\" y=\"32\" fill=\"#cbd5e1\" font-size=\"6.5\">• Deduplication</text>\n    <text x=\"10\" y=\"44\" fill=\"#cbd5e1\" font-size=\"6.5\">• Grouping</text>\n    <text x=\"10\" y=\"56\" fill=\"#cbd5e1\" font-size=\"6.5\">• Silences and inhibition</text>\n    <text x=\"10\" y=\"68\" fill=\"#a7f3d0\" font-size=\"6.5\">➔ Slack, PagerDuty, Email</text>\n    <rect x=\"0\" y=\"93\" width=\"160\" height=\"82\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <text x=\"10\" y=\"113\" fill=\"#38bdf8\" font-size=\"8\" font-weight=\"800\">GRAFANA</text>\n    <text x=\"10\" y=\"127\" fill=\"#cbd5e1\" font-size=\"6.5\">• Interactive dashboards</text>\n    <text x=\"10\" y=\"139\" fill=\"#cbd5e1\" font-size=\"6.5\">• SLI/SLO visualization</text>\n    <text x=\"10\" y=\"151\" fill=\"#cbd5e1\" font-size=\"6.5\">• K8s cluster telemetry</text>\n    <text x=\"10\" y=\"163\" fill=\"#fde68a\" font-size=\"6.5\">➔ Trend analysis</text>\n  </g>\n</svg>",
      "caption": "Flujo de Prometheus: sondea activamente (pull HTTP) métricas de cAdvisor, node-exporter y aplicaciones. Almacena series temporales en su TSDB local y utiliza PromQL para generar tableros en Grafana y enviar alertas a Alertmanager.",
      "captionEn": "Prometheus pull telemetry architecture: actively scrapes cAdvisor, node-exporter, and application endpoints. Stores data in local TSDB and evaluates PromQL rules for Grafana dashboards and Alertmanager routing."
    },
    "kcna-t-5-1": {
      "badge": "GitOps & CI/CD",
      "title": "Ciclo de Vida de GitOps: Reconciliación Declarativa con ArgoCD",
      "titleEn": "GitOps Lifecycle: Declarative Reconciliation with ArgoCD",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">GITOPS PRINCIPLES: GIT AS SOURCE OF TRUTH AND PULL RECONCILIATION</text>\n  <!-- Git Repo Left -->\n  <g transform=\"translate(25, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"180\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f43f5e\"/>\n    <rect x=\"0\" y=\"0\" width=\"180\" height=\"22\" rx=\"5\" fill=\"#be123c\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">GIT REPOSITORY</text>\n    <text x=\"10\" y=\"40\" fill=\"#fda4af\" font-size=\"7.5\" font-weight=\"700\">Single Source of Truth</text>\n    <rect x=\"10\" y=\"50\" width=\"160\" height=\"34\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fb7185\"/>\n    <text x=\"18\" y=\"65\" fill=\"#ffffff\" font-size=\"7\">Declarative Manifests</text>\n    <text x=\"18\" y=\"75\" fill=\"#94a3b8\" font-size=\"6.5\">YAML, Helm, Kustomize</text>\n    <rect x=\"10\" y=\"92\" width=\"160\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#fb7185\"/>\n    <text x=\"18\" y=\"107\" fill=\"#ffffff\" font-size=\"7\">Immutable History</text>\n    <text x=\"18\" y=\"117\" fill=\"#cbd5e1\" font-size=\"6.5\">• Commits with authorship and signature</text>\n    <text x=\"18\" y=\"127\" fill=\"#a7f3d0\" font-size=\"6.5\">• Simple rollback with git revert</text>\n    <rect x=\"10\" y=\"142\" width=\"160\" height=\"22\" rx=\"3\" fill=\"#4c0519\"/>\n    <text x=\"16\" y=\"156\" fill=\"#fecdd3\" font-size=\"6.5\">OpenGitOps Principle 1 &amp; 2</text>\n  </g>\n  <!-- Pull Arrow Center -->\n  <g transform=\"translate(210, 115)\">\n    <line x1=\"0\" y1=\"0\" x2=\"45\" y2=\"0\" stroke=\"#38bdf8\" stroke-width=\"2.5\"/>\n    <polygon points=\"45,0 37,-5 37,5\" fill=\"#38bdf8\"/>\n    <text x=\"22\" y=\"-8\" fill=\"#38bdf8\" font-size=\"7\" font-weight=\"800\" text-anchor=\"middle\">PULL SYNC</text>\n    <text x=\"22\" y=\"15\" fill=\"#94a3b8\" font-size=\"6\" text-anchor=\"middle\">Read-only</text>\n  </g>\n  <!-- ArgoCD Operator Center-Right -->\n  <g transform=\"translate(260, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"195\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#38bdf8\"/>\n    <rect x=\"0\" y=\"0\" width=\"195\" height=\"22\" rx=\"5\" fill=\"#0284c7\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">GITOPS OPERATOR (ArgoCD / Flux)</text>\n    <text x=\"10\" y=\"38\" fill=\"#7dd3fc\" font-size=\"7.5\" font-weight=\"700\">Agent inside the Cluster</text>\n    <rect x=\"10\" y=\"46\" width=\"175\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#38bdf8\"/>\n    <text x=\"18\" y=\"62\" fill=\"#38bdf8\" font-size=\"7.5\" font-weight=\"700\">Drift Detection</text>\n    <text x=\"18\" y=\"73\" fill=\"#cbd5e1\" font-size=\"6.5\">Permanently compares:</text>\n    <text x=\"18\" y=\"82\" fill=\"#cbd5e1\" font-size=\"6.5\">Desired State vs. Actual State</text>\n    <rect x=\"10\" y=\"96\" width=\"175\" height=\"44\" rx=\"3\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n    <text x=\"18\" y=\"112\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">Self-Healing</text>\n    <text x=\"18\" y=\"123\" fill=\"#d1fae5\" font-size=\"6.5\">Reverts manual kubectl changes</text>\n    <text x=\"18\" y=\"132\" fill=\"#d1fae5\" font-size=\"6.5\">forces a match with Git</text>\n    <rect x=\"10\" y=\"146\" width=\"175\" height=\"20\" rx=\"3\" fill=\"#0c4a6e\"/>\n    <text x=\"16\" y=\"159\" fill=\"#bae6fd\" font-size=\"6.5\">No credentials exposed in CI</text>\n  </g>\n  <!-- Sync Arrow to Cluster -->\n  <g transform=\"translate(460, 115)\">\n    <line x1=\"0\" y1=\"0\" x2=\"35\" y2=\"0\" stroke=\"#10b981\" stroke-width=\"2.5\"/>\n    <polygon points=\"35,0 27,-5 27,5\" fill=\"#10b981\"/>\n    <text x=\"18\" y=\"-8\" fill=\"#10b981\" font-size=\"7\" font-weight=\"800\" text-anchor=\"middle\">APPLY</text>\n  </g>\n  <!-- Cluster State Right -->\n  <g transform=\"translate(500, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"155\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"155\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">K8S CLUSTER</text>\n    <text x=\"10\" y=\"38\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">Actual State (Synced)</text>\n    <rect x=\"10\" y=\"48\" width=\"135\" height=\"32\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"16\" y=\"62\" fill=\"#34d399\" font-size=\"7\" font-weight=\"700\">Deployments v2.4</text>\n    <text x=\"16\" y=\"73\" fill=\"#cbd5e1\" font-size=\"6\">ConfigMaps, Secrets</text>\n    <rect x=\"10\" y=\"88\" width=\"135\" height=\"32\" rx=\"3\" fill=\"#0f172a\" stroke=\"#10b981\"/>\n    <text x=\"16\" y=\"102\" fill=\"#34d399\" font-size=\"7\" font-weight=\"700\">Services &amp; Ingress</text>\n    <text x=\"16\" y=\"113\" fill=\"#cbd5e1\" font-size=\"6\">Active NetworkPolicies</text>\n    <rect x=\"10\" y=\"128\" width=\"135\" height=\"36\" rx=\"3\" fill=\"#064e3b\"/>\n    <text x=\"16\" y=\"143\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"800\">Status: Healthy</text>\n    <text x=\"16\" y=\"155\" fill=\"#d1fae5\" font-size=\"6.5\">Sync: Synced with main</text>\n  </g>\n</svg>",
      "caption": "Modelo GitOps con ArgoCD: Git es la única fuente de verdad declarativa e inmutable. El operador corre dentro del clúster extrayendo cambios (modelo pull), detectando desviaciones (drift) y reconciliando automáticamente el estado deseado.",
      "captionEn": "GitOps workflow with ArgoCD: Git serves as the single declarative source of truth. An in-cluster operator pulls state, detects configuration drift, and continuously reconciles Kubernetes resources."
    },
    "kcna-t-5-2": {
      "badge": "Entrega & Empaquetado",
      "title": "Estrategias de Despliegue: Rolling Update, Blue/Green y Canary",
      "titleEn": "Deployment Strategies: Rolling Update, Blue/Green & Canary",
      "svg": "<svg viewBox=\"0 0 680 230\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"680\" height=\"230\" rx=\"8\" fill=\"#0f172a\" stroke=\"#334155\"/>\n  <text x=\"25\" y=\"24\" fill=\"#f8fafc\" font-size=\"11\" font-weight=\"800\">CLOUD NATIVE DEPLOYMENT STRATEGIES: ROLLING, BLUE/GREEN AND CANARY</text>\n  <!-- Strategy 1: Rolling Update -->\n  <g transform=\"translate(25, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#3b82f6\"/>\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"22\" rx=\"5\" fill=\"#1d4ed8\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">ROLLING UPDATE (K8s Default)</text>\n    <text x=\"10\" y=\"40\" fill=\"#93c5fd\" font-size=\"7.5\" font-weight=\"700\">Gradual pod-by-pod replacement</text>\n    <!-- Visual Pods -->\n    <g transform=\"translate(10, 48)\">\n      <rect x=\"0\" y=\"0\" width=\"40\" height=\"30\" rx=\"2\" fill=\"#047857\" stroke=\"#10b981\"/>\n      <text x=\"8\" y=\"18\" fill=\"#ffffff\" font-size=\"6.5\">v2</text>\n      <rect x=\"45\" y=\"0\" width=\"40\" height=\"30\" rx=\"2\" fill=\"#047857\" stroke=\"#10b981\"/>\n      <text x=\"53\" y=\"18\" fill=\"#ffffff\" font-size=\"6.5\">v2</text>\n      <rect x=\"90\" y=\"0\" width=\"40\" height=\"30\" rx=\"2\" fill=\"#1e3a5f\" stroke=\"#3b82f6\"/>\n      <text x=\"98\" y=\"18\" fill=\"#ffffff\" font-size=\"6.5\">v1</text>\n      <rect x=\"135\" y=\"0\" width=\"40\" height=\"30\" rx=\"2\" fill=\"#1e3a5f\" stroke=\"#3b82f6\"/>\n      <text x=\"143\" y=\"18\" fill=\"#ffffff\" font-size=\"6.5\">v1</text>\n    </g>\n    <rect x=\"10\" y=\"88\" width=\"180\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#334155\"/>\n    <text x=\"18\" y=\"102\" fill=\"#cbd5e1\" font-size=\"6.5\">• Controls maxSurge and maxUnavailable</text>\n    <text x=\"18\" y=\"113\" fill=\"#cbd5e1\" font-size=\"6.5\">• Zero Downtime</text>\n    <text x=\"18\" y=\"124\" fill=\"#fde68a\" font-size=\"6.5\">• Temporary coexistence of v1 and v2</text>\n    <rect x=\"10\" y=\"136\" width=\"180\" height=\"28\" rx=\"3\" fill=\"#064e3b\"/>\n    <text x=\"18\" y=\"152\" fill=\"#a7f3d0\" font-size=\"7\" font-weight=\"700\">Standard Deployment strategy</text>\n  </g>\n  <!-- Strategy 2: Blue / Green -->\n  <g transform=\"translate(240, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#10b981\"/>\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"22\" rx=\"5\" fill=\"#047857\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">BLUE / GREEN</text>\n    <text x=\"10\" y=\"40\" fill=\"#a7f3d0\" font-size=\"7.5\" font-weight=\"700\">Two complete parallel environments</text>\n    <g transform=\"translate(10, 48)\">\n      <rect x=\"0\" y=\"0\" width=\"85\" height=\"30\" rx=\"2\" fill=\"#1e3a5f\" stroke=\"#3b82f6\"/>\n      <text x=\"8\" y=\"18\" fill=\"#93c5fd\" font-size=\"6.5\">Blue (v1) [100%]</text>\n      <rect x=\"95\" y=\"0\" width=\"85\" height=\"30\" rx=\"2\" fill=\"#064e3b\" stroke=\"#10b981\"/>\n      <text x=\"103\" y=\"18\" fill=\"#a7f3d0\" font-size=\"6.5\">Green (v2) [Idle]</text>\n    </g>\n    <!-- Switch arrow -->\n    <text x=\"100\" y=\"92\" fill=\"#fbbf24\" font-size=\"7\" font-weight=\"700\" text-anchor=\"middle\">Service / Router switch</text>\n    <rect x=\"10\" y=\"98\" width=\"180\" height=\"42\" rx=\"3\" fill=\"#0f172a\" stroke=\"#334155\"/>\n    <text x=\"18\" y=\"112\" fill=\"#cbd5e1\" font-size=\"6.5\">• Instant cutover to 100%</text>\n    <text x=\"18\" y=\"123\" fill=\"#cbd5e1\" font-size=\"6.5\">• Immediate rollback by reverting the selector</text>\n    <text x=\"18\" y=\"134\" fill=\"#fca5a5\" font-size=\"6.5\">• Doubles infrastructure resources</text>\n    <rect x=\"10\" y=\"146\" width=\"180\" height=\"20\" rx=\"3\" fill=\"#1e3a5f\"/>\n    <text x=\"18\" y=\"159\" fill=\"#93c5fd\" font-size=\"6.5\">Ideal for pre-cutover validation</text>\n  </g>\n  <!-- Strategy 3: Canary Deployment -->\n  <g transform=\"translate(455, 38)\">\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"175\" rx=\"5\" fill=\"#1e293b\" stroke=\"#f59e0b\"/>\n    <rect x=\"0\" y=\"0\" width=\"200\" height=\"22\" rx=\"5\" fill=\"#b45309\"/>\n    <text x=\"10\" y=\"15\" fill=\"#ffffff\" font-size=\"8.5\" font-weight=\"800\">CANARY DEPLOYMENT</text>\n    <text x=\"10\" y=\"40\" fill=\"#fde68a\" font-size=\"7.5\" font-weight=\"700\">Percentage-based traffic split</text>\n    <g transform=\"translate(10, 48)\">\n      <rect x=\"0\" y=\"0\" width=\"125\" height=\"30\" rx=\"2\" fill=\"#1e3a5f\" stroke=\"#3b82f6\"/>\n      <text x=\"10\" y=\"18\" fill=\"#93c5fd\" font-size=\"7\">v1 Stable (90%)</text>\n      <rect x=\"135\" y=\"0\" width=\"45\" height=\"30\" rx=\"2\" fill=\"#78350f\" stroke=\"#f59e0b\"/>\n      <text x=\"140\" y=\"18\" fill=\"#fde68a\" font-size=\"6.5\">Canary (10%)</text>\n    </g>\n    <rect x=\"10\" y=\"88\" width=\"180\" height=\"48\" rx=\"3\" fill=\"#0f172a\" stroke=\"#334155\"/>\n    <text x=\"18\" y=\"102\" fill=\"#cbd5e1\" font-size=\"6.5\">• Validates metrics with real users</text>\n    <text x=\"18\" y=\"113\" fill=\"#cbd5e1\" font-size=\"6.5\">• Minimal blast radius for bugs</text>\n    <text x=\"18\" y=\"124\" fill=\"#cbd5e1\" font-size=\"6.5\">• Progressive promotion: 10% ➔ 50% ➔ 100%</text>\n    <rect x=\"10\" y=\"142\" width=\"180\" height=\"22\" rx=\"3\" fill=\"#78350f\"/>\n    <text x=\"18\" y=\"156\" fill=\"#fef08a\" font-size=\"6.5\" font-weight=\"700\">Tools: Argo Rollouts, Flagger</text>\n  </g>\n</svg>",
      "caption": "Estrategias de despliegue: Rolling Update reemplaza pods progresivamente sin downtime; Blue/Green duplica entornos con conmutación del 100%; Canary enruta un porcentaje controlado de tráfico (ej. 90/10) evaluando métricas en tiempo real.",
      "captionEn": "Deployment strategies compared: Rolling Update replaces pods incrementally; Blue/Green switches 100% of traffic between duplicate environments; Canary routes a small percentage (e.g. 90/10) to validate real-user telemetry."
    }
  },
  "patterns": []
};
